window.POEM_DB=window.POEM_DB||{};POEM_DB["song_044"]={"n":"贺铸","dyn":"宋","poems":[{"t":"九日张谋父席上","f":"七言绝句","c":["浪竹低枝扫隙尘，到帘清月欲留人。","西家一斛黄华酒，沈醉吴音贺季真。"]},{"t":"九日答张谋父见招","f":"七言绝句","c":["昨夜新霜满菊丛，起来何面对西风。","白衣送酒无消息，赖有西邻张长公。"]},{"t":"丹阳客舍示曾纡公衮","f":"七言绝句","c":["眼里铅华今日见，胸中冰炭几时除。","欲知老子消怀处，静夜青灯一卷书。"]},{"t":"斗岘山马上","f":"七言绝句","c":["西来投策倦跻攀，晚叶寒华一径间。","尽日闲云不留雨，斜阳还照隔江山。"]},{"t":"东平周村驿观临川吴公题","f":"七言绝句","c":["顿辔挥毫墨尚新，碧纱从此碧生尘。","可怜庭下长杨树，犹有清阴待路人。"]},{"t":"东城马上","f":"七言绝句","c":["綵虹桥下水关东，接畛园林狭径通。","繁杏半开随半落，短墙无计碍春风。"]},{"t":"东城送客马上","f":"七言绝句","c":["向午孤烟起客樯，一陂春水两鸳鸯。","渔童解唱沧浪曲，应笑尘埃马上郎。"]},{"t":"冬夜怀寄周文清郭天辅","f":"七言绝句","c":["壁缸向灭砚生澌，仰屋重哦旧卷诗。","悬想北园闲散伴，青钱堆坐赌宫棋。"]},{"t":"北园初夏","f":"七言绝句","c":["天气清和树荫浓，冥濛薄雨湿帘栊。","蔫红半落生香在，向晚玫瑰架上风。"]},{"t":"平野堂重送江茂宗","f":"七言绝句","c":["东风南浦雨潇潇，欲去行人不自聊。","谁道垂杨攀折苦，过春犹有最长条。"]},{"t":"再涉南罗渡","f":"七言绝句","c":["滞水生苔没马蹄，涨沙隐约见金堤。","禹功寖久人无继，未信东流不复西。"]},{"t":"再游西城","f":"七言绝句","c":["柳条破眼已堪攀，鹭下城隅水一湾。","后日重来寒食近，杏花林外见青山。"]},{"t":"同张汉求宿升中院西寮","f":"七言绝句","c":["僧閤窗扉学画船，青荧灯火对床眠。","北风带雪披檐竹，浑似潇湘夜泊天。"]},{"t":"成安道中怀寄冯惟逸","f":"七言绝句","c":["苍面黄须过壮时，欲投闲去两难期。","人生自是无根物，南北东西任所之。"]},{"t":"早发斜沟道中寄王有元","f":"七言绝句","c":["处处春林有鸟啼，恨无芳酒一樽携。","何缘复得彭城梦，日日东风送我西。"]},{"t":"江夏八咏 其一 磨剑池","f":"五言绝句","c":["祖龙砺长剑，昔道此南巡。","徒挟雄铓利，湘川奈水神。"]},{"t":"江夏八咏 其二 灵竹寺","f":"五言绝句","c":["孟公泣竹地，今是布金园。","不保五亩宅，非无百代孙。"]},{"t":"江夏八咏 其八 龙穴渡","f":"五言绝句","c":["应龙昔此去，雷雨助腾伸。","旧穴潜鲛蜃，风波横要津。"]},{"t":"江夏八咏 其三 祖贯墓铭","f":"五言绝句","c":["高岸已为谷，斯人如蜕蝉。","固应留宝刻，信示当家仙。"]},{"t":"江夏八咏 其六 赵佗石","f":"五言绝句","c":["南津赵佗石，云是昔人舟。","长怀精卫志，不碍长江流。"]},{"t":"江夏八咏 其七 石镜亭","f":"五言绝句","c":["西戍夕阳晴，东城石镜明。","有山名八字，供作两眉横。"]},{"t":"江夏八咏 其五 奇章亭","f":"五言绝句","c":["亭揭奇章榜，斯民孰去思。","多惭羊叔子，涕泗岘山碑。"]},{"t":"约十客同集金山米芾元章约而不至坐中分题以元章未至分韵作诗拈阄韵应口便作滞思即罚巨觥余得章字","f":"七言绝句","c":["九客相逢思楚狂，停歌罢铗缓行觞。","座中那更添严令，分韵吟诗招阿章。"]},{"t":"自卫还徐憩永城王氏园","f":"七言绝句","c":["归路尘埃懒著鞭，北窗仰枕碧云天。","柴桑此兴无人学，负尔清风七百年。"]},{"t":"西城马上","f":"七言绝句","c":["烛冷尘消过上元，晴明风日柳初繁。","偷闲偶到西城陌，喜见青山似故园。"]},{"t":"过曹氏园马上作","f":"七言绝句","c":["香风细细出重墙，不见繁枝已断肠。","知有何人卷帘箔，卧看零落满斜阳。"]},{"t":"过澶魏被水民居二首 其一","f":"七言绝句","c":["带沙畎亩几经淤，半死黄桑绕故墟。","未必邻封政如虎，自甘十室九为鱼。"]},{"t":"初见白发示内","f":"七言绝句","c":["安能屈指计封侯，西日东风见白头。","信是色身非我有，若论身外更悠悠。"]},{"t":"吴门秋怀","f":"七言绝句","c":["吴门客鬓再经秋，城郭篮舁久倦游。","平静松江三万顷，不应无处著渔舟。"]},{"t":"局中归","f":"七言绝句","c":["心火成灰不复然，故园笑别十三年。","晚凉退食无馀事，坐与儿曹挽纸鸢。"]},{"t":"怀寄寇元弼王文举十首 其一 初别后","f":"五言绝句","c":["樽酒津亭别，还城何所投。","无情是流水，断送到南州。"]},{"t":"怀寄寇元弼王文举十首 其七 局中归","f":"五言绝句","c":["不见西街客，归来即闭门。","胡床面南树，鸟鹊啅黄昏。"]},{"t":"怀寄寇元弼王文举十首 其九 招文举","f":"五言绝句","c":["后夜溪山雪，临门望子猷。","莫因清兴尽，半道却回舟。"]},{"t":"怀寄寇元弼王文举十首 其二 过碧芦轩","f":"五言绝句","c":["东轩美风月，诗酒伴欢呼。","昨日墙阴过，依依见碧芦。"]},{"t":"怀寄寇元弼王文举十首 其八 招元弼","f":"五言绝句","c":["暑雨茅柴熟，秋风淮白肥。","留连阮校尉，何日跨驴归。"]},{"t":"怀寄寇元弼王文举十首 其十 赋后诗","f":"五言绝句","c":["偶得悲秋句，还惊旧社空。","中庭步明月，朗咏与西风。"]},{"t":"怀寄寇元弼王文举十首 其三 出小市门","f":"五言绝句","c":["小市门南路，旧游联马行。","祇从前日别，秋草一番生。"]},{"t":"怀寄寇元弼王文举十首 其五 游百步洪","f":"五言绝句","c":["百步洪头水，秋霖一夜浑。","相携濯缨处，无复履綦痕。"]},{"t":"怀寄寇元弼王文举十首 其六 登黄楼","f":"五言绝句","c":["何处延明月，东城百尺楼。","故人那得见，后夜是中秋。"]},{"t":"怀寄寇元弼王文举十首 其四 登飞鸿亭","f":"五言绝句","c":["南京一登眺，朔雁正来宾。","好去长淮北，殷勤访故人。"]},{"t":"怀寄清凉和上人二首 其二","f":"五言绝句","c":["试问江南客，何时肯度杯。","多情是湖水，每日石头来。"]},{"t":"怀寄彭城朋好十首 其一 寇三","f":"五言绝句","c":["元弼今安健，音尘久阔疏。","早年倾盖意，白首复何如。"]},{"t":"怀寄彭城朋好十首 其二 张大","f":"五言绝句","c":["努力张谋父，躬耕老白云。","无年俭足用，此外奈何君。"]},{"t":"怀寄彭城朋好十首 其八 王七","f":"五言绝句","c":["子敏超龙级，得官何处州。","它时趋洛下，独与士龙游。"]},{"t":"怀寄彭城朋好十首 其十 王三","f":"五言绝句","c":["试吏王文举，俄缠风树哀。","明年道濉上，为尔一徘徊。"]},{"t":"怀寄彭城朋好十首 其三 刘四","f":"五言绝句","c":["子仲安贫者，毗陵久罢归。","秋风一相忆，赖有燕西飞。"]},{"t":"怀寄彭城朋好十首 其五 董大","f":"五言绝句","c":["希远来彭泽，聊为三径资。","拂衣归底处，命驾定何时。"]},{"t":"怀寄彭城朋好十首 其六 陈二","f":"五言绝句","c":["远寄陈传道，穷秋亦罢官。","还驱款段马，吟雪向长安。"]},{"t":"怀寄彭城朋好十首 其四 张十七","f":"五言绝句","c":["好在张居士，云龙寄梦频。","西斋见风月，连榻复何人。"]},{"t":"折中仓观米元章题字","f":"七言绝句","c":["银钩入木掩钟王，拂眼清风识楚狂。","淮海京尘两流落，与君大是觉身妨。"]},{"t":"拟刘孝胜咏安仁得果","f":"五言绝句","c":["果尽犹招手，车停更起尘。","固应持一笑，先答近辕人。"]},{"t":"李氏池上","f":"七言绝句","c":["湖外西风吹雨丝，半随杨柳拂涟漪。","女郎偷折藕花去，沙上鸳鸯睡不知。"]},{"t":"李固道中怀寄杜邯郸","f":"七言绝句","c":["西望丛台百尺间，车轮无角不知还。","大夫庭下长无讼，谁伴青堂整日闲。"]},{"t":"杨柳枝词二首 其一","f":"七言绝句","c":["方过清明雨后天，回塘照影弄跹跹。","深情拟属风光主，爱惜长条待少年。"]},{"t":"杨柳枝词二首 其二","f":"七言绝句","c":["杨柳东风尽日吹，柔条应自不禁持。","都门三月伤心地，强半青青赠别离。"]},{"t":"汴下晚归","f":"七言绝句","c":["隋渠经雪已流冰，乘兴东游恐未能。","试问何人知夜永，一樽相伴小窗灯。"]},{"t":"京居暮春感兴二首 其一","f":"七言绝句","c":["闲坊税屋远人群，晨鹊昏鸦亦厌闻。","无奈春风作多事，满庭花絮正纷纷。"]},{"t":"京居暮春感兴二首 其二","f":"七言绝句","c":["扰扰奔蹄与疾轮，九街寻胜作狂人。","东风漫送朝来雨，可奈长安自古尘。"]},{"t":"变竹枝词九首 其一","f":"五言绝句","c":["莫把雕檀楫，江清如可涉。","但闻歌竹枝，不见迎桃叶。"]},{"t":"变竹枝词九首 其七","f":"五言绝句","c":["胜概今犹昨，层楼栖燕雀。","但闻歌竹枝，不见乘黄鹤。"]},{"t":"变竹枝词九首 其二","f":"五言绝句","c":["隔岸东西州，清川拍岸流。","但闻竹枝曲，不见青翰舟。"]},{"t":"变竹枝词九首 其八","f":"五言绝句","c":["危构压江东，江山形胜雄。","但闻竹枝曲，不见胡床公。"]},{"t":"变竹枝词九首 其三","f":"五言绝句","c":["露湿云罗碧，月澄江练白。","但闻竹枝歌，不见骑鲸客。"]},{"t":"变竹枝词九首 其五","f":"五言绝句","c":["西戍长回首，高城当夏口。","但闻竹枝歌，不见行吟叟。"]},{"t":"变竹枝词九首 其六","f":"五言绝句","c":["南浦下鱼筒，孤篷信晚风。","但闻竹枝曲，不见沧浪翁。"]},{"t":"变竹枝词九首 其四","f":"五言绝句","c":["北渚芙蓉开，褰裳拟属媒。","但闻竹枝曲，不见莫愁来。"]},{"t":"和人伤春","f":"七言绝句","c":["入帘轻絮故依人，梦后题诗欲判春。","纵使相思解销骨，此情终未作黄尘。"]},{"t":"和王文举玉台体","f":"五言绝句","c":["南城空目送，西馆断心期。","悬知今夜思，明灯半下帷。"]},{"t":"和王文举别馆初夏","f":"五言绝句","c":["薰风酣绿树，午日思黄鹂。","的的罗窗梦，西邻可得知。"]},{"t":"和同行潘生悒悒悠悠二首 其二","f":"五言绝句","c":["悠悠复悠悠，泪寄东风流。","所思怅何许，西北齐云楼。"]},{"t":"和邠老郎官湖怀古五首 其五","f":"五言绝句","c":["岑辅何为者，当年唱不应。","名随诗石在，附骥两青蝇。"]},{"t":"和邠老郎官湖怀古五首 其四","f":"五言绝句","c":["杜守王明府，吾知夫不凡。","解持馀酒胾，一饫逐臣馋。"]},{"t":"和邠老郎官湖怀古五首 其三","f":"五言绝句","c":["昔人泯黄壤，陈迹变沧波。","劫火洞然坏，无如嘉句何。"]},{"t":"和邠老郎官湖怀古五首 其二","f":"五言绝句","c":["白也遭时网，临年放夜郎。","何妨去物远，当道横豺狼。"]},{"t":"和邠老郎官湖怀古五首 其一","f":"五言绝句","c":["郎官老辞笔，得尔寿春碑。","奸贼馀灵在，斯文是戮尸。"]},{"t":"和吴达夫见过留题","f":"七言绝句","c":["雀罗门巷不容车，杖屦相过一试茶。","后日相思会乘兴，五云溪上是侬家。"]},{"t":"和陈传道秋日十咏 其七 秋望","f":"五言绝句","c":["宿雨尘霾静，寒原黍稷空。","临风聊放目，不为送飞鸿。"]},{"t":"和陈传道秋日十咏 其九 秋燕","f":"五言绝句","c":["梅梁巢已空，去此复何从。","勿惮归飞远，冰霜不尔容。"]},{"t":"和陈传道秋日十咏 其十 秋蝇","f":"五言绝句","c":["不复怒飞声，朝鸡得擅鸣。","婆娑犹有地，媚灶毕馀生。"]},{"t":"和陈传道秋日十咏 其六 秋风","f":"五言绝句","c":["纷纷脱柯叶，衮衮断根蓬。","不待吹扬力，随风亦自东。"]},{"t":"和陈传道秋日十咏 其四 秋晓","f":"五言绝句","c":["未捲半帘霜，犹疑在庭月。","倚树汲清泉，疏风猎华发。"]},{"t":"和钱德循古意二首 其二","f":"五言绝句","c":["维汉南有箕，垂象列三辰。","长司簸扬职，糠秕居前尘。"]},{"t":"和崔若拙四时田家词四首 其一","f":"七言绝句","c":["鼓声迎客醉还家，社树团栾日影斜。","共喜今年春赛好，缠头红有象生花。"]},{"t":"和崔若拙四时田家词四首 其二","f":"七言绝句","c":["野蔓牵花过短墙，麦秋时节并蚕忙。","迎门老父延行客，井汲清甘树荫凉。"]},{"t":"和崔若拙四时田家词四首 其三","f":"七言绝句","c":["鸡声犬吠远相望，社酒登槽唤客尝。","晓日晴明陂更阔，风吹荞麦蜜花香。"]},{"t":"和崔若拙四时田家词四首 其四","f":"七言绝句","c":["晚雪漫漫没兔罝，满杯豆粥饷邻家。","夜长少妇无舂织，一点青灯伴缉麻。"]},{"t":"放舟通津门外作","f":"七言绝句","c":["国门欲去尚迟迟，况复凄风落照时。","犹有京尘坌舟尾，恼人无几庾元规。"]},{"t":"泊舟永城寄京都朋游","f":"七言绝句","c":["正西千里是青门，桥下春流带雨浑。","想见旧游芳草合，有谁楼上与销魂。"]},{"t":"茅塘马上","f":"七言绝句","c":["壮图忽忽负当年，回羡农儿过我贤。","水落陂塘秋日薄，仰眠牛背看青天。"]},{"t":"金堤客舍望南乐城","f":"七言绝句","c":["黄流漫涣浸城根，烟火依微日欲昏。","禾黍不登非政罪，居人犹得饱鱼飧。"]},{"t":"将发永城题陈伯隽蒙轩","f":"七言绝句","c":["几对春风把酒杯，小舟临发更徘徊。","四明狂客重来日，庭下榴花开未开。"]},{"t":"春夜对月","f":"七言绝句","c":["丽景门头初月明，清川灯火两桥横。","一舟若许东南去，何啻西风羽翼生。"]},{"t":"春晚楼上","f":"五言绝句","c":["杨华吹复尽，春色但茫茫。","独立西楼上，持情向夕阳。"]},{"t":"秋风登城楼","f":"七言绝句","c":["袭人风露觉秋初，临水高楼更雨馀。","天幕鲜明河影淡，行云流月两徐徐。"]},{"t":"秋江晚望","f":"七言绝句","c":["黄芦洲渚赤枫林，林外残阳叠嶂深。","记得广陵城里市，董源横障卖千金。"]},{"t":"舣舟广津门外作","f":"七言绝句","c":["綵蝀桥西七日留，几回回首凤皇楼。","如何一叶扁舟里，载得离人万斛愁。"]},{"t":"追和杜仲观咏蝶","f":"七言绝句","c":["黄蝶寻花日百回，荒庭多雨漫莓苔。","老狂能似徽之辈，借宅犹应乞竹栽。"]},{"t":"送人朝飨裕陵","f":"七言绝句","c":["三年不见鼎湖龙，弓剑尘埃玉座空。","白发孤臣心断绝，满山明月柏城风。"]},{"t":"送王西枢出镇郑圃八首 其一","f":"五言绝句","c":["千载君臣会，将图不世功。","卷收天下福，偏厚右扶风。"]},{"t":"送王西枢出镇郑圃八首 其七","f":"五言绝句","c":["门阑曳裾客，皆自许人豪。","今日宸廷下，谁知北郭骚。"]},{"t":"送王西枢出镇郑圃八首 其二","f":"五言绝句","c":["帷幄参神算，边尘万里清。","西藩聊偃息，犹是一长城。"]},{"t":"送王西枢出镇郑圃八首 其八","f":"五言绝句","c":["衮绣行将复，沙堤百里东。","病夫虽老矣，犹解赋豳风。"]},{"t":"送王西枢出镇郑圃八首 其三","f":"五言绝句","c":["公论由来重，高怀此去轻。","吾非厚知己，感叹此苍生。"]},{"t":"送王西枢出镇郑圃八首 其五","f":"五言绝句","c":["前日神州尹，声华掩赵张。","春风长有待，难树是甘棠。"]},{"t":"送王西枢出镇郑圃八首 其六","f":"五言绝句","c":["来暖西枢席，斯民赖已多。","前春凤池水，四海涨恩波。"]},{"t":"送王西枢出镇郑圃八首 其四","f":"五言绝句","c":["新书许从事，狡穴荡应空。","寄语征西将，无矜猎犬功。"]},{"t":"送僧法印志因西游京师","f":"七言绝句","c":["刻雪裁冰物外人，强随肥马走京尘。","未应无地栽桃李，江北江南一样春。"]},{"t":"送僧法印智因西上","f":"五言绝句","c":["千里长淮北，东风破雪寒。","此行休问路，蓦直到长安。"]},{"t":"重送曾诚之兼简俞澹陈庾 其一","f":"七言绝句","c":["春风漠漠老江蓠，行矣骚人好自持。","半百幻身如且健，石头城下两茅茨。"]},{"t":"重送曾诚之兼简俞澹陈庾 其二","f":"七言绝句","c":["陈颠俞散旧朋游，樽酒相逢定少留。","衰病故情犹有在，春风一夜梦扬州。"]},{"t":"重游钟山定林寺","f":"七言绝句","c":["破冰泉脉漱篱根，坏衲遥疑挂树猿。","蜡屐旧痕寻不见，东风先为我开门。"]},{"t":"重游寄老庵怀僧芝","f":"七言绝句","c":["淡游已恨失芝公，陈躅空留梦境中。","欲问孤云何处去，庭前双树自西风。"]},{"t":"重游梵行院","f":"七言绝句","c":["晓渡南冈五里松，精庐未见已闻钟。","门前拂地垂杨柳，扫净秋来过马踪。"]},{"t":"重赋京居暮春感兴","f":"七言绝句","c":["怒风狂雨信悠悠，收拾春华不少留。","祗有柳绵吹未尽，墙阴落泊伴人愁。"]},{"t":"席上分韵寄陈传道","f":"七言绝句","c":["忍穿布袜与青鞋，困走京尘十二街。","拟仗飞云寄招隐，东风吹送落君怀。"]},{"t":"晓晴西郊马上","f":"七言绝句","c":["夜雨萧萧彻晓闻，不应为我扫尘纷。","弄鞭十里西郊道，但见青山纳白云。"]},{"t":"留别僧永","f":"七言绝句","c":["三处分携跨两年，浮云生计本悠然。","江山胜地端相待，大有东南未尽缘。"]},{"t":"留题左顾亭二首 其一","f":"七言绝句","c":["馀不亭下舣归舟，访古怀贤百刻留。","办得千金脱元绪，此心端不为封侯。"]},{"t":"留题左顾亭二首 其二","f":"七言绝句","c":["亭际高枞满百围，不无山鬼此焉依。","咿呦为话当年事，曾见将军佩印归。"]},{"t":"病告中答王锜见招","f":"七言绝句","c":["伏枥驽骀伏枕人，不应俱是厌京尘。","东城自有乘肥客，白苧新裁探候春。"]},{"t":"离冠氏道中","f":"七言绝句","c":["别酒厌厌一据鞍，远林微径雪迷漫。","伤心不似来时路，柳摆东风絮作团。"]},{"t":"晚泊会亭","f":"七言绝句","c":["后日符离复舍舟，马蹄尘土入徐州。","祇应明月曾相识，伴我时登燕子楼。"]},{"t":"梅华寄清凉和上人","f":"五言绝句","c":["石头城上客，领取一枝梅。","何事春消息，今从江北来。"]},{"t":"梦后闻蛩","f":"五言绝句","c":["笼灯耿欲灭，枕下虫声切。","底许事相关，煎人肠断绝。"]},{"t":"清燕堂","f":"七言绝句","c":["雀声啧啧燕飞飞，在得残红一两枝。","睡思乍来还乍去，日长披卷下帘时。"]},{"t":"野步","f":"七言绝句","c":["津头微径望城斜，水落孤村格嫩沙。","黄草庵中疏雨湿，白头翁妪坐看瓜。"]},{"t":"黄埭魏氏见江亭","f":"七言绝句","c":["浮生欲寄酒杯间，马上谁容一日闲。","不是登高粗能赋，老夫真负尔江山。"]},{"t":"寒宵叹","f":"五言绝句","c":["可怜明月光，委曲照空床。","自是元无梦，更悲今夜长。"]},{"t":"渡冷水涧投宿万岁岭","f":"七言绝句","c":["萧萧黄叶下清沟，白鸟飞来故少留。","今夜行人短亭宿，小窗风雨梦渔舟。"]},{"t":"游夷门资福佛祠园","f":"七言绝句","c":["百根高树挂凌霄，鶗鴂飞来深处巢。","心喜它年有归著，白衣居士此诛茅。"]},{"t":"登兴国寺楼","f":"七言绝句","c":["怪槐风动绿鬅鬙，廊外时闻演梵僧。","怊怅无人共樽酒，可怜明月最高层。"]},{"t":"登如方山","f":"七言绝句","c":["楚郊十月尚闻蝉，傍道黄华亦可怜。","特上西山最高处，长安应在夕阳边。"]},{"t":"答陈传道五首 其二","f":"五言绝句","c":["游梁复归宋，南北更相送。","失得两如何，劳劳不如梦。"]},{"t":"答陈传道五首 其三","f":"五言绝句","c":["游宦几人达，不知强健归。","未容誇昼锦，几见化缁衣。"]},{"t":"答陈传道五首 其五","f":"五言绝句","c":["倒橐黄金尽，方悲行路难。","桂薪炊玉粒，可是乐长安。"]},{"t":"铸年五十八因病废得旨休致一绝寄呈姑苏毗陵诸友","f":"七言绝句","c":["求田问舍向吴津，欲著衰残老病身。","未拜君恩赐剡曲，归来且醉鉴湖春。"]},{"t":"感兴六首 其二","f":"五言绝句","c":["青鵳啖雀雏，饫饱侮鸢乌。","不知皂雕力，拿杀北城狐。"]},{"t":"感兴六首 其一","f":"五言绝句","c":["雏雀学翻飞，不知毛羽微。","青鵳笑高树，待尔饱朝饥。"]},{"t":"僧居对雨二首 其一","f":"七言绝句","c":["檐雨溅溅滴砌沙，绿丛深处一榴花。","小窗隐几俄成梦，堪笑无功饭后茶。"]},{"t":"僧居对雨二首 其二","f":"七言绝句","c":["平沙四绕护城堤，小雨经旬不作泥。","似与幽人慰牢落，一双黄鸟隔墙啼。"]},{"t":"题芭蕉叶","f":"七言绝句","c":["十亩荒池涨绿萍，南风不见芰荷生。","隔窗赖有芭蕉叶，未负潇湘夜雨声。"]},{"t":"题承天寺竹轩","f":"七言绝句","c":["征衫初解就僧床，惠我翛然一枕凉。","赤日黄尘畏途里，此君风味可能忘。"]},{"t":"题毗陵僧舍二首 其一","f":"七言绝句","c":["古寺相留跨两年，穷通出处固天然。","短檠灯火掩书卷，屡听芭蕉夜雨眠。"]},{"t":"题项羽庙三首 其一","f":"七言绝句","c":["分张天下付群雄，回首咸阳卷地空。","六国三秦随扰攘，锦衣何暇到江东。"]},{"t":"题项羽庙三首 其二","f":"楚辞体","c":["楚都陈迹久灰埃，一曲虞兮尚寄哀。","不作偷生渡江计，可须千里更西来。"]},{"t":"题项羽庙三首 其三","f":"七言绝句","c":["三户睢盱竟破秦，君王武略世称神。","途穷一夜无遗恨，挈首殷勤予故人。"]},{"t":"题流香亭","f":"七言绝句","c":["秋色朝来已十分，远山清瘦露云根。","芙蕖昨夜惊风雨，叶叶流香有泪痕。"]},{"t":"题海陵寓舍二首 其一","f":"五言绝句","c":["池上千条柳，依依解占春。","自怜衰飒鬓，不与物争新。"]},{"t":"题海陵寓舍二首 其二","f":"五言绝句","c":["池上雪初消，春鸦已占巢。","自怜流寓迹，无地可诛茅。"]},{"t":"题贾氏废园","f":"七言绝句","c":["丞相园林半手栽，清樽曾为几人开。","荒榛野蔓换桃李，惭愧春风如故来。"]},{"t":"题赠芥堂老僧遇来","f":"七言绝句","c":["岁计江边二顷田，不能多应世间缘。","闭门密竹荒松里，杯粥炉香六十年。"]},{"t":"魏城东","f":"七言绝句","c":["短短宫墙见杏花，霏霏晚雨湿啼鸦。","欲将今夜思归梦，凭仗春风吹到家。"]},{"t":"九日怀京都旧游","f":"七言律诗","c":["昔年九日登临处，把酒梁王旧吹台。","今年九日登临处，江上黄华殊未开。","一川落日随朝下，万里西风送雁来。","节物可惊人更老，宦情归计两悠哉。"]},{"t":"九日寄维扬刘明仲","f":"七言律诗","c":["扬舲瓜步背瓜洲，底处孤亭是玉钩。","蜡烛有心啼别夜，布帆无恙到南州。","黄华嘉节与何事，白发故人分取愁。","赖有沧江知客恨，长年西北望京流。"]},{"t":"九日登戏马台","f":"七言律诗","c":["当时节物此山川，倦客登临独惘然。","戏马台荒年自久，射蛇公去事空传。","黄华半老清霜后，白鸟孤飞落照前。","不与兴亡城下水，稳浮渔艇入淮天。"]},{"t":"九月十日寄潘邠老","f":"五言律诗","c":["明月昔如许，怀人殊不来。","徒歌桃叶曲，又负菊华开。","尺纸缄愁去，扁舟载梦回。","它年鸡黍约，千里信悠哉。"]},{"t":"二月二日席上赋","f":"七言律诗","c":["仲宣何遽向荆州，谢惠连须更少留。","二日旧传挑菜节，一樽聊解负薪忧。","向人草树有佳色，带郭江山皆胜游。","载酒赋诗从此始，它年耆老话风流。"]},{"t":"上巳晚泊龟山作","f":"七言律诗","c":["薄暮东风不满帆，迟迟未忍去淮南。","故园犹在北山北，佳节可怜三月三。","兰叶自供游女佩，芸编聊对故人谈。","洛桥车骑相望客，曾为吴儿几许惭。"]},{"t":"与张历阳追怀从禽之乐因赋","f":"七言律诗","c":["宜秋门外养鹰坊，好草陂头射雉场。","油幕毡庐张野饮，锦袍貂帽结戎装。","兴阑落日黄尘断，梦后西风白发长。","谁念江湖独流寓，此情难话与渔郎。"]},{"t":"广陵茱萸湾晚泊","f":"七言律诗","c":["冷云抛雪未成花，过埭东风冻著沙。","荻浦渔归初下雁，枫桥市散祗啼鸦。","旧闻南国饶春事，行见东风换物华。","老病心情亦何有，药囊诗卷是生涯。"]},{"t":"中秋日怀寄潘邠老赋","f":"七言律诗","c":["西戍角声清且哀，东城鼓动殷然雷。","雨阑伏槛月可待，风横舣舟君不来。","得酒未容欢独伯，把书端与睡为媒。","雪堂敛谷急还舍，更约头陀黄菊开。"]},{"t":"乌江广圣寺虚乐亭","f":"七言律诗","c":["避雨孤篷泊柳阴，潮回溪曲稻花深。","有时白鹭窥鱼下，竟日青蛙伴我吟。","酒敌无人情落漠，云乡何处老侵寻。","诛茅拟卜终焉计，不为清风暂解襟。"]},{"t":"乌江东乡往还马上作二首 其一","f":"七言律诗","c":["黄尘随马染征衣，十里江皋送客晖。","废井草荒蛙黾怒，下田沙涨芋魁肥。","解缨拂树弄清浅，横榻扫云飞翠微。","人生事事不如意，终日念归何日归。"]},{"t":"乌江东乡往还马上作二首 其二","f":"七言律诗","c":["悠悠东去欲何之，草草西还可是归。","残日两竿荒戍远，青山满眼故园非。","江田经雨菰蒋熟，石路无风蠛蠓飞。","回羡耕夫闲胜我，早收鸡犬闭柴扉。"]},{"t":"乌江北道中作","f":"七言律诗","c":["寒麦田畴雪糁花，暮潮洲渚水吞沙。","凫鹥长作渔舟伴，桑柘深藏老圃家。","浊酒纵贤谁与醉，青山有价不容赊。","南来学得沧浪唱，却著征衫袖马挝。"]},{"t":"乌江石跂觜晚望有怀","f":"七言律诗","c":["山色相衔类太行，江流东去亦浑黄。","鲈鱼鲙美招来客，鸿雁书迟梦故乡。","五斗月支何足道，一帆风便可能忘。","归田有计非今日，莫把移文揭草堂。"]},{"t":"乌江泛舟寓目","f":"七言律诗","c":["沧江浩渺寄星槎，望极纷纷两眼花。","但见潮头澍木杪，直疑山背落天涯。","鸱夷信得平生乐，仲御尤宜抵死誇。","伧父惭非能赋手，渔郎若个是诗家。"]},{"t":"书国志陈登事后","f":"七言律诗","c":["求田问舍良可嘉，元龙偶未思之耶。","黄鼠长为太仓耗，白云犹有青山家。","人生欻尔待钻石，世故纷然劳算沙。","销磨髀肉亦何事，竟作子阳同井蛙。"]},{"t":"内翰出龙眠居士写真图","f":"七言律诗","c":["落墨龙眠品入神，横筇一见谪仙人。","孤云老鹤来何处，异石清流有是身。","瞻仰生风开鬓发，卷舒盥手敬星辰。","他年莫用黄金铸，传在人间此逼真。"]},{"t":"历阳十咏 其二 鸡笼山","f":"五言律诗","c":["楚姥昔奔迸，馀生脱沈沦。","家禽不忍置，信谓妇人仁。","空笼欻变化，千载高嶙峋。","可待历湖水，复生桑下尘。"]},{"t":"壬申上元有怀金陵旧游","f":"七言律诗","c":["瓦官大庭千步方，灯如流萤月如霜。","高僧共礼旃檀像，游女来焚薰陆香。","旧国破亡何物在，少年逐乐个侬狂。","别来白社更牢落，回首衡湘春梦长。"]},{"t":"方明古免丧西上山阴贺铸方回以诗送行非敢赠言聊书美志","f":"七言律诗","c":["西上迟迟谁挽留，了君方寸慕松楸。","三年既尽亦当起，五斗有馀非所求。","早岁向风劳企羡，残生指日愿依投。","得官傥近柴桑里，应许江边著钓舟。"]},{"t":"丙寅舟次宋城作","f":"五言律诗","c":["水馆四边村，登临奈断魂。","黄花开小径，红粉哭高原。","舟楫逢新火，松楸老故园。","斜阳一千里，依约是苏门。"]},{"t":"永城邂逅周元通再索诗赠别","f":"七言律诗","c":["汎汎流萍滚滚蓬，偶然南北偶然逢。","一樽通济桥边酒，两夜临濉驿外钟。","行矣风波宜尚慎，归哉尘土不相容。","事功早立须知退，学稼它年访老农。"]},{"t":"玉津晚归马上","f":"五言律诗","c":["落日南城陌，东风禁火时。","醉醒皆自得，单袷正相宜。","绿树侵高阁，繁花泪曲池。","未应判节物，可奈故园思。"]},{"t":"示王泌","f":"七言律诗","c":["违离南北几星霜，短发萧萧带尺长。","执戟郎效官落拓，楚丘生触绪悲凉。","双凫乘雁谁比数，拉虎批熊犹健彊。","端恨养疴妨废酒，樽前都属个侬狂。"]},{"t":"兴龙节日渡江怀寄二友弟兼示同行","f":"七言律诗","c":["燕庭冠佩拜炉香，丸剑纷纷想定场。","江上烹鱼犹得信，座中惊雁已离行。","浇愁酩酊一樽酒，破睡咿哑两橹床。","不特赋诗怀二仲，故呈凡韵恼支郎。"]},{"t":"再送潘仲宝兼寄彭城交旧","f":"七言律诗","c":["风雨扁舟幸少留，为君持酒话徐州。","白鱼紫蟹秋初美，戏马飞鸿梦屡游。","二阮年来知健否，季真老去尽归休。","白云庄畔多闲地，不惜横刀直换牛。"]},{"t":"再酬讷师兼简清凉和上人","f":"七言律诗","c":["莫谓功名是可希，定知求法不求衣。","此身于世百无用，异日与君同所归。","遮眼何关黄卷在，安心更悟白牛非。","清凉有道平如掌，岂比他方大铁围。"]},{"t":"同王克慎宿清凉寺兼示和上人孙安之","f":"七言律诗","c":["六代风流不可寻，石头胜槩古犹今。","疏钟答响江山迥，啼鸟忘形松竹深。","借问白云谁卜筑，拟要明月共登临。","终投逸少兴公社，蔬粥麻衣事道林。"]},{"t":"同毕绍寓泊永城招李深昆仲","f":"七言律诗","c":["满城杨柳正黄繁，几处鞦韆出短垣。","经雨河流失清浅，带云春色乍寒暄。","从来嵇阮耽琴酒，况得机云好弟昆。","咫尺津亭望斋馆，杖藜相过莫辞烦。"]},{"t":"同道通师之香林马上","f":"五言律诗","c":["冰霜节候迟，淮楚早春时。","白草风头急，黄云日脚垂。","鸟声投古戍，马力倦长陂。","吾有官箴畏，劳生尔浪为。"]},{"t":"岁暮舟居卧病怀寄金陵和上人","f":"五言律诗","c":["野泊岁云暮，念归期正赊。","津童为过客，商舶是邻家。","雪密鱼依罧，潮回蚌委沙。","南州人健否，不寄早梅华。"]},{"t":"扬州叙游","f":"七言律诗","c":["迷藏九曲属樵耕，野草闲花故有情。","废苑春风遽如许，隔江山色可怜生。","新声度曲复谁道，古井酌泉聊独清。","杜紫微灵定相笑，青楼薄倖不知名。"]},{"t":"早发王村道中寄李智父","f":"五言律诗","c":["鸡鸣戒徒御，驱马度前陂。","得雨人耕早，边山日上迟。","罢休何复道，会合邈无期。","赖有西来水，悠悠慰我思。"]},{"t":"早夏","f":"五言律诗","c":["吏役初无补，端令乐事妨。","不知春遂去，但爱日何长。","薄雨梅含核，温风麦擢芒。","须容退食暇，一枕梦吾乡。"]},{"t":"有僧自峡中来持黄黔州手制茶兼能道其动静与潘豳老赋二首 其二","f":"词","c":["平生得禄仅荣亲，持底天涯料理贫。","夜户不关无长物，晨炊待火乞诸邻。","山?颇侠能来虎，水弩何知枉中人。","少减家园旧年调，携笼先采雨前春。"]},{"t":"有僧自峡中来持黄黔州手制茶兼能道其动静与潘豳老赋二首 其一","f":"七言律诗","c":["未闻东观奏书成，俄见西南万里行。","从坐何关李都尉，补亡犹待褚先生。","心悬黄犬沈来耗，耳惯青驹祗旧鸣。","时节私庭差自慰，凤将雏去雁随兄。"]},{"t":"江行写望","f":"五言律诗","c":["斜照侵疏箔，微凉逗小窗。","青蒲故依渚，白鸟屡横江。","遣兴诗三百，煎愁橹一双。","前舟定未远，叠鼓听逄逄。"]},{"t":"江夏秋怀三首 其一","f":"七言律诗","c":["陈物纷然眼界中，长年何与偶书空。","沧浪难为俗子唱，络纬漫催贫女工。","风月少容休吏役，烟波长与济途穷。","功成身退非吾事，犹办扁舟东复东。"]},{"t":"江夏秋怀三首 其三","f":"七言律诗","c":["此身岂复系西东，流浪江湖伴塞鸿。","曲突非图三爵客，直钩何羡六鳌翁。","千年陈迹祇今日，万里故园犹个中。","冗散偶逃人指数，未应吟啸坐妨公。"]},{"t":"汤泉道中","f":"五言律诗","c":["青石冈西下，灵泉产药苗。","山英如有待，木客可相招。","蝉带风移树，尘随马度桥。","飏鞭吟旧句，归路不知遥。"]},{"t":"自讼","f":"五言律诗","c":["朝听明钟出，暮随衙鼓归。","朝朝复暮暮，是是与非非。","迹寄升沈路，言投祸福机。","何穷百年事，端使一心违。"]},{"t":"自郓还徐道中","f":"五言律诗","c":["八月过新雨，行云弄晚凉。","山川乍明晦，禾黍半青黄。","西去真何事，东还非故乡。","悠悠尘土里，无路不亡羊。"]},{"t":"舟发金陵望历阳作","f":"五言律诗","c":["尚识历阳道，依然西照间。","风烟石碛戍，林麓楚王山。","隔水一凝伫，当年百往还。","谁怜跃马客，衰病再投闲。"]},{"t":"舟次广陵怀寄京都交旧","f":"七言律诗","c":["朋游冠盖满京华，病客东流迹自赊。","音驿未闻来日下，邻墙不见亦天涯。","尚惭斗粟烦官廪，已指扁舟是我家。","莫谓因风无可寄，雪梅开遍腊前花。"]},{"t":"舟次淮阴呈邑令田望","f":"七言律诗","c":["狂吟醉约昔悠悠，衰病方谐散浪游。","蔬粥满杯供我饱，兰舟系岸判君留。","尘埃古刹寻遗篆，香火严祠谒故侯。","晚具不须烹赤鲤，聊凭别后作书邮。"]},{"t":"西城有怀旧游","f":"五言律诗","c":["西郭天泉里，依依得旧游。","绮罗红芰晓，丝管万蝉秋。","柳碍鞦韆陌，萍沈祓禊舟。","华年勿复道，谁为驻东流。"]},{"t":"许永席上赋","f":"七言律诗","c":["流浪江湖跨两年，西风犹驻木兰船。","可人方外二三子，与尔樽中十八仙。","处士妄同公子议，曲生未减索郎贤。","自怜衰病方轰饮，也在刘家幕下天。"]},{"t":"访金陵王闲叟不遇留别","f":"七言律诗","c":["歌成五噫赁舂者，药不二价夺牛翁。","衰俗何知贵公子，清贫颇有昔人风。","君方上冢渡沔去，我适乘舟投剡中。","差池相失重回首，好住海鸥忘塞鸿。"]},{"t":"吴江送客","f":"五言律诗","c":["送别松陵道，轻舟助客拿。","湖空剪葭菼，市隘集鱼虾。","薄雨啼残雪，新潮蚀嫩沙。","镜中羞沓飒，行复见春花。"]},{"t":"呈李之仪","f":"七言律诗","c":["淹卧疲筋快晓晴，屋头相报鹁鸪鸣。","病侵老境可怜许，春入故园何似生。","坐想兰亭通曲水，行闻上巳接清明。","明年强健陪嘉集，定夺三觥赋不成。"]},{"t":"快哉亭朝暮寓目二首 其一","f":"五言律诗","c":["夙起喜舒旷，径趋城上楼。","初阳动禾黍，积雨失汀洲。","水牯负鸲鹆，山枢悬栝蒌。","坐惭真隐子，物我两悠悠。"]},{"t":"快哉亭朝暮寓目二首 其二","f":"五言律诗","c":["积潦际危堞，登临西照中。","苔衣罥白羽，槐荫悬青虫。","不浅胡床兴，无多团扇功。","目穷犹起羡，演漾一渔篷。"]},{"t":"怀寄寇元弼","f":"七言律诗","c":["君投筦库可知非，我饱官粮又愿违。","旧国秋高鸿雁过，长淮水落白鱼肥。","西风吹梦端相觅，南物留人也念归。","何日芦轩下双榻，满持樽酒洗尘机。"]},{"t":"怀寄潘孝本兼简其子言","f":"五言律诗","c":["春色先梅岭，秋声后桂林。","溪通五羊险，云近九疑阴。","无雁难逢信，有猿能伴吟。","一樽烧酒美，应对阿戎斟。"]},{"t":"投宿清凉寺","f":"五言律诗","c":["建业衣冠集，秦淮舟楫屯。","东西万里客，朝暮两潮浑。","何处契心赏，片时清耳根。","仆夫浪见问，但出石城门。"]},{"t":"拟南梁慧侃法师独杵捣衣","f":"五言律诗","c":["峄阳桐杵鸣，莲岳石砧平。","待谁相应节，要自不胜情。","吹衣风稍急，吊影月微明。","会有不眠客，听此断肠声。"]},{"t":"汴上有怀李易初","f":"七言律诗","c":["何处经行特惘然，津头曾送木兰船。","桃花春水生前夜，杨柳秋风忆故年。","驿路尺书疑断绝，官仓斗米愧留连。","飘飖复作江湖计，从此长安是日边。"]},{"t":"汴上留别李智父","f":"七言律诗","c":["一马西投汴水滨，自惊秋鬓带尘纷。","秋风尽日吹黄叶，心事经年寄白云。","去矣尺书勤访我，醉来樽酒强酬君。","北窗络纬寒声急，明夜伤心独自闻。"]},{"t":"汴渠夜泊示毕绍彦祖","f":"五言律诗","c":["耿耿度中夜，浩歌谁与酬。","屋头风罨岸，枕底浪澎舟。","春物行飘忽，乡心久滞留。","须明投吏部，一醉驿西楼。"]},{"t":"芜湖王敦城下作","f":"七言律诗","c":["斗立孤城日四围，贼奴曾未慑天威。","风生虎帐豺声厉，尘犯龙颜鱼服归。","首揭大航遗臭在，歌流乐府旧音非。","当时不慕桓文举，草满中原胡马肥。"]},{"t":"辛未兴龙节日怀历阳王掾元胥","f":"五言律诗","c":["昨岁东溪口，扁舟欲下江。","伴愁灯映幔，欺睡月侵窗。","漫寄书连纸，谁同酒一缸。","何当见之子，聊使我心降。"]},{"t":"陈留南城马上简李公年","f":"七言律诗","c":["南郭何人卜筑幽，平田高树带清沟。","隔墙野鸟啼晴昼，驻马行人照白头。","二顷难寻归老计，一樽宜结探春游。","步兵不惜供厨费，更作东风数日留。"]},{"t":"龟山晚泊","f":"五言律诗","c":["春候半寒温，维舟淮上村。","长林补山豁，青草际潮痕。","久厌浮家役，重招去国魂。","禅房欲舒写，烟雨促黄昏。"]},{"t":"京居春日遣怀","f":"七言律诗","c":["青梅小叶柳长条，相对春风各动摇。","物色依依如有待，人情忽忽自无聊。","五陵剑侠知谁健，三径车工不我招。","好去广津门下水，新秋稳送木兰桡。"]},{"t":"京居感兴","f":"五言律诗","c":["为问长安客，何人识要津。","长持一马箠，浪走六街尘。","城阙烟中晓，关河雪后春。","故园桃李在，樽酒愿相亲。"]},{"t":"和人游白云庄二首 其一","f":"五言律诗","c":["原野正春风，登临一醉同。","阴晴时未定，今古思何穷。","山势落还起，溪流噎复通。","隐君方自得，可羡尔冥鸿。"]},{"t":"和人游白云庄二首 其二","f":"五言律诗","c":["可爱白云翁，前溪舣钓篷。","耕樵一径下，井臼四邻同。","倦宦终何得，馀生寄此中。","预烦多种秫，毋使酒杯空。"]},{"t":"和田录事君义咏雪","f":"七言律诗","c":["千里龙沙失旧荒，四来云物助苍凉。","直疑见月应无影，未必因风始解狂。","枉费铅华□楚女，不禁汤饼试何郎。","回中自是人间世，怊怅龟台去路长。"]},{"t":"和田录事新燕","f":"七言律诗","c":["新巢故国两依依，似与春华秋叶期。","雨过池塘得泥近，日高台榭卷帘迟。","鞦韆节后初相见，祓禊人归有所思。","双侣多情拟凭杖，小笺封就碧云诗。"]},{"t":"和别清凉和上人","f":"七言律诗","c":["明朝解携白鹭洲，后日相望黄鹤楼。","建业水清供白酌，武昌鱼贱足音邮。","著身物外不无处，俛首人群非有求。","愿报西庵落成会，待公退卧侬归休。"]},{"t":"和杜仲观青字诗二首 其一","f":"五言律诗","c":["青袍少年子，独出青门游。","逢人少青眼，凝笑望青楼。","窗中青蛾女，正为青春愁。","心事属青鸟，青骢能少留。"]},{"t":"和钱德循书怀","f":"七言律诗","c":["咄嗟世与我相疏，岁月推排负壮图。","狂客大难兼外监，方回小得胜常奴。","胸中累块亦何有，鬲上督邮非所须。","径买一舟归自好，五云溪接当家湖。"]},{"t":"和彭城王生悼歌人盼盼","f":"七言律诗","c":["东园花下记相逢，倩盼偷回一笑浓。","书簏尚缄香豆蔻，镜奁初失玉芙蓉。","歌阑燕子楼前月，魂断凤皇原上钟。","寄语虞卿谩多赋，九泉无路达鱼封。"]},{"t":"和答郑郎中见寄","f":"七言律诗","c":["客子由来怀故乡，苏门冷落白云旁。","梦随夜月钟前断，诗入秋风草共荒。","操板镰靴游宦厌，开樽挥麈旧欢长。","泜川逸老应相念，为倚阑干向夕阳。"]},{"t":"和潘豳老汉上属目","f":"五言律诗","c":["白云蒙山头，清川山下流。","芳洲采香女，薄暮漾归舟。","并蒂双荷叶，逢迎一障羞。","持情不得语，大妇在高楼。"]},{"t":"宝应野泊","f":"五言律诗","c":["伏枕漳滨后，维舟楚泽边。","筋骸非壮日，节物迫穷年。","夜雨侵床漏，晨炊凑鼻烟。","劳生我其分，十口亦飘然。"]},{"t":"放舟下江留寄王元胥","f":"七言律诗","c":["桧楫淹留已涉旬，小窗犹得酒相亲。","寒潮不应溪流涩，病客未行舟子嗔。","挥手便分今夜月，断肠先见隔江春。","凤皇台上长回首，何处高城与故人。"]},{"t":"易官后呈交旧","f":"五言律诗","c":["当年笔漫投，说剑气横秋。","自负虎头相，谁封龙额侯。","聊辞哙等伍，滥作诗家流。","少待高常侍，功名晚岁收。"]},{"t":"苦竹村南马上","f":"五言律诗","c":["楚泽薰风后，林皋夕照间。","渔船沿绿岸，鸟道转荒山。","久负杯中乐，长偷马上闲。","悠悠白门路，何日杖藜还。"]},{"t":"金陵怀寄历阳王掾","f":"五言律诗","c":["征虏亭边路，望夫山下舟。","长江不隔梦，明月祇供愁。","促席歌尘断，闲窗醉墨留。","惜芳桥畔柳，谁系木兰舟。"]},{"t":"雨馀晚望","f":"五言律诗","c":["相应乳鸠鸣，桑间返照平。","明津小舫度，高陇一牛耕。","林薮归心健，尘埃病骨轻。","屈骚魂爽在，未许独君清。"]},{"t":"雨晴西郊寓目","f":"七言律诗","c":["城中厌雨过清和，偶出西郊野意多。","蚕簇趁晴初摘茧，麦场经润欲生蛾。","营巢黄鸟啼深树，引犊青牛饮暮河。","老圃念人留伫久，挽衣沽酒愿相过。"]},{"t":"临汴亭送客还马上作","f":"七言律诗","c":["衮衮尘埃与愿违，可堪持酒送将归。","壮心已服驽骀老，羁思常先鸿雁飞。","十口无厌太仓粟，四邻分采故山薇。","何时偃卧柴桑里，自讼渊明昨日非。"]},{"t":"冠氏寺居书怀","f":"七言律诗","c":["古刹荒凉昼掩门，鸣鸡吠犬接西村。","窗间自记曾归梦，楼外谁招欲断魂。","漫赋新诗题琬琰，少逢佳客佩兰荪。","更堪愁肺经春病，负尔商歌酒一樽。"]},{"t":"冠氏县斋书事寄滏阳朋游","f":"七言律诗","c":["小阁烧香麝煎浓，翠苔庭院绿阴风。","卷帘燕自双飞去，敧枕人方半梦中。","秋鬓先于怀县令，春愁多似义城公。","西园酒伴无消息，欲寄鱼笺水自东。"]},{"t":"将发永城留题李氏斋壁","f":"七言律诗","c":["匹马扁舟寄此身，可怜投老尚迷津。","黄尘是处随游子，明日相逢即故人。","东道琴樽能惜夜，西园花絮欲伤春。","分携后日匆匆去，灯火虹桥梦更频。"]},{"t":"将发彭城作","f":"七言律诗","c":["四年吟笑老东徐，满目溪山不负渠。","得米径须偿酒债，有田便拟卜吾庐。","明朝门外扁舟雪，别夜灯前满纸书。","会问匆匆解携客，相思命驾定何如。"]},{"t":"度黄叶岭怀寄清凉白云庵主","f":"七言律诗","c":["黄叶岭头黄叶飞，白云庵畔白云归。","叶随游子终相失，云伴禅翁得所依。","会解腰间斩马剑，肯寻江上钓鱼矶。","焚香扫地双林下，愿赎今生种种非。"]},{"t":"待晓朝谒天庆作","f":"五言律诗","c":["望晓谒琳宫，荒庭雾气浓。","曾陪羽林仗，如待景阳钟。","薄宦情无几，劳生梦不容。","樵朋与渔伴，它日会相从。"]},{"t":"春书","f":"五言律诗","c":["新蚕经浴罢，旧燕未来前。","吏局坐如梦，物华行可怜。","藻生南浦钓，雨足东皋田。","故国负归约，尘埃年复年。"]},{"t":"春怀有寄代同行作","f":"七言律诗","c":["未应一笑为千金，且解樽前绿绮琴。","归雁不将书北去，行云长伴日西沉。","楚兰径远飞黄蝶，湘水帘空对绿阴。","无复赏心酬节物，断肠翻咏白头吟。"]},{"t":"秋衣闻雨晨兴偶书","f":"五言律诗","c":["故国心驰北，扁舟计漫东。","寒生一夜雨，病涉两秋风。","落泊篱根叶，幽忧屋角虫。","何情悲节物，聊自况衰翁。"]},{"t":"秋怀二首 其一","f":"五言律诗","c":["室迩人尚远，况乎千里间。","岂徒道路长，重水复重山。","清霜老芳物，嘉树不堪攀。","欲寄陇头信，春风殊未还。"]},{"t":"舣舟当利口待风累日怀寄城中朋游二首 其一","f":"五言律诗","c":["一叶寄津口，怒涛安可乘。","朝风占酒旆，夜爨乞渔灯。","牛渚逢新月，秦淮想结冰。","故人它夕梦，歌吹满金陵。"]},{"t":"舣舟当利口待风累日怀寄城中朋游二首 其二","f":"五言律诗","c":["离忧不可解，罢酒独登临。","潮落江空阔，云繁岁晏阴。","愁鸱守渔罧，怒犬突神林。","触目增悽断，聊为泽畔吟。"]},{"t":"舣舟当利港作","f":"七言律诗","c":["为问溪头潮浅深，片帆长挂北归心。","夜风吹雪晓尤怒，午日破云寒复阴。","江淮行役殊未已，京洛朋游安事寻。","何时稳坐饱粗饭，鼓腹东皋农父吟。"]},{"t":"送历阳潘司户瑶移令归东鲁","f":"七言律诗","c":["衰俗纷纷务近功，几人心迹与君同。","低回州县青衫列，踊跃圣贤黄卷中。","牛渚江山空夜月，河阳桃李再春风。","相望鲁卫无多远，异日能寻卖药翁。"]},{"t":"送方安行之官高密令","f":"七言律诗","c":["平世功名输阿童，束书洗剑栖渔篷。","晚交东武百里长，想见桐庐三拜风。","白雪兴阑吟社远，绿槐阴合讼庭空。","它年朱绂指东道，试访钓鳌浮玉翁。"]},{"t":"送左禹赴江夏尉","f":"五言律诗","c":["汎汎青翰舟，亭亭黄鹤楼。","江山信清洒，人物想风流。","美酒遣归思，新诗题旧游。","有鱼知不食，端作置书邮。"]},{"t":"送汉阳刑狱掾邹永年解官归养","f":"七言律诗","c":["高歌每忆故山薇，笑掷青衫换綵衣。","竟为苍生安石起，本来男子次君归。","脱冠弭棹兴非浅，戴笠乘车誓莫违。","明日渡江聊赠别，武昌官柳尚依依。"]},{"t":"送毕平仲西上","f":"七言律诗","c":["吟鞭西指凤皇州，好趁华年访昔游。","新样春衫裁白苧，旧题醉墨满青楼。","鸣蛙雨细生梅润，飏燕风高报麦秋。","须念江边桃叶女，定从今日望归舟。"]},{"t":"送毕彦祖先之京师","f":"七言律诗","c":["日日东风吹旱云，弄鞭低帽送西曛。","客亭五里复十里，春物三分今二分。","但解征衣平酒债，莫随肥马作尘纷。","扁舟不及清明约，紫笋朱樱未负君。"]},{"t":"送江与京归山阳","f":"七言律诗","c":["山阳泽国四无山，百雉危城两水关。","杨柳遥知紫极路，沧波长羡白鸥闲。","病来药裹为吾累，兴尽渔舟送子还。","风月异时何限思，区区并入尺书间。"]},{"t":"送张师常之官南雄","f":"七言律诗","c":["爰居蹭蹬海西头，紫凤求皇亦少留。","持酒一樽明日别，题诗几处旧年游。","春风白芷江南岸，暑雨黄梅岭上州。","却望衡阳千里远，悬知无雁托音邮。"]},{"t":"送张商老西上","f":"五言律诗","c":["雾气敛陂泽，鼓声催客航。","蒹葭靡宿露，鹳鹤盘朝阳。","行役自兹远，离愁安可忘。","黄华一樽酒，何处望吾乡。"]},{"t":"送时适归彭城兼寄王会之并张白云","f":"七言律诗","c":["壮年客宦乐徐州，五见黄华戏马周。","无复登山抛旧屐，不堪临水送归舟。","东城公子犹三径，南墅先生久一邱。","为话吴门非乐土，鲈鱼菰黍漫淹留。"]},{"t":"送李主簿夷行之官河阴四首 其一","f":"五言律诗","c":["夙昔一樽酒，相从清泗滨。","回首欻四载，长安逢故人。","交情久益淡，辞笔老加新。","送子复西去，劳生悲重陈。"]},{"t":"送李宗古录事谢病南归","f":"七言律诗","c":["十旬病免谢鸡群，收得闲身付白云。","南浦少留离别赋，北山相待敢移文。","松舟桂楫晓将发，菰叶鲈鱼秋未分。","异日有怀长笑客，西飞燕子一相闻。"]},{"t":"送李易初还汶阳","f":"五言律诗","c":["客宦怆离群，徐方复得君。","青衫初试吏，白面颇能文。","画舸浮春水，清樽醉舞裙。","它年会相访，分卧北山云。"]},{"t":"送陈传道摄双沟戍商税","f":"七言律诗","c":["墙外长川拥万舟，门前山色入南州。","风来浦口客争发，日下庭阴印未收。","乍厌折腰从吏役，屡应回首念朋游。","病夫颇有东流兴，预约清樽为少留。"]},{"t":"送陈传道摄官双沟","f":"五言律诗","c":["弭楫想登临，閒云护日阴。","青蒲泗水阔，古木汉祠深。","应醉杯中物，谁闻泽畔吟。","禅坊养疴客，轻别若为心。"]},{"t":"送周开祖出守鄱阳","f":"七言律诗","c":["三尺京尘衮衮中，略无闲地贮清风。","鲈鱼菰菜经年别，皂盖朱轓一日东。","俗眼强分青白在，芳樽未觉圣贤空。","鄱阳不乏江山助，高兴都卢属谢公。"]},{"t":"送金坛慎令瓛","f":"五言律诗","c":["清素复多闻，天涯晚得君。","相延蒲塞馔，细演贝多文。","世味淡如水，身谋散胜云。","谩为花县约，聊慰此临分。"]},{"t":"送赵令畤之官陈州兼简周文清","f":"七言律诗","c":["朱衣白面懿王孙，好去淮阳事相君。","已放扁舟下南浦，更持樽酒醉西曛。","青云计自此行始，明月惜从今夜分。","拟仗短书裁不及，但传穷达报知闻。"]},{"t":"送彭城周主簿建中移黄县令","f":"七言律诗","c":["客宦逢迎泗上州，酒筹诗卷慰淹留。","九层灯火偃王塔，四面溪山彭祖楼。","此去君辞栖棘地，年来吾有负薪忧。","终期一过河阳县，相对春风话旧游。"]},{"t":"送蒲圻陈主簿彦升归越","f":"五言律诗","c":["好在稽山北，因君访故园。","风流久衰歇，湖水自清浑。","可得千秋观，相传百代孙。","时闻祖行客，不减汉东门。"]},{"t":"送潘景仁之官岭外兼寄桂林从叔","f":"七言律诗","c":["夜衔舟尾昼联樯，齐发都门到楚乡。","我欲尘埃投衮衮，君方湖海去茫茫。","伤心客路逢寒食，回首家园但夕阳。","想见步兵应访问，仲容无复竹林狂。"]},{"t":"重别王掾","f":"五言律诗","c":["别访难遽了，不知寒夜长。","回灯撤杯案，抱被宿船仓。","载听远鸡唱，稍分征雁行。","临风满掬泪，吹落一襟霜。"]},{"t":"重别和上人","f":"七言律诗","c":["分手风波路几千，侵寻老境百疴缠。","一官得饱亦劳矣，大士忘情犹泫然。","北道音尘长断望，西庵香火不无缘。","是身脱使先朝露，图像聊依十七贤。"]},{"t":"钟山法云彦上人留中餐罢游草堂寺","f":"五言律诗","c":["弭楫秦淮尾，登临殊兴回。","难销蔬饭饱，更过草堂来。","日转岩扉暝，风披蕙帐开。","吾非海盐令，猿鸟莫相猜。"]},{"t":"闻苏眉山谪守英州作","f":"七言律诗","c":["岭首登临楚粤分，披襟先喜得南薰。","座隅鵩鸟敢要赋，溪下鳄鱼知畏文。","酒洗黄茅瘴时雨，啸驱碧落洞中云。","高才何假江山助，未拟区区咏五君。"]},{"t":"海陵书事","f":"七言律诗","c":["海滨流浪胡为乎，况复支离百病馀。","三月逢梅识春色，半年无雁托归书。","老乌啄屋巫呼鬼，野艇横门米换鱼。","回首扬州才百里，画桥风月可怜渠。"]},{"t":"海陵西楼寓目","f":"七言律诗","c":["天涯樽酒与谁开，风外徂春挽不回。","扫地可怜花更落，卷帘无奈燕还来。","王孙莫顾漳滨卧，渔父何知楚客才。","强策驽筋怀故国，浮云千里思悠哉。"]},{"t":"烈洲守风","f":"七言律诗","c":["张帆早发石头城，淹泊风波百里程。","白芷汀洲潮进退，黄梅村落昼阴晴。","官粮牵迫少休日，药物扶持多半生。","深闭船扉谢渔老，自惭尘垢满襟缨。"]},{"t":"留别王闲叟","f":"七言律诗","c":["婆娑晚境未知还，邂逅故人增厚颜。","次道志包宇宙外，子牟身寄江湖间。","一乘妙义想冰释，九死馀生非石顽。","敢负清凉阿师约，西庵先办十年闲。"]},{"t":"留别王掾元胥","f":"五言律诗","c":["之子贯东牟，青衫试宦游。","颠非小贺比，爽自阿戎流。","未即芸香拜，俄先瓜戍秋。","孤蓬别夜思，霜月满沧洲。"]},{"t":"留别王景通二首 其一","f":"七言律诗","c":["早年放乐五云乡，远笑垣东侠少场。","宪也但贫犹未病，公乎非酒自能狂。","尘埃辇路春游散，灯火僧窗夜话长。","后日相思枉缄幅，茱萸湾北付渔郎。"]},{"t":"留别王景通二首 其二","f":"七言律诗","c":["游宦差池太半生，君方倥偬我伶俜。","官衔转落百僚底，衫色浑偷两鬓青。","张掾官曹抛胜日，向平家事汩馀龄。","相逢一段孟城梦，明发扁舟是浪萍。"]},{"t":"留别米雍丘二首 其一","f":"五言律诗","c":["明釭通夜语，累块写胸中。","水癖推刘令，书名浼鲁公。","忌猜悲廪鼠，逐热贱云鸿。","不乏佳山水，东南著两翁。"]},{"t":"留别米雍丘二首 其二","f":"五言律诗","c":["好住楚公子，山林何处逢。","官身须自乞，俗眼可相容。","叔夜懒犹锻，伯鸾佣且舂。","多惭方禄隐，尔汝傲吴侬。"]},{"t":"留别张白云谋父","f":"七言律诗","c":["三年官局冷如冰，炙手权门我未能。","赖与白云之隐者，不谈黄卷即寻僧。","萧萧帘箔风披竹，草草杯盘雪洒灯。","尘土浮游浸相远，吴鱼燕雁两难凭。"]},{"t":"留别彦上人","f":"七言律诗","c":["道人临别重留连，应念吾生汩世缘。","拄笏看山犹故态，量船载酒异常年。","兴来不计远千里，休去可须持一钱。","会作清凉老庵主，两盂分粥对床眠。"]},{"t":"留别寇定","f":"七言律诗","c":["不见步兵今一秋，年来复与仲容游。","苍颜白发惭衰暮，纵饮狂歌作辈流。","顾我宦情真漫浪，为君行计几淹留。","能寻三月皇州约，拍手同登卖酒楼。"]},{"t":"病后登快哉亭","f":"七言律诗","c":["经雨清蝉得意鸣，征尘见处见归程。","病来把酒不知厌，梦后倚楼无限情。","鸦带斜阳投古刹，草将野色入荒城。","故园又负黄昏约，但觉秋风发上生。"]},{"t":"秦淮夜泊","f":"五言律诗","c":["官柳动春条，秦淮生暮潮。","楼台见新月，灯火上双桥。","隔岸开朱箔，临风弄紫箫。","谁怜远游子，心旆正摇摇。"]},{"t":"秦淮官柳二首 其二","f":"七言律诗","c":["西来载病一扁舟，建业江山负胜游。","杨柳经眠方自得，蒲帆临挂复迟留。","长条似舞前溪曲，卷叶宜翻出塞愁。","想见南朝旧人物，可怜能閟样风流。"]},{"t":"载病东归山阴酬别京都交旧","f":"七言律诗","c":["我家湖水接山溪，载病东归路不迷。","城郭依然辽海鹤，鹓鸿邈矣会稽鸡。","可须印绶怀中出，幸有珠玑袖里携。","行赋渔歌寄亲串，春风吹渡浙江西。"]},{"t":"钱塘海潮","f":"七言律诗","c":["高岸如陵累石顽，一支涨海横中间。","九军雷鼓震玉垒，万里墨云驱雪山。","秦政维舟羞胆怯，史迁舐笔恨才悭。","钱郎几许英雄气，强弩三千拟射还。"]},{"t":"高邮舟居对雪","f":"七言律诗","c":["天涯晚岁客无欢，拥鼻微吟行路难。","三楚浮程波淼淼，五陵归梦雪漫漫。","兔园授简心犹壮，剡曲拿舟兴久阑。","病骨支离仍禁酒，渔蓑重缉待春寒。"]},{"t":"高望道中","f":"五言律诗","c":["积雨涨陂塘，田塍插晚秧。","远山宜薄莫，高燕弄微凉。","马革非吾愿，鱼餐餍此乡。","归期知近在，犹待菊华黄。"]},{"t":"宿芥塘佛祠","f":"七言律诗","c":["青青麰麦欲抽芒，浩荡东风晚更狂。","微径断桥寻古寺，短篱高树隔横塘。","开门未扫杨花雨，待晓先烧柏子香。","底许暂忘行役倦，故人题字满长廊。"]},{"t":"宿黄叶岭田家","f":"五言律诗","c":["聚落荒山里，畬田岁不登。","牛衣障隙雪，鼠穴见邻灯。","愁信鱼难瞑，寒凝酒亦冰。","怅然歌白石，推枕待晨兴。"]},{"t":"寄王岐","f":"七言律诗","c":["未从名宦两蹉跎，可但诗狂与酒魔。","紫陌尘埃日驰逐，青楼灯火夜经过。","当时豪纵年方少，今日疏慵病更多。","唯见凭栏复敧枕，往来方寸奈情何。"]},{"t":"寄别秦观少游","f":"七言律诗","c":["沔阳湖上小留连，疑是前时李谪仙。","流向夜郎才半道，径还江夏乐当年。","个侬生以才为累，阿堵官于老有缘。","待得公归吾亦罢，春风先办两渔船。"]},{"t":"寄别僧芝","f":"七言律诗","c":["不见江南汤惠休，芝钱今也嗣风流。","烧香弄笔一生事，蹑屐佩囊千里游。","乞酒未还黄菊晚，拟诗初就碧云秋。","临高跂马君行矣，从此安期始欲愁。"]},{"t":"寄李赵二友生","f":"七言律诗","c":["东风掠地百草青，颠毛馀几今星星。","长年婴疾断还往，无处避愁徒醉醒。","联马寻芳狭斜道，衔舟待月沧浪亭。","遥输此兴二公子，涨海未应沈一萍。"]},{"t":"寄周文清","f":"七言律诗","c":["节物惊心不我留，故人相望海边州。","芰荷老尽池台晚，鸿雁来多云汉秋。","谁共清樽寻乐事，独将长幅写离忧。","明年芳草青门道，好试青衫伴侠游。"]},{"t":"寄金陵和上人","f":"七言律诗","c":["旧年问米欲东流，先赋新诗寄石头。","赤鲩久沉江上信，杂悬误落海边州。","想君道眼遥相识，顾我官身可自由。","香火因缘知有在，草庵蔬粥不他求。"]},{"t":"寄清凉和上人二首 其一","f":"七言律诗","c":["吾家无担石之储，朝四暮三如有馀。","北岳官粮饱妻子，南朝僧寺寓图书。","迎船春色情亲我，坌马京尘笑谢渠。","莫作江东步兵待，翻然端不为鲈鱼。"]},{"t":"寄清凉和上人二首 其二","f":"七言律诗","c":["南国风流百不存，石头今是给孤园。","山连雉堞犹侵路，潮送渔舟自到门。","方丈定容居士病，贝多应待客儿翻。","悬知后日逢迎际，桃李春风两不言。"]},{"t":"寄题狄丘李伟官舍东斋","f":"七言律诗","c":["树竹开窗小屋东，低檐却日竹通风。","长年驰骛欲何往，终日退藏于此中。","未厌睡魔常有在，若思人事即无穷。","躬耕不是悠悠计，来作苏门邻舍翁。"]},{"t":"寄题盱眙杜子师东山草堂","f":"五言律诗","c":["东山与物远，松竹荫茅茨。","信有冥鸿志，难藏雾豹姿。","会招安石起，何患德璋移。","后日岩扉下，游人想履綦。"]},{"t":"寄题泉南陈氏步云亭","f":"七言律诗","c":["紫翠峰前水一湾，趣亭微径白云关。","渔樵不见携筇去，猿鹤相随采药还。","晚月带潮来海上，春风吹雨到人间。","恨君轻为苍生起，曾得东山几日闲。"]},{"t":"晚泊小孤山作","f":"七言律诗","c":["江势东南陡折回，两山屹立地维开。","颠风裂石轰雷下，骇浪澎舟卷雪来。","扪虱王孙初睥睨，饱鱼乌鬼但毰毸。","物情岂识忘形乐，啸倚樯干独快哉。"]},{"t":"晚泊长芦有怀历阳金陵朋好","f":"七言律诗","c":["犀照亭边两橹催，凤栖台下片帆开。","龙盘虎踞行远矣，牛渚鸡笼安在哉。","无端鞍马三年役，有意莼鲈异日来。","樽酒故人谁待我，故应风月尚徘徊。"]},{"t":"晚泊东采石矶","f":"七言律诗","c":["谢卫将军怜苦吟，袁临汝郎遭赏音。","风流人物岂如昨，形胜江关留与今。","控鲤直思淩浩渺，然犀何假照幽深。","莫招捉月翰林老，屈曲尘间犹陆沉。"]},{"t":"曹永州哀词","f":"七言律诗","c":["老眼春风两泪倾，穗帷樽俎异平生。","可惊人与琴俱绝，但见肴晞酒复清。","相合水边传美政，飞来峰下启佳城。","翩翩五六奇男子，肯使高门坠厥声。"]},{"t":"梦游金陵设堂故基","f":"七言律诗","c":["燕堂遗址压西州，剪径扪萝出石头。","老木骎骎太相逼，连冈衮衮欲东流。","歌钟谁话前朝事，风雨魂惊别夜游。","梦境浮生更多病，结茅归老信悠悠。"]},{"t":"清明病中","f":"五言律诗","c":["寒食晴旸少，江南此候同。","侵晨泼火雨，薄暮驾潮风。","目力书签上，生涯药裹中。","可怜佳节物，似不系衰翁。"]},{"t":"雪后同吴达夫慎献玉登黄鹤楼","f":"七言律诗","c":["岁律峥嵘腊尽头，风吹朔雪到南州。","三湖簸荡鲛鼍恐，七泽迷漫狐兔愁。","狂客定回青雀舫，猎儿初试皂貂裘。","江楼伏槛迎新霁，群玉峰前练带流。"]},{"t":"寓泊金陵寻王荆公陈迹","f":"七言律诗","c":["晚泊扁舟一问津，依然节物思羁人。","江山月照六朝梦，桃李风吹三月春。","宅枕谢公墩下路，诗寻萧寺壁间尘。","可须樽酒平生约，长望西州泪满巾。"]},{"t":"寓泊临淮有怀杜脩撰","f":"五言律诗","c":["幕卷歌鬟列，堂深蜜炬然。","临风鸣羯鼓，待月戏鞦韆。","短韵吟笺出，长檐醉帽偏。","斯人违薄俗，何减孟公贤。"]},{"t":"游六合定山真如寺","f":"五言律诗","c":["只履西归远，何年此布金。","地寒苍桧老，岁宴白云阴。","烧隔溪冰断，樵穿径雪深。","祖心无处问，俗驾晚骎骎。"]},{"t":"游雍丘燕溪分韵作","f":"五言律诗","c":["舍辔步平陆，解襟俯清池。","微风度修竹，瑟瑟生沦漪。","梨华照晴影，暖雪正纷披。","把酒久沈想，况与玉人期。"]},{"t":"游滕县时氏园池","f":"五言律诗","c":["珍重西园主，开门待子猷。","城隅树交荫，楼下水通流。","鸲鹆鸣深竹，蜻蜓驻小舟。","可能忘梦想，尘土满徐州。"]},{"t":"登乌江宝泉寺南山望金陵作","f":"七言律诗","c":["我爱金陵望不厌，独寻微径蹑晴岚。","柔桑浅草三月尾，踊塔飞楼一水南。","苒苒流云牵仿像，迟迟艳日助醺酣。","何须拊手歌桃叶，已觉王郎思不堪。"]},{"t":"登乌江柏子冈怀潘景仁","f":"五言律诗","c":["驱车柏子冈，引首东南望。","孤戍带寒日，长江流大荒。","故人越五岭，旅雁留三湘。","好待春风暖，相随还北乡。"]},{"t":"登快哉亭有属","f":"七言律诗","c":["南浦东风拂水文，汀洲芳草绿罗裙。","桃花旧叶应相望，杨叶新声我独闻。","酸鼻可怜香欲绝，断肠不待酒初醺。","斜阳归去书窗下，一幅蛮笺赋梦云。"]},{"t":"登海陵齐云楼","f":"七言律诗","c":["楼外浮云何可攀，聊持樽酒共销闲。","归心欻起登临际，春色来从想像间。","晚雪晞时见芳草，沧波尽处欠青山。","长安桃李行应好，解笑刘郎底未还。"]},{"t":"答王文举","f":"七言律诗","c":["茫茫尘土欲安之，珍重吾人个处期。","绿野相随一藜杖，青山正对两茅茨。","自怜悾惚负平昔，尚敢婆娑临暮迟。","第恐阿戎犹喜仕，它时不与五君诗。"]},{"t":"答王拙见寄","f":"七言律诗","c":["好在金陵王隐君，尺书忽与我相闻。","莼鲈久负秋风约，猿鹤终寻旧日群。","横笛卧吹南浦月，杖藜笑度北山云。","六朝陈迹何须问，一曲沧浪酒十分。"]},{"t":"答孙休兼简清凉和上人二首 其一","f":"七言律诗","c":["声迹相闻忽此逢，杖藜萧散一相从。","平生诗酒真吾事，何处江山不尔容。","芳草自生南北路，孤云难系往来踪。","异时荒戍长回首，风送石城楼上钟。"]},{"t":"答孙休兼简清凉和上人二首 其二","f":"七言律诗","c":["渭北人游楚水东，论诗说旧偶从容。","乡关此日几多远，春酒与愁相胜浓。","且免牛衣愧妻子，莫将羊酪诧吾侬。","哀王孙赖弥天释，肯学扬州饭后钟。"]},{"t":"答陈传道","f":"七言律诗","c":["吾家季真登大蓬，我为斗筲来宝丰。","公乎时以监呼我，自笑名同实不同。","樽酒相望今夜月，鲈鱼又负一秋风。","少须婚嫁匆匆毕，会买扁舟下浙东。"]},{"t":"答致仕吴朝请潜登黄鹤楼见招","f":"七言律诗","c":["城隅黄鹤莫登临，端使悲翁动楚吟。","日下长安人共远，天围梦泽岁方阴。","北风欲雪雁飞急，南渚始冰鱼伏深。","谁似草堂安隐客，下帷隐几不求心。"]},{"t":"谢米雍丘元章见过","f":"五言律诗","c":["今古两妙令，雍丘与太丘。","当时号清白，后日想风流。","吏鼾庭阴午，农歌野色秋。","吾非荀氏老，愧尔德星留。"]},{"t":"赋得枕上闻雁","f":"五言律诗","c":["朔吹飘惊雁，寒声彻枕前。","远违沙漠雪，不下汶阳田。","客梦悲中夜，归期隔故年。","莓苔与菰米，何处是湘天。"]},{"t":"辞酒","f":"五言律诗","c":["鲁酒一樽薄，吾愁万斛多。","尘埃斩马剑，涕泗饭牛歌。","髀肉生如许，颠毛黑几何。","功名可复道，身世两蹉跎。"]},{"t":"酬别法云彦上人","f":"五言律诗","c":["将别雁门师，殷勤访所之。","江湖怀北阙，鸥鸟恋南枝。","朝隐非吾所，山英不汝欺。","明年东下约，春水漾蘋时。"]},{"t":"酬别曾忱","f":"七言律诗","c":["昔年室迩叹人遐，少日相逢别日赊。","聊寄归心天北雁，会乘高兴斗边槎。","雷惊白昼龙蛇起，风荡青春草木华。","谁念渠伊独憔悴，岂容平世赋怀沙。"]},{"t":"酬别道师许自然","f":"七言律诗","c":["早慕浮云耻系匏，泠然风驭起三茅。","青菁可种无闲地，黄鹤归来失旧巢。","石鼎颇传惊俗句，醉图未免取僧嘲。","何须西望长安笑，谁是平生莫逆交。"]},{"t":"酬宗室令率惠墨","f":"七言律诗","c":["麝煤新剂黝而坚，谁谓奚生法不传。","信是文房希代宝，益知公子过人贤。","蔡中郎老喜飞白，扬执戟穷耽草玄。","雅意肯要琼玖报，十丸聊以助吾颠。"]},{"t":"酬桂林从叔","f":"五言律诗","c":["江到三湘尽，山围八桂深。","龙蛇寒下蛰，雾露昼多阴。","迢递驰梅信，殷勤访竹林。","淮南风土美，留滞亦何心。"]},{"t":"暮投葛墟马上","f":"五言律诗","c":["旬浃走千里，尘埃如有缘。","惭无季子印，可换洛阳田。","广泽雁行去，荒山雨脚悬。","长亭犹未见，疲马不胜鞭。"]},{"t":"潘豳老出十数诗皆有怀苏儋州者因赋二首 其一","f":"七言律诗","c":["人烟寂绝鬼门关，更指儋州杳莽间。","三四月交天漏雨，东南地尽水浮山。","依迷春草鸰原失，响像秋风鹤驭还。","回羡河阳贤父子，雪堂曾伴十年闲。"]},{"t":"潘豳老出十数诗皆有怀苏儋州者因赋二首 其二","f":"七言律诗","c":["旧隐江城东复东，堂前杨柳付春风。","犹传白雪兴中曲，俄失黄粱梦后翁。","儋耳吉音无雁使，峨眉爽气属狙公。","不应更广穷愁志，悟取平生坐底穷。"]},{"t":"题乌江丘氏昆仲岁寒亭","f":"五言律诗","c":["新甫移根远，苍然对两翁。","闭门三尺雪，仰枕一亭风。","东郭颜何厚，西来意莫穷。","未应输狭小，酿酒待春丛。"]},{"t":"题乌江东隆山邓氏亭","f":"五言律诗","c":["逋客今何许，空馀接隐亭。","舟随潮水上，门背夕阳扃。","兔策尘生蠹，渔蓑雨化萤。","题诗岩下石，聊代草堂灵。"]},{"t":"题永城县园水亭","f":"七言律诗","c":["诘曲池塘碧玉流，禊亭孤占小汀洲。","长纫座上芳兰佩，不系檐前画鹢舟。","好泛羽觞脩旧事，为书茧纸记清游。","季真待得东还日，初见红蕖十亩秋。"]},{"t":"题甘露寺净名斋兼寄米元章","f":"五言律诗","c":["日出天垠露，江横地轴分。","驰年悲落木，羁思托孤云。","重扫净名室，长招漫仕君。","悠悠德璋辈，未办勒移文。"]},{"t":"题任氏传德集","f":"七言律诗","c":["钓鱼公子学屠龙，潦倒西班八品中。","鼠目獐头登要地，鸡鸣狗盗策奇功。","仪刑拔士无光禄，经术传家有圣童。","慨想斯人安可作，九原松槚几秋风。"]},{"t":"题张氏白云庄","f":"五言律诗","c":["江左陶徵士，高风昔所闻。","应惭五株柳，难比一溪云。","我有乘桴约，君方植杖耘。","悠悠竟何得，晚岁盍同群。"]},{"t":"题杜仲观南康遗编后","f":"七言律诗","c":["高吟晚节动江关，自况孤云岂易攀。","赋鵩一篇传日下，骑鲸半夜去人间。","知音谁复称流水，招隐吾方拟小山。","固有清风千古在，不应空伴月明闲。"]},{"t":"题定山寺法远上人壁","f":"七言律诗","c":["支郎风味喜相亲，乘兴来寻雪后春。","夹径竹阴疑碍马，隔江山色似招人。","岂无暇日容高卧，如有闲田愿卜邻。","预约东城二三子，岁时相过莫辞频。"]},{"t":"题宝泉官舍壁","f":"五言律诗","c":["偶著强名字，非才但铸金。","不妨称外监，况复住山阴。","胜日聊披卷，清风故解衿。","馀生偷禄隐，何等是升沈。"]},{"t":"题金陵天庆观钟阜轩","f":"七言律诗","c":["霞构云扉不著关，甍檐开处见人间。","断墙废井连东第，白塔青松对北山。","昨夜桂娥奔月去，经秋芝盖御风还。","玉虚真籍家声在，再熟金桃愿一攀。"]},{"t":"题彭城张氏放鹤亭","f":"七言律诗","c":["曾见君家亭上碑，东望风月动闲思。","昔无卜筑如相待，今遂登临是不期。","万顷白云山缺处，一庭黄叶雨来时。","许昌应负重泉恨，当日阳春枉赋诗。"]},{"t":"题海陵寓舍四首 其一","f":"七言律诗","c":["藜藿荒庭微径通，支撑破屋古池东。","暮凉百燕抵突雨，昼静一蝉饕餮风。","隐几敢希南郭久，移文方诮北山空。","森然槐柳相差地，它日低回忆个中。"]},{"t":"题海陵寓舍四首 其三","f":"七言律诗","c":["倒障开窗面曲池，尘襟初喜豁然披。","清风殊不去人远，明月端能与我期。","鼓吹青蛙聊自喜，歌讴白鸟渐相欺。","纷纷利害朝昏出，闭目忘言是住持。"]},{"t":"题海陵寓舍四首 其四","f":"七言律诗","c":["千里家园安在哉，羁栖犹喜占池台。","酒非从事断年别，风是故人弥日来。","黄鸟绵蛮紫椹熟，白鸥瀺灂绿萍开。","颇知老子机心废，留得渠伊兴尽回。"]},{"t":"题秦观少游写真","f":"五言律诗","c":["淮海多才士，徒希马少游。","谁容老芸阁，自谶死藤州。","状貌披图爽，阳春掩卷愁。","湛郎长鬣尔，殊不嗣风流。"]},{"t":"题诸葛谼田家壁","f":"五言律诗","c":["晚度孔明谼，林间访老农。","行冲落叶径，坐听隔江钟。","后舍灯犹织，前溪水自舂。","无多游宦兴，卜隐幸相容。"]},{"t":"题渊明轩","f":"七言律诗","c":["渊明新榜揭门眉，夫子高情俗不知。","未仰秫粳供岁计，本于松菊有心期。","卧来不浅羲皇兴，归去何惭乡里儿。","窗破檐倾从此始，祇应风月解相思。"]},{"t":"题彭城南台寺苏眉山诗刻后","f":"七言律诗","c":["秋风几度老江蓠，鼎水眉峰隔梦思。","下走误传宣室召，上前谁进子虚辞。","东坡麋鹿同三径，西掖鹓鸾占一枝。","独有野僧违一俗，翠珉新勒旧题诗。"]},{"t":"题皖山北濒江田舍","f":"七言律诗","c":["江转皖公山北流，萧闲人物美田畴。","一溪春水百家利，二顷夏秧千石收。","小市竹楼张酒旆，平桥松岛荫渔舟。","莫知农老何为者，几叶传封乐国侯。"]},{"t":"赠张之才","f":"七言律诗","c":["夙龄垂耳慕飞黄，晚岁相逢两漫郎。","浼我青衫奈尘土，误君白首坐文章。","折腰仅厌米五斗，满腹莫骄钱一囊。","多病劳生馀有几，买山筑室愿邻墙。"]},{"t":"赠张士元","f":"七言律诗","c":["夫子安贫五十年，年来生事更茫然。","青衿稚子彼何有，白首故人谁见怜。","霜后鹑衣寒绽线，日高鱼釜冻无烟。","冗官犹愧苏司业，不得时时送酒钱。"]},{"t":"赠僧彦","f":"七言律诗","c":["昔年杖舄几相从，同遇弥天汉上翁。","早恨扬舲南浦别，俄惊扫地北山空。","壮心脱落浮云外，病骨枝梧梦境中。","赖有西岩旧桃李，异时应许共春风。"]},{"t":"久病寄二三亲友","f":"五言古诗","c":["早昧摄生理，百劳戕至真。","药灵翻佐病，诗癖竟穷人。","终负黄垆恨，长违白首亲。","一囊安可得，四壁未应贫。","灯下尘编泪，风前墓草春。","傥忘鸡酒设，腹痛勿多嗔。"]},{"t":"东畿舟居阻雪怀寄二三知旧三首 其二","f":"五言古诗","c":["寒洛未澌结，东趋江海深。","舟人惊朝鼓，敛繂逗长林。","林端落滞雪，沙际起鸣禽。","病客坐长叹，摄衣涕流襟。","亲朋自兹远，可是慕山阴。","兴尽莫回楫，何人知此心。"]},{"t":"东畿舟居阻雪怀寄二三知旧三首 其三","f":"五言古诗","c":["沄沄清川流，冉冉浮云阴。","天寒日云莫，鱼鸟方潜沈。","吾岂厌安隐，东浮违宿心。","一官未足养，老境行侵寻。","牛歌感白石，马骨要黄金。","惭无子虚作，万里悬知音。"]},{"t":"邯郸郡楼晚望","f":"五言古诗","c":["新凉泻轩槛，草木带秋声。","阔水倒岚影，洗磨刀戟明。","百虫暮吟动，一鸟归思轻。","晚律骇徂景，羁怀念劳生。","去国亦已久，己年今复庚。","官仓容雀耗，世路忌蜗争。","顾我实荒浪，误抛樵与耕。","竹木微径在，奚独古人行。"]},{"t":"郎官湖","f":"五言古诗","c":["当年贤守令，载酒沔南游。","凉月呈新霁，明湖涵素秋。","郎官夏口使，仙客夜郎囚。","促膝青螭舫，连觞紫绮裘。","高驩随雨散，馀躅想风流。","芳草失青履，沧波浮白鸥。","江吞百顷尽，石刻一篇留。","宜有沈碑者，前怀陵谷忧。"]},{"t":"得周元翁蕲春道中书","f":"七言古诗","c":["离离赤枣墙东林，开窗下榻依墙阴。","杖藜相顾赖之子，隐几忘言知我心。","晚契初逢一东野，清诗屡掷双南金。","官身为米自南北，世路亡羊无古今。","梦泽草荒孤驿远，洞庭雨入沧江深。","相思何以祝高韵，桂树秋风吟玉琴。"]},{"t":"登黄鹤楼怀古兼寄潘豳老昆仲","f":"七言古诗","c":["汉大将军楚国材，半生倦韵浼尘埃。","徐夫人匕首安在，丁令威华表归来。","紫府无踪劳彷像，白云有待久裴徊。","楼标空阔天垠露，川势从横地纽开。","陇鸟赋成洲共永，越人歌断棹先回。","会招物外二三子，长啸披襟挹快哉。"]},{"t":"题杨子王辂故居清轩","f":"五言古诗","c":["卜筑负南郭，褰开临要津。","舟舆占集地，奈尔独清人。","坐上一樽酒，江南千里春。","何须茂弘扇，何患元规尘。","游子感陈躅，恍如平生亲。","九原不可作，归老复谁邻。"]},{"t":"九日雨中作","f":"七言古诗","c":["九夏赤旱百井枯，三秋积雨釜生鱼。","淩高径醉不易图，问底黄叶今有无。","愿致皎白来庭除，昏瞳烂卷勤卷舒。","管中一班聊自娱，未羡北里鸣笙竽。","少日用壮胆力粗，六鳌可取负而趋。","谁谓衰迟百病馀，雀鼠入屋不受驱。","长铗长铗归来乎，泥深没胫行无车。","咄嗟蜡屐非双凫，安得翩然过故都。"]},{"t":"人生七十稀","f":"五言古诗","c":["人生七十稀，行年今已半。","事功贵及时，迟暮复何算。","嗟吾夙多负，失怙在童丱。","诗礼思有闻，飘飖辞祖贯。","慈亲念衰绪，猝猝营婚宦。","名姓系西班，星霜亟徂换。","未筑黄金台，长歌白石烂。","岂无同心契，相望眇云汉。","每虞狂飙至，摧折涧底干。","异日偶班输，抱柯徒永叹。"]},{"t":"三山","f":"五言古诗","c":["南朝凤皇台，置酒昔高会。","酒酣望三山，宛在青天外。","长哦谪仙吟，如啖鲸鲵鲙。","明日信东风，孤帆出其背。","荒戍接江濆，开门适相对。","鼎足跱长川，不为舟楫碍。","雨旸云吞吐，早晏潮进退。","万古免浮沈，曾微抃鳌戴。","伊余厌尘坌，闭目何可奈。","爽气豁襟灵，山乎吾有赖。","尝闻晋阿童，万舻飞戈快。","径造此山陲，沧波为之隘。","顾我疲软姿，功名让前辈。","玄晖昔凭眺，物色颇有在。","他时挂武冠，刀剑行且卖。","山价略可酬，庵栖谢当代。","远持三山矶，况彼七里濑。","犹得傲狂奴，吾无故人待。"]},{"t":"三月二十日游南台","f":"五言古诗","c":["晴春六十日，不与酒杯亲。","吏事岂无閒，风雨复兼旬。","始作南城游，时物固已陈。","扫不见桃李，浓绿迷荆榛。","登高暂逍遥，引目清泗滨。","向田有交径，俯城皆要津。","得意属禽鱼，可爱不可驯。","顾余千里客，眷此十日春。","胡不念尔生，筋骸劳欠伸。","二十起丁籍，一官初为贫。","侜张西复东，甑满莱芜尘。","黄绶彼何物，豕苓安足珍。","山园有芳兰，幽佩手自纫。","长哦白云谣，遐想紫阳真。","去矣南昌尉，庶几乎若人。"]},{"t":"三鸟咏 提壶引","f":"词","c":["绿野带江春漠漠，露湿花蔫朝暮薄。","年芳婉娩欲辞人，啼鸟殷勤劝行乐。","提壶真起予，十千美酒当剩沽。","金龟宝貂家所无，持底可过黄公垆。","调官东来今几日，谓有公田宜种秫。","朝廷未除私酿律，安得一试焦革术。","提壶鸟，叹吾与尔皆悠悠。","君不见长安两市多高楼，大书酒旆招贵游。","脱闻提壶鸣树头，论槽买瓮更献酬。","庶几此声知所投，胡为南乡长滞留，端使北宗狂客羞。"]},{"t":"三鸟咏 竹鸡词","f":"词","c":["东南泽国陂塘阔，旱岁少逢晴五月。","田间蛙喜雨冥冥，竹下鸡啼泥滑滑。","而予不耕陂下田，田皋驱马挥长鞭。","稻塍微茫绝复连，如蹑镜面流鲛涎。","植蹄沮洳不敢前，何暇顾惜青莲乾。","竹鸡鸟，汝幸飞翔罗罻外，安知此涂吁可畏。","雄雌更鸣方自慰，汝不能言意为对。","君不见日围赫赫是长安，大明宫阙开云端。","鸡人唱漏辰三刻，左右相君朝谒还。","前驺谁敢干，后乘不可攀。","飘飖青盖望已远，绿槐阴下沙堤闲。","长堤千步沙漫漫，风不惊尘雨亦乾。","君能驰骛此其所，何事江乡行路难。"]},{"t":"三鸟咏 子规行","f":"词","c":["长江靡迤山坡陀，旅竹荒松蒙茑萝。","蚕初眠起风日暖，梅弄黄时烟雨多。","山间有径行逶迤，倦客据鞍生睡魔，奈尔思归啼鸟何。","子规鸟，不如归去好。","谁家西北最高楼，几为王孙怨芳草。","子规怜尔解归飞，我独何心长不归。","十年迹绝苏门道，梦里旧游知是非。","一官窃食官仓米，十口之家饱而已。","金印锦衣耀闾里，少年此心今老矣，问舍求田从此始。"]},{"t":"上巳有怀金明池游赏","f":"七言律诗","c":["西城小雨宿尘消，春水溶溶拍画桥。","拾翠汀洲白蘋发，披香宫殿紫云高。","綵舟日晚绮罗醉，油幕风晴丝管焦。","侠少朋游应念我，一年佳赏负今朝。"]},{"t":"亡女胜璋哀辞","f":"七言古诗","c":["百痾沉顿弥两年，何图壮女死我先。","失声忍号气窒咽，泪如绠縻汲九泉。","呜呼尚敢尤诸天，托非其人死失所。","父孱母嚣犹弃汝，吞辛咀楚申何许。","萎荑殒英春不主，呜呼万古为冤土。"]},{"t":"广四愁寄李譓","f":"楚辞体","c":["夜如何其夜未央，斗星灿兮河苍凉。","微月入牖窥曲房，候虫刺促鸣我床。","离忧欻来煎人肠，夜如何其夜何长。","绿琴在荐兮，拟楚奏之沈湘。","朱弦湿露兮，声戾指而不扬。","屏琴浩歌兮，屑涕泗之浪浪。","我有所思兮，在河之阳。","僾而不见兮，衷难弭忘。","騄骥腾跃兮，鸿鹄翱翔。","明珰玉案兮，尔不我将。","缄诚结惠兮，久莫汝偿。","永如牛女兮，南北相望。","昔燕处兮，灵芸之堂。","纫兰为佩兮，集芰为裳。","西风凄紧兮，淩百草以殒黄。","兰萎芰裂兮，恐被服之不芳。","念汝玉立兮，贱组绣之文章。","玄节日厉兮，奈惨慄之冰霜。","胡不乘白云兮，归来乎帝乡。","尚何所徯兮，毕永岁而彷徉。"]},{"t":"广津门东马上","f":"五言律诗","c":["津头落帆鼓，薄暮尚蓬鼕。","疑是秦淮口，扁舟醉梦中。","不堪隋岸北，尘土一鞭风。","传语端能否，伯劳飞自东。"]},{"t":"广陵山光寺夜集留别黄材昆仲","f":"五言古诗","c":["维舟山光步，却顾广陵城。","十里春风外，夹津芳草生。","渔篷衔尾来，愧尔故人情。","更卜连床语，神房温且清。","语阑夜自久，泪烛剪复明。","撤樽兀相视，酸涕流金缨。","我本山海士，误遭时网婴。","出身两纪馀，何等为浮名。","矧此一分首，几年当合并。","离忧如惊澜，荡潏未易平。","疏亲系远迩，斯言出荒伧。","音邮无禁限，勤访白云兄。"]},{"t":"飞鸿亭","f":"五言古诗","c":["禅林跨山胁，飞构凿崚嶒。","千里寄双睫，百忧消一登。","斯游属公暇，晓日东南升。","霜野明练甲，云阴垂海鹏。","东州地阳暖，腊月川无冰。","大艑出洪口，突去如骞腾。","趺坐思方寂，桐鱼闻饭僧。","生台饱驯鸽，散上浮图层。","矫首发长啸，清风鼓尘膺。","寥寥紫虚路，鸿雁正凭凌。","仿像中散公，俯手朱丝绳。","粉绘久零落，爽灵呼不应。","顾余识尤寡，况复无才称。","行且置缨笏，庵栖宗大乘。","二子勿多诮，有心何不能。"]},{"t":"历阳十咏 其一 历湖","f":"五言律诗","c":["昔也万家邑，今为无底渊。","城郭泯遗迹，人民安得全。","吊古一回首，薄暮愁风烟。","拯溺不无意，吾生后千年。"]},{"t":"历阳十咏 其七 采石矶","f":"五言律诗","c":["东西采石矶，山水两清绝。","渔舠与商舶，今古几沿越。","飘飖翰林主，长笑弄明月。","难访物外游，飞云眇天末。"]},{"t":"历阳十咏 其九 桃花坞","f":"五言律诗","c":["种树临溪流，开亭望城郭。","当年孟张辈，载酒来行乐。","斯人久埃灭，节物今犹昨。","看取不言华，春风自相约。"]},{"t":"历阳十咏 其八 百福寺","f":"五言律诗","c":["文昌西郭居，修竹闭环堵。","琴樽不复存，青莲开梵宇。","尘纷晦遗像，粉绘才可睹。","拜奠愧无言，长哦君乐府。"]},{"t":"历阳十咏 其十 平痾汤","f":"五言律诗","c":["文础护清漪，炯若涵冰玉。","澡涤起沈痾，功参灵剂速。","荒唐桑氏经，琐碎桐君录。","利物本无穷，何须尘简牍。"]},{"t":"历阳十咏 其三 濡须坞","f":"五言律诗","c":["孙郎昔鹰扬，曹瞒方虎视。","敢忘板筑勤，远挫兵锋锐。","俄闻青盖谣，无复金陵气。","六代迭倾亡，长江亦平地。"]},{"t":"历阳十咏 其五 当利港","f":"五言律诗","c":["龙骧乘上游，锐气吞敌境。","风便趋吴京，收功在俄顷。","平生负雄图，晚岁方获骋。","何必传鼎彝，江山与之永。"]},{"t":"历阳十咏 其六 天门山","f":"五言律诗","c":["天门束箭流，北注据牛弩。","淩高驻翠华，舟师耀威武。","当时侍帷幄，谁复徵往古。","虞舜有苗征，端为两阶舞。"]},{"t":"历阳十咏 其四 遏胡城","f":"五言律诗","c":["狂胡昔凭凌，阔步长淮外。","难此百雉城，万甲屯要害。","时平一登望，江山互襟带。","想像文献公，清风宛如在。"]},{"t":"历阳姥矶下马上有怀京都游好","f":"七言律诗","c":["楚泽初冬正穫田，孤鸿欲下却翻然。","人烟隐约青山郭，云物离披小雪天。","送别杯盘犹昨日，劳生鞍马遂穷年。","故人多在金闺籍，谁念寸心如断弦。"]},{"t":"长安在何许二首 其一","f":"五言绝句","c":["长安在何许，疑是青天上。","矫首溯西风，溪云断人望。"]},{"t":"长安在何许二首 其二","f":"五言绝句","c":["长安在何许，疑在白日下。","徘徊天一隅，华月生新夜。"]},{"t":"丛台歌","f":"词","c":["累土三百尺，流火二千年。","人生物数不相待，摧颓故址秋风前。","武灵旧垄今安在，秃树无阴困樵采。","玉箫金镜未销沈，几见耕夫到城卖。","君不见丛台全盛时，绮罗成市游春晖。","一从雕辇闭荒草，萧散行云无复归。","韶魂想像风流在，晴华露蔓犹依稀。","盘纡棘径撩人衣，禾黍晚成貊貉肥。","层檐碧瓦碎平地，梦作鸳鸯相伴飞。","登临吊古将语谁，城郭人民今是非。","指君看取故时物，南有清流西翠微。","彷徨华表不忍去，岂独辽东丁令威。"]},{"t":"东华马上怀寄清凉和公兼简社中王拙居士","f":"词","c":["鸡鸣紞五鼓，驱马东华路。","月落潮上时，云披日生处。","摇摇渔艇子，挂席淩江去。","送目思悠悠，横槊聊一赋。","鸿雁南飞江北流，亭亭双塔是升州。","前朝物色今何见，白鹭平沙接石头。","石头城上清凉国，中有弥天大比丘。","右军远孙傲时者，巾钵久从莲社游。","吾亦明年及瓜代，一庵见寄外何求。"]},{"t":"东畿舟居阻雪怀寄二三知旧三首 其一","f":"五言古诗","c":["舟路江淮永，岁寒冰雪深。","戍期良敦迫，王畿方滞淫。","疲筋苦跧卧，行药长川阴。","云物接平陆，不见西飞禽。","风从城阙来，如闻钟漏音。","昕霁更东迈，区区子牟心。"]},{"t":"冬夜寓直","f":"五言古诗","c":["落月半侵窗，蛩声寒到床。","羁人不堪此，梦后夜仍长。","结衣出庭户，河汉正苍凉。","浮阴暝四野，来雁不知行。","陈物悲暮节，畏途怀故乡。","十年泥滓贱，半生靴板忙。","岂不志事功，筋骸难自强。","壮毛抽寸霜，烈胆磨尺钢。","素尚竟谁许，行歌追楚狂。"]},{"t":"卯醉口号","f":"七言绝句","c":["丙寅元祐初年冬，贺老困寓京尘中。","无心炙手权门热，曝背晴阳坐屋东。"]},{"t":"对酒","f":"五言古诗","c":["白驹不可驻，尺璧非所珍。","独挹一樽酒，悲歌送徂春。","歌阑酒亦尽，回首迹已陈。","自笑十年仕，尚迷天下津。","岂无濯缨水，奈尔长路尘。","命也复何道，今人犹昔人。"]},{"t":"玉钩环歌","f":"七言古诗","c":["良工得玉蓝溪窟，相璞命形心匠出。","螳螂倔彊疑有骨，颈系一环犹莫屈。","镜湖老狂厌袍笏，素裰纁绦须此物。","价比连城不容乞，王孙辍好人所难。","何以报之明月盘，薰炉波面山巑岏。","吾乡美笴鹍鸡翰，闽瓷兔碗霜毛寒。","称是头贡双龙团，聊送公斋增冗长。","短歌粗可评珍贶，吾方野装事游放。","局步臞颜曳藜杖，薄暮微吟江汉上。","彼渔丈人误相访，谓似三闾大夫样。"]},{"t":"田园乐","f":"五言古诗","c":["昔我未去国，幽栖淇上村。","分辞侠少事，喜与农老言。","农老孰追从，四邻皆世婚。","机中工织妇，籍上成丁孙。","青驹自走磨，黄犬长候门。","昨日春火开，逍遥望高原。","西照牛羊下，东风花草繁。","今朝夏鸡鸣，麦熟田头喧。","归来息树荫，课汲灌中园。","秋赛方及辰，酿秫烹膏豚。","丛祠响腰鼓，免杖奉神樽。","冬雪断门巷，蚕庐清且温。","地藉熊豹席，炉明荆枥根。","起居就安适，非复系晨昏。","不识百里面，不知千骑尊。","供输先众期，于我何威恩。","太上复淳古，坐超羲与轩。","敢忘天地施，击壤声如埙。","毕此百岁愿，泰然长夜魂。","避秦谁氏子，客死武陵源。"]},{"t":"再由赤埭有怀曹梦得","f":"七言律诗","c":["江上颠风倒客樯，江豚舞浪卷浑黄。","故人漂泊知何处，何日平安到故乡。","野色苍茫春尚浅，梦魂惝恍夜仍长。","可无百斛兵厨酝，此段离忧未易忘。"]},{"t":"戏答张商老","f":"七言律诗","c":["扬子江头两信潮，送君西去木兰桡。","依依暮雨鸳鸯梦，袅袅春风豆蔻梢。","细字碧笺随雁到，小帘朱户抵天遥。","长安触绪牵情地，不特魂销骨亦销。"]},{"t":"此日足可惜","f":"五言古诗","c":["此日足可惜，此樽何可辞。","人生信浮寓，老境将安之。","念昔青衿岁，九七殊未知。","忽忽俯仰间，复见趋庭儿。","名系冗从籍，顾亦胡能为。","抚此多病躯，敢有黄发期。","每虞毙奔走，明哲永见嗤。","后日卖刀剑，买牛耕故陂。","不惮力作勤，农事有閒时。","慨想无心子，清言真我师。"]},{"t":"江南曲","f":"词","c":["游倡搴杜若，别浦鸳鸯落。","向晚鲤鱼风，客樯千里泊。","当时桃叶是新声，千载长馀隔水情。","乌衣巷里人谁在，白鹭洲边草自生。"]},{"t":"江夏秋怀三首 其二","f":"七言律诗","c":["人物骎寻迫暮迟，秋风万里来如期。","幽虫切切竟何道，羁燕匆匆将安之。","洛下微吟聊拥鼻，西山爽气为支颐。","肯将翰墨悲流落，寄语三闾彼一时。"]},{"t":"江夏寓兴二首 其二","f":"五言律诗","c":["陂湖蹙坊市，江汉复纵横。","沮洳莎城阽，晴旸竹瓦鸣。","新文添鵩赋，异味识鼋羹。","岂复悲流落，官粮寓此生。"]},{"t":"老槐","f":"五言古诗","c":["老树久枯秃，俯临清路尘。","曾无席地阴，庇暍及斯民。","枭巢与狐穴，凶怪相凭亲。","嗥啸属阴黑，惊摇旁近人。","周环筑级坛，立社祠秋春。","既享不材寿，滥当有土神。","勿惑巫妇言，请挥樵者斤。","犹疑终窃据，复作后来薪。"]},{"t":"老鹤叹","f":"词","c":["华表华表归来乎，出无车，食无鱼。","懿公之遇难再图，卑栖剩啄同群雏。","谁谓嵇氏子不孤，强颜市井交屠沽，巨源密启亦已疏。","呜呼，卫侯既不可作，道林今也则无。","露鸣风舞何区区，夙夜供君耳目娱。","西山二子饥相似，南国三闾放不如。","端虑盘飧怀异味，并随焦尾付庖厨。"]},{"t":"自历阳汎江至赤埭访别曹解","f":"七言律诗","c":["我访故人不待招，沧江谓广才容舠。","离城五点寒更急，著岸两竿晴日高。","别来书尺正坐懒，老去鞍马何堪劳。","明年淮上更携手，醉步卧虹千丈桥。"]},{"t":"舟次金陵怀寄历阳王掾相","f":"七言律诗","c":["昨时江北望江南，把酒离愁已不堪。","今夜江南望江北，抵掌清谈安可得。","历湖白下非吾乡，官身俗眼禁人狂。","后日扁舟更西去，江北江南两何处。"]},{"t":"行路难","f":"五言古诗","c":["惊飙猎榛莽，西山匿颓阳。","四五阴魄晚，繁星亦光芒。","驱车何所投，却顾归路长。","挟辕两羸牸，犯此豺虎场。","安得渥洼骏，皎旦游康庄。","岂徒写我忧，要使尘不扬。"]},{"t":"访周沆郭忱","f":"五言古诗","c":["前日去薄官，驱车望城阙。","情亲周与郭，契阔多年别。","征袍未及解，径造郊扉谒。","存问审安娱，芝眉尉怀渴。","家饱具羹炙，笑我犹饕餮。","野色夜苍茫，松阴步微月。","悲风应长啸，洒面若冰雪。","狭室烛花青，坏炉拥驼褐。","欢呼讲旧好，邻梦憎惊聒。","念昔初冠年，朋从事颠蹶。","匆匆一回首，身志成老拙。","居诸信遄迈，又值阳生节。","春物行可期，良游须屡结。","妇家酒醅美，升斗容丐辍。","斟酌挹东君，手选时芳折。","樽前有馀乐，身外无所切。","欲寻玉清路，难访金丹诀。","修短三万朝，黄尘共埋灭。"]},{"t":"迁家历阳江行夜泊黄泥潭怀寄冯善渊","f":"七言律诗","c":["黄泥潭口舣征篷，回指东城祗眼中。","半夜凫鹥先觉雨，连江葭菼自生风。","青灯解作无眠伴，白酒难招一醉同。","从此相思寖相远，便凭归棹附诗筒。"]},{"t":"过鼌掾端智","f":"五言古诗","c":["西风吹晚雨，饥雀噪寒丛。","文举对谈客，坐惭觞豆空。","咄嗟宦游子，贫病略相同。","斗俸折腰得，醉钱常不供。","君看北里儿，高堂燕歌钟。","虽誇酒无算，饱德何由丰。","吾岂乞墦者，不为妻妾容。","永怀冰檗操，未愧屠酤雄。"]},{"t":"过澶魏被水民居二首 其二","f":"七言绝句","c":["莫问居人溺与逃，破篱敧屋宿渔舠。","中庭老树秋风后，鹳鹤将雏夺鹊巢。"]},{"t":"问内","f":"五言古诗","c":["庚伏厌蒸暑，细君弄针缕。","乌绨百结裘，茹茧加弥补。","劳问汝何为，经营特先期。","妇工乃我职，一日安敢堕。","尝闻古俚语，君子毋见嗤。","瘿女将有行，始求然艾医。","须衣待僵冻，何异斯人痴。","蕉葛此时好，冰霜非所宜。"]},{"t":"别王铚性之","f":"五言律诗","c":["吾老无北里，子能讵南来。","临分即间诀，薄暮更徘徊。","晚节徇微尚，方刚患多才。","此生南与北，出处两悠哉。"]},{"t":"快哉亭","f":"五言古诗","c":["飞亭冠城隅，空豁延四望。","夙昔两文雄，故床此相向。","山川气候美，诗酒风神王。","弹压许昌侯，阳春惭俚唱。","麾车忽南北，荣辱生誉谤。","一躐云逵间，一落江湖上。","我来得陈躅，伏槛徒怊怅。","可畏此尘笼，归哉养荒浪。"]},{"t":"怀寄周元翁十首 其一","f":"五言古诗","c":["周郎假沔官，我偶来沔居。","得闲定相过，谈笑沈痾袪。","俄闻戍楼角，晓引吹咿呜。","自君居湓城，恍恍一梦馀。","复求若辈人，陶灶搜璠玙。","诚为天下士，岂特江汉无。"]},{"t":"怀寄周元翁十首 其二","f":"五言古诗","c":["周郎嗜茗饮，偶与吾好同。","赠行发吾宝，紫璧雕云龙。","此实太官物，分甘玉堂公。","我曹百石吏，藜菽每不充。","诗人盍得尝，可以骄万钟。","愿君间一歠，千里共清风。"]},{"t":"怀寄周元翁十首 其八","f":"五言古诗","c":["周郎强仕年，药石甘苦口。","得无耗天和，汤剂禦衰朽。","空华与□色，种种竟何有。","妄爱温柔乡，荡然不回首。","坐令松桂姿，凋脆等蒲柳。","幸勿易斯言，前车镜湖叟。"]},{"t":"怀寄周元翁十首 其六","f":"五言古诗","c":["周郎西笑时，叠寄两函书。","情亲语恳到，骨肉所不如。","妙翰骋遒放，抵突黄与苏。","黄癯曳羸筋，苏厚凝腯肤。","我于季孟间，增少损有馀。","家鸡敢复道，储此橐中珠。"]},{"t":"怀寄周元翁十首 其四","f":"五言古诗","c":["周郎妙雅道，五字可人师。","许与非不严，奈何取我诗。","我诗如秋虫，徒增长年悲。","指疵固有望，逐臭得无嗤。","诗鸣人必穷，我穷岂所宜。","愿君勿阂此，晚节益经奇。"]},{"t":"怀寄周元翁十首 其三","f":"五言古诗","c":["周郎尘外人，冰甃立寒玉。","去我千里馀，炯炯长在目。","有德且有言，可采篆缣竹。","未为造物怜，方徇斗筲禄。","司晨属群鸡，安事彼鸾鹄。","聊自况疲驽，盐车不为辱。"]},{"t":"怀寄周元翁十首 其九","f":"五言古诗","c":["周郎有史才，班马可并驱。","纷纷谗谄人，畏君笔削诛。","我恨接君晚，要亦君之徒。","沈痾积岁月，顾此留须臾。","志我圹中石，赖君文不谀。","庶乎陵谷变，名字见君书。"]},{"t":"怀寄周元翁十首 其十","f":"五言古诗","c":["周郎贯江华，而复厌湖湘。","我亦非乐此，西归计茫茫。","颓年抱沈痼，生理岂得长。","后期真何时，存殁两莫忘。","怀君辄赋诗，落笔联十章。","它年一掩卷，为我涕浪浪。"]},{"t":"怀寄周元翁十首 其七","f":"五言古诗","c":["周郎走王都，马足尘翻波。","贺老宦江夏，无人惊雀罗。","出处躁静间，奈此贫病何。","平生解指誓，晚境忽婆娑。","迫死不得休，前言食已多。","尚敢厌闲冷，欻为赴火蛾。"]},{"t":"怀寄周元翁十首 其五","f":"五言古诗","c":["周郎归濂溪，旱燥害嘉谷。","仰饱百指馀，嗷然坐空屋。","应书乞米帖，得继朝来粥。","行升大夫籍，月赐万钱禄。","振显属他年，盘飧罗海陆。","毋忘佛子言，不食大夫福。"]},{"t":"怀寄清凉和上人二首 其一","f":"五言绝句","c":["不见江南客，愿听江南钟。","倾耳度遥夜，天寒多北风。"]},{"t":"怀寄彭城朋好十首 其七 王十三","f":"五言绝句","c":["不见会之久，每思诗酒豪。","扁舟由甬上，乘兴可须招。"]},{"t":"怀寄彭城朋好十首 其九 寇十一","f":"五言绝句","c":["寇叔情何厚，邮筒数得书。","前春应上冢，能访酒家无。"]},{"t":"拟王少伯新兴","f":"五言律诗","c":["西北云悠悠，东南日杲杲。","浪语问阴晴，悬知行雨少。","桃蹊换青荫，夙昔一何好。","临牖思茫然，微风动萱草。"]},{"t":"拟阮步兵夜中不能寐","f":"五言律诗","c":["夜久不成梦，张灯开故书。","清霜屏云物，有月来庭除。","良时怅难再，不与佳人俱。","掩卷长太息，望子城之隅。"]},{"t":"拟温飞卿","f":"五言古诗","c":["露网朱甍上，风帘翠锁前。","宿衾熏萏菡，朝镜拂漪涟。","津润销金笔，香依扑粉绵。","度闲双陆子，拨恨十三弦。","鹦鹉殷勤语，旃檀委曲烟。","鲛绡乾玉箸，鱼钥限金莲。","团扇酬桃叶，乌丝代杏笺。","朱门长窅窅，白马自翩翩。","难钓三珠树，徒抛七宝鞭。","酒阑应有待，梦破即无缘。","信鹊新秋去，孤蟾后夜圆。","浪言墙外地，的是洞中仙。"]},{"t":"拟鲍溶寒宵叹","f":"五言律诗","c":["孤缸照愁眠，明灭知夜久。","荧荧月落床，摵摵风入牖。","美人怅何许，寤言不相偶。","心寄南征鸿，云汉长回首。"]},{"t":"补感寓诗","f":"五言古诗","c":["猛虎未出柙，扰如搏鼠狸。","苍鹰方在韝，孱甚伏卵雌。","弭戢以违祸，孰云尔无知。","幸遭纵释仁，返谓人可欺。","岂复念前辱，摇尾垂翅时。","择肉毙侪类，戕忍犹天姿。","吾将罪虞者，奈何生致之。","南山有重阻，邓林无樛枝。","机阱与罗罻，今也将安施。"]},{"t":"诅蚊","f":"五言古诗","c":["公舍踞阴沟，维蚊得所在。","朝昕灭声迹，曛暮相期会。","挟是党与繁，岂资躯力大。","饥心过狼贪，毒喙甚蜂虿。","侜张巧中人，勇悍将何奈。","贫无绡葛裯，拙计燃萧艾。","徒自取熏蒸，举家更嚏咳。","烟销尚鼓箑，夜久禦益懈。","坦腹恣交攻，烦痒如搔疥。","神疲复梦悸，少不容清快。","如何造物工，种此生民害。","安得长风驱，投诸四荒外。","断之严霜诛，并命不可贷。","丑类傥一遗，馀孽行当再。"]},{"t":"闲情二首 其二","f":"五言律诗","c":["秋风动朱箔，流尘污鸳绮。","念昔合欢人，两心今万里。","冰霜变松竹，况复如桃李。","欲寓相思文，无多右军纸。"]},{"t":"闲情二首 其一","f":"五言律诗","c":["青窗隐夕曛，玉甃紫苔春。","佳人久不见，翠被销檀薰。","长巾拂绿绮，上有三年尘。","聊弹别燕弄，寄谢阳台云。"]},{"t":"阻风白鹭洲招讷上人","f":"七言律诗","c":["凤皇台下凤皇巢，白鹭洲边白鹭涛。","舟未解维先望见，风能传语更相招。","江南春物为谁好，淇上归心不自聊。","何日结茅钟阜尾，幅巾相对一方袍。"]},{"t":"陈留道中","f":"七言绝句","c":["强半春风掩户庭，出门唯见麦青青。","从来赤白歌桃李，曾与何人伴醉酲。"]},{"t":"京居感兴五首 其五","f":"五言绝句","c":["长言与短调，谁谓高游艺。","谩赋芳草篇，长安居不易。"]},{"t":"京居感兴五首 其四","f":"五言绝句","c":["扰扰尘笼下，容身亦自贤。","横尸道边子，共笑直如弦。"]},{"t":"京居感兴五首 其三","f":"五言绝句","c":["稠人致高位，一二难遽数。","骠骑彼将军，未应贤第五。"]},{"t":"京居感兴五首 其二","f":"五言绝句","c":["平生感激心，炯炯徒自许。","尘埃五十弦，难为齐人拊。"]},{"t":"京居感兴五首 其一","f":"五言绝句","c":["壮图可复道，罄折营五斗。","负郭二顷田，何时落吾手。"]},{"t":"变竹枝词九首 其九","f":"五言绝句","c":["蒹葭被洲渚，凫鹜方容与。","但闻歌竹枝，不见题鹦鹉。"]},{"t":"和同行潘生悒悒悠悠二首 其一","f":"五言绝句","c":["悒悒复悒悒，愁眠成梦泣。","薄暮落花天，高楼面风立。"]},{"t":"和张谋父游石佛山观魏太武书","f":"五言古诗","c":["中夏昔屯否，代邦天所开。","鸿图属太武，不世英雄才。","南洗洛阳血，西荡长安灰。","毡车十万乘，略地驱风雷。","一苇济长淮，筑宫瓜步隈。","东邻拜牢饩，走使为婚媒。","云旗即归路，览胜此裴徊。","俯挥铁马鞭，顽石同陶坏。","划成四大字，屹栗阴虹摧。","沦精入崖壑，怒气羞蟠回。","茫茫六百年，风雨生莓苔。","伟迹寖销泯，威灵安在哉。","生存贵无上，零落等尘埃。","君为访古游，赋诗追七哀。","人生谁不尔，莫负手中杯。"]},{"t":"和杜仲观青字诗二首 其二","f":"五言律诗","c":["白马青络头，青萍宝带钩。","青溪流水急，独上青翰舟。","佳人青雀钗，手把青荷游。","慕君青云器，青发结绸缪。"]},{"t":"和陈传道秋日十咏 其一 秋雨","f":"五言绝句","c":["近砌掷鸣签，长檐悬素绠。","湿翅暝鸦归，高梧落寒井。"]},{"t":"和陈传道秋日十咏 其二 秋晴","f":"五言绝句","c":["归云去悠悠，长风来猎猎。","檐角两长楸，斜阳晒黄叶。"]},{"t":"和陈传道秋日十咏 其八 秋兴","f":"五言绝句","c":["拟从康乐公，双蹑登山屐。","晴夜宿天台，披云看初日。"]},{"t":"和陈传道秋日十咏 其三 秋夜","f":"五言绝句","c":["病骨倦空林，曳杖闲庭步。","暗烛与寒虫，迢迢思风露。"]},{"t":"和陈传道秋日十咏 其五 秋月","f":"五言绝句","c":["霜空出华月，樽酒聊相对。","别夜复婵娟，故人千里外。"]},{"t":"和钱适德循寓怀二首 其一","f":"五言律诗","c":["悠悠北山云，苒苒东门草。","纷吾起故居，与尔即远道。","巅崖博锱铢，得不偿所耗。","寄语邻墙翁，岁晚从吾好。"]},{"t":"和钱适德循寓怀二首 其二","f":"五言律诗","c":["鲁酒味自薄，楚歌声更悲。","曾无忘忧用，安事酒歌为。","西风激商序，流芳迫衰迟。","寄语邻墙客，兹非行乐时。"]},{"t":"和钱德循古意二首 其一","f":"五言绝句","c":["驾犁岂知耕，布谷不入田。","大农坐官府，百吏饱穷年。"]},{"t":"和题毗陵荐福寺红梅","f":"七言绝句","c":["一种梅生禅老家，屋檐古干恣敧斜。","诗人莫讶深红色，可胜寻常桃杏花。"]},{"t":"夜行邹县道中遇雨作","f":"五言古诗","c":["昨日秋遂分，村村敛禾黍。","半夜宿田人，相嘑深陂雨。","骎骎马上客，厌浥投何所。","暮发邹子城，朝期饭东鲁。","据鞍思假寐，颠坠惭不武。","俯畏道旁石，颓然如伏虎。","远惊荞麦华，白水漫洲渚。","安能叱吾驭，亲闱寄西楚。","念昔卧苏门，夙兴犹及午。","岂谓从一官，羁离遽如许。","归欤惜迟暮，幽愫将谁语。","赖尔草根虫，助我长吟苦。"]},{"t":"招寇元弼兼呈白云庄张隐居","f":"七言律诗","c":["长铗长铗归来乎，十口想厌淮南鱼。","游宦非图饱而已，浮生且问乐何如。","定无佳客清樽酒，赖有古人黄卷书。","我亦尘埃同病者，与君长愧白云居。"]},{"t":"金山化成阁望焦山作","f":"五言古诗","c":["朝登化成阁，写睇沧江东。","岿然痤鹤山，屏截横流中。","云烟生蔽亏，水石相磨砻。","飞构结岩腹，天龙严佛宫。","初无刳木智，不与尘界通。","旷莽天地间，胜事岂易穷。","将谋乘兴入，难此迎潮风。","可信浮桴约，仅有由也同。","我亦念行役，翻如征北鸿。","他日一渔艇，悠悠浮玉翁。"]},{"t":"金山夜集招米芾元章不至作","f":"五言古诗","c":["芳洲撷兰佩，清夜栖宝坊。","晚风驾飞涛，柱石摇长廊。","微月逗檐际，助我灯烛光。","黄童天下才，亹亹陈与章。","狂歌间险语，捧腹屡烘堂。","惜无杯中物，可以延楚狂。","兴阑半道去，浪学山阴王。","明发吾将还，沧波渺相望。","如何方外徒，漫仕烦官仓。","端尔凉秋节，白云来帝乡。"]},{"t":"金山游","f":"词","c":["轻舠放中?，岸远春风壮。","楫师俯仰呼，天水争簸荡。","吾方扣其舷，聊赓小海唱。","梢回即东麓，侧磴联屦杖。","危刹表层巅，疲筋蹑牵强。","斜廊缭复殿，鱼脊分背向。","放目四垠宽，秋毫入吾望。","侵云铁瓮垒，崛起去缘傍。","映日海门山，不蒂沧波上。","吾虽百石吏，平昔有微尚。","俄得金仙徒，剪萝开岫幌。","誓投桑榆年，浮玉翁自况。"]},{"t":"南楼歌送武昌慎太守还朝","f":"词","c":["君不见鄂渚山环少城半，高牙之冲仰飞观。","裴回华月天一隅，缥缈青山江两岸。","题榜南楼非昔时，今人可复识元规。","唯馀在得昔时月，与此江山长住持。","公堂坐啸无留事，清夜登临谁辨此。","流风逸响殆千年，初见东吴贵公子。","剸繁健手付方州，迎刃未始逢全牛。","潢池小儿归田畴，田无高下乃多收。","每寻不浅胡床兴，更有歌人行酒筹。","明日云帆望峣阙，镜湖老生愁欲绝。","一钱何敢浼刘公，送行聊以南楼月。","照见金闺待漏时，结佩正冠勤晓谒。","公乎莫负鲈鱼菰菜期，衣锦东还使持节。"]},{"t":"客有携寇莱公真挂于驿舍傍题云今作阎罗王慨然有作","f":"七言律诗","c":["凛凛英风万世孤，忽瞻容貌涕洟俱。","遗谋不愧生张说，异事犹烦鬼董狐。","黑白已分归节义，丹青长慑在奸谀。","不烦摇扇苍蝇去，一片寒冰挂座隅。"]},{"t":"故邺","f":"五言古诗","c":["魏武昔恢图，北平谭尚孽。","卜邺筑新都，非徒三狡穴。","将行迁鼎志，遽有分香诀。","落日穗帷空，奠终歌舞阕。","旋闻瀍洛上，载起苍龙阙。","四叶不归东，苔花驰道绝。","食槽谶终验，挂饭期先决。","扰攘百年间，覆车寻此辙。","山川气象变，朝市繁华歇。","白露复青芜，茫茫换时节。","阴风吹葛屦，燐火走兵血。","木叶下西陵，寒虫助骚屑。","当时陪葬骨，马鬣犹环列。","隧碣仆纵横，镌文久残缺。","帛砧与柱础，螭首随分裂。","指此一抔间，贤愚两何别。","悠悠凤漳水，寂寂雀台月。","千古配英魂，未随埃烬灭。","田皋访遗老，谓有兴亡说。","但听黍离篇，叱牛耕不辍。"]},{"t":"春行","f":"五言律诗","c":["风俗喜嘉辰，行乐东城春。","人歌芍药章，马度杨柳津。","田亩久枯渴，麦芒栖暗尘。","焦心戴白叟，日望西郊云。"]},{"t":"春怀","f":"七言律诗","c":["东风吹雪阴复晴，西日冉冉林间明。","著水苔衣渐涵绿，向阳竹鞭初引萌。","官粮得饱酒不足，春物有意人无情。","驰书相谢五陵侠，汗板尘靴今半生。"]},{"t":"秋怀二首 其二","f":"五言律诗","c":["萧萧庭木落，格格鸡声恶。","荒檐日影斜，饥猫捕黄雀。","窗间养痾客，起念丘园乐。","欲赋归去来，西风老藜藿。"]},{"t":"舣舟姑熟溪","f":"七言律诗","c":["潮来姑熟半篙深，帆落溪口樯如林。","谢氏青山失故井，桓郎白苧无遗音。","良游蹑屐负登览，衰病伏枕方呻吟。","个中二顷了吾事，怊怅十年怀此心。"]},{"t":"舣舟秦淮雨中寄侍其服之","f":"五言古诗","c":["篷卑每碍帻，仓狭才容席。","悽酸拥膝吟，奈此风雨夕。","欣闻钟漏旦，怀彼南城客。","欲往从之游，塞涂没吾屐。","方君慕栖遁，顾己淹行役。","后夜岁云除，畸辰良足惜。","何当斥氛闭，新旸被东陌。","壶觞殿两骖，聊取一日适。"]},{"t":"舣舟秦淮雪中访侍其瑀","f":"七言律诗","c":["北风破雨初成雪，斋舫篷窗吹纸裂。","篮舁触冷访圆庐，得把一杯聊耳热。","人生自适待何时，矧君与我皆衰迟。","会待晴天暖风日，杖藜同赴北山期。"]},{"t":"追和亡友杜仲观古黄生曲三首 其一","f":"五言绝句","c":["朝为去山云，暮为还山雨。","谁谓物无情，欢期不知许。"]},{"t":"追和亡友杜仲观古黄生曲三首 其二","f":"五言绝句","c":["欢归夜何其，月照临门别。","后夜待欢来，开门但明月。"]},{"t":"追和亡友杜仲观古黄生曲三首 其三","f":"五言绝句","c":["要知两侬心，等是它山石。","此诚不可转，彼情无自入。"]},{"t":"送王安节赴武康尉","f":"词","c":["江左风华推第一，王氏堂堂文献出。","乌衣诸郎能少屈，尚执中司三尺律。","君方色养白头亲，吴兴水陆饶甘新。","卞山之下苕溪滨，一洗长安肥马尘。","君不见昔人负米长勤捧檄喜，敢论州县徒劳耳。"]},{"t":"送何安中之官新安录事","f":"七言律诗","c":["带郭荒山百匝牢，跻攀几见病猿猱。","官粮可数才鸡肋，吏事悬知倍马曹。","芸阁有书行且召，萱堂须养未容高。","庆湖老子何堪别，隐几僧坊更寂寥。"]},{"t":"送李主簿夷行之官河阴四首 其四","f":"五言律诗","c":["少小縻一官，身世两相补。","为饱西复东，志愿劣儿乳。","不无同心友，颇压折腰膂。","寄语北山云，异时吾与汝。"]},{"t":"送李主簿夷行之官河阴四首 其三","f":"五言律诗","c":["君才本高绝，流俗固难谐。","桂生樗栎林，宁免相突排。","勾稽谅多暇，帘箔蔽公斋。","圣贤在黄卷，差可遣人怀。"]},{"t":"送李主簿夷行之官河阴四首 其二","f":"五言律诗","c":["古来英特士，往往沈下僚。","念君鸾鹄姿，俛首栖蓬蒿。","霜气敛陂泽，伊流才半篙。","舟行何以尉，酌酒诵离骚。"]},{"t":"送陈传道之官下邳","f":"五言古诗","c":["昔也官彭城，日与君子亲。","俱游大梁下，不见辄兼旬。","衣食牵迫人，汗走长街尘。","相逢立马语，愁面如含辛。","朝来忽叩门，颇惊黄绶新。","告我即东下，得官淮泗滨。","方语病中暍，药物苦殚贫。","故人复舍去，此怀难重陈。","想见经旧庐，节候属萧辰。","朝寻张翁墅，暮投寇叔邻。","二子亦吾好，尺书坐因循。","交情定相访，为话正迷津。"]},{"t":"送周元通昆仲官蜀","f":"七言律诗","c":["周郎弟兄皆可人，外朗内润连城珍。","樽酒逢迎记梁宋，联骖行迈度咸秦。","宝鸡道上冰雪晚，金雁江边梅柳春。","公暇乐游须念我，青衫白发倦京尘。"]},{"t":"送周寿元翁西上","f":"五言古诗","c":["露草蔓前庭，微虫思明月。","宵分耿不寐，怀我友生别。","舟师望箕宿，缀幔须明发。","蠲首托归风，安知川路阔。","夫君青云士，行奉紫宸谒。","一鹗抉尘笼，骞轩应霜节。","仰追鸾鹤驾，肯顾狐兔穴。","越客寓荒城，卑栖慕鸠拙。","衰迟积尪弊，未死人事缺。","懒制一缄书，寄声彼朝列。","方今百废举，衮职补何阙。","每自幸馀龄，江湖傲华发。","躬耕固难强，五斗代薇蕨。","摩腹溯南薰，苍生解烦暍。"]},{"t":"送武庠归隐终南","f":"词","c":["君不见南朝豪俊有郗生，自厌出身时网婴。","乐闻栖遁去人者，倾金累百赠其行。","关西武郎将家种，心实慕儒官冗从。","春走巴东岁暮还，逢迎偶在江南梦。","过门把酒豁清襟，行将归隐南山阴。","终焉之计咄嗟办，愿赋一诗轻百金。","吾闻自古咸秦称陆海，六印可求田莫买。","别墅三千亩上腴，将军部曲犹多在。","未应亲手把钩锄，岁事经营付家宰。","一官换得今是翁，昔何所缚今谁解。","携琴领鹤白云乡，身世相辽自两忘。","北窗仰枕安足道，未知何者为羲皇。","岂不胜俛首尘埃百僚底，南北推迁随尺纸。","摩肩接武半台舆，谁谓淮阴非哙比。","君家鼎甲盛先唐，两都朱邸森相望。","天道恶盈几赤族，当时赖有安平王。","庆牒蝉联今几代，云孙庠继游方外。","他时野史逸民篇，铸也磨铅跂而待。"]},{"t":"送武桓之安阳","f":"五言律诗","c":["黄金络征辔，之子待明发。","樽酒少迟留，禅林见凉月。","歌鬟结蛾黛，怨此佳期阔。","去去柳堤风，青蝉催白发。"]},{"t":"送表侄赵子亿之官沧州兼简通守李延宁","f":"五言古诗","c":["吾昔游浮阳，童心初办狂。","淩高瞰海日，径欲穷扶桑。","岁纪忽再周，此图竟莫偿。","今适送子往，临风但彷徉。","之子公族秀，祖基维懿王。","成吾家宅相，裂封复吾乡。","汝翁同谷守，视吾犹雁行。","后生古所畏，之子未易量。","筦库方试吏，事役须更尝。","譬彼汗血驹，齿齐即腾骧。","是宜勤夙夜，动虞三尺妨。","勿惮川陆遥，千里如邻墙。","勿计弦晦馀，俛仰度三霜。","边朔昔云苦，今歌海隅康。","正赖别驾贤，不减晋王祥。","依投得吏师，行见售所长。","为吾语故人，曩契想未忘。","愿致双鱼封，继以一鹗章。"]},{"t":"送咸宁陈令完夫移官吴郡","f":"五言古诗","c":["蒿莱东郭居，长者车成辙。","礼经尚往来，岂为我辈设。","临分怀出饯，津远舟速发。","十月雁啼寒，沧波洒微雪。","送君一樽酒，孤饮聊耳热。","会取屈平书，商声歌九阕。","开正到吴郡，旸暖张灯节。","两地见梅花，相思不同折。","官闲羁绁□，陈迹得搜阅。","虎去丘隧空，燕惊宫火灭。","廊倾罢鸣屧，兰斸香径绝。","逮□故时人，唯馀剑池月。","名城见图绘，丹墨殊灭裂。","细与赋新诗，长封寄天末。","老狐首丘志，客子敢忘越。","未死定归东，柴荆昼常闭。","右军领妙语，年大不堪别。","况复鱼鸟情，飞沈方此诀。"]},{"t":"送海陵周太守邠受代还朝","f":"词","c":["汤汤水东流，奈何载此西行舟。","紞如五鼓鸣城头，使君去矣不可留。","前日使君来，天子惠此州。","传道管城政，先声走群偷。","不关外户息吠犬，悉把钩锄谁带牛。","雨旸不违祷，舄卤数倍收。","吏却一钱贿，狱无五木囚。","黄堂坐啸有馀暇，八咏新诗追隐侯。","斯民幸使君，毕世为吾休。","俄及瓜时代，本朝官重内。","旧通金门籍，行奉玉宸对。","问君何以治海陵，但陈圣主之德臣何能，狂生有意水衡丞。"]},{"t":"送寇元弼王文举","f":"五言古诗","c":["无端嵇氏叟，早结曹家偶。","不遂龙蛇藏，翻从牛马走。","东西祇强颜，清镜照人顽。","敧枕知归路，开屏认旧山。","甘心折腰膂，为饱来西楚。","始验釜生鱼，还悲厕中鼠。","两君冰玉人，倾盖许相亲。","何意尘埃地，欻游云汉津。","佳时第行乐，不与华年约。","大白酒交酬，长笺诗间作。","俄报戍期秋，扁舟去莫留。","台乡淮水北，和氏玉坑头。","飘飖同李郭，到岸逢摇落。","俱是长年人，得忘弥日恶。","劳生不自知，会合复何时。","笼鸟槛猿思，烹鸡炊黍期。","此期谅难必，幸勿忘今日。","固有梦依依，可无书一一。","徐国壮山河，黄楼入望多。","后时三五夕，奈尔月明何。"]},{"t":"送章邦杰移家馀杭包家山","f":"词","c":["九江贤令尹，千载两相望。","昔也陶彭泽，今之章瑞昌。","拂衣置五斗，高兴挹羲皇。","避俗陶无悔，达生吾与章。","渊明三径荒松菊，我携一瓢寓僧屋。","渊明乞食踵人门，我卖神丸办蔬粥。","渊明为酒接休元，我每移书谢州牧。","渊明纸笔课儿曹，我子长歌紫芝曲。","萧闲门户十三年，尚畏尘缘生处熟。","行将卜隐包家山，誓与苍生鍊大还。","愿君门外诛榛菅，来者勿拒容跻攀。","镜湖遗老老且孱，犹堪护鼎诃神奸。","功成拔宅自仙去，唯馀井臼留人间。"]},{"t":"送鄂州刑狱掾王懋元功罢官还海陵兼简金陵和上人","f":"词","c":["暖云芳草横塘路，送客何之官鄂渚。","江皋暑淫气如蒸，别来何之还海陵。","海陵鄂渚非吾土，每后君来先我去。","人无根蒂本悠悠，况指沧波是舟路。","君方少健我衰迟，局蹙辕间不自持。","因行寄声雁门远，岁暮敢忘林下期。","好去将无同语掾，行见春风花满县。","隐显它年不我遗，为续白莲社中十八传。"]},{"t":"送僧云还吴兴","f":"七言律诗","c":["吴兴道人美风度，月下沧浪翘白鹭。","昼公诗律尚能传，间有赤乌黄耳句。","海角相逢一笑新，怀归不待白蘋春。","寄声故国群儿辈，潦倒尘埃贺季真。"]},{"t":"重送","f":"五言律诗","c":["夹岸雪初消，青青见麦苗。","传声汶阳客，已解木兰桡。","春水生张泽，春风动乐郊。","良游知不负，回首念无聊。"]},{"t":"重寄潘豳老","f":"七言律诗","c":["轻舠蓦水帆如弓，一伸臂顷来江东。","聊持美酒致吾子，方事綵衣娱汝翁。","悬榻可容它客坐，闭关正与无月同。","夙兴行乐竟何有，醒醉阴晴皆梦中。"]},{"t":"闻莺有怀故园","f":"七言律诗","c":["海陵春后雨冥冥，耳厌蛙嗥鹳齿鸣。","何意东亭好风日，流莺忽作故园声。","故园千里长牵梦，老病三年不废情。","想见杨花收卷尽，绿苔池院落朱樱。"]},{"t":"除夜叹","f":"五言古诗","c":["壮发忽种种，华年今复穷。","客怀少安适，况乃京尘中。","病肺厌斟酌，疲筋谢过从。","闲坊税老屋，车马无来踪。","日俸才百钱，盐齑犹不供。","夜榻覆龙具，晨炊熏马通。","出门欲贷乞，羞汗难为容。","安得一扁舟，浮家乘兴东。","江山此深隐，终老为田翁。","春秧二顷苗，秋穫期百钟。","稚子课樵汲，壮妻兼织舂。","行歌沧浪清，卧快柴桑风。","神明养内观，忧患无旁攻。","有客闻此言，诮余何不衷。","兹行果勇决，谁揽冥冥鸿。","安知禄籍间，去就如樊笼。","微尚良自信，所悲君不同。"]},{"t":"食芡实作","f":"五言古诗","c":["钱侯官舍旁，走水来方塘。","暑雨过初伏，斜阳生晚凉。","风翻芡盘卷，万觜争低昂。","犹疑秦鸡暴，擅此六国场。","下榻延密客，开樽荐新尝。","金刀剥老蚌，玉沙磨夜光。","殷勤烦饤饾，未咀悲生肠。","引领鄘卫西，百泉乃吾乡。","水产富此物，数钱论斗量。","朝餐取餍饱，无复炊黄粱。","贪嗜比羊枣，况乎惟味良。","十年去国仕，遇得才微芒。","季鹰思莼羹，拂衣谢齐王。","我亦散浪者，未许斯人狂。","长歌定行矣，千载会相望。"]},{"t":"食鲥鱼","f":"七言律诗","c":["雨长沙田三尺芦，截江逻钓待嘉鱼。","上钩一尾誇先得，下箸千钱忍弃馀。","倦客罢弹腰下铗，故人忘寄腹中书。","知机何独张生翰，不俟秋风已起予。"]},{"t":"夏夜怀寄传道","f":"五言古诗","c":["疲筋任藜杖，行药下僧坊。","月出河汉白，雨馀草木凉。","有怀社中子，引首东南望。","高韵少谐结，何心事征商。","泗滨六七月，万柳鸣蜩螗。","大艑轲峨来，迎风坐胡床。","投钱授赤券，岂所试君长。","申退尚多暇，不无金玉章。","而余方执热，思得濯沧浪。","云笺傥写寄，珍重未相忘。"]},{"t":"夏夜雨晴遣怀","f":"五言古诗","c":["积潦被广陌，谁过牛侩翁。","闭关养尪瘵，药石收良工。","高斋俯嘉樾，疏箔延清风。","左右列图史，披张俄一通。","从嗤獭祭鱼，聊学蠹书虫。","坐挹古人语，孰云吾道穷。","浮生梦境间，不蒂之惊蓬。","生死犹物化，今昔贤愚同。","分阴贱垂棘，白日莫再中。","薄暮纷滓澄，寥寥还太空。","为问此何夕，凉蟾生自东。","荒哉西园士，联盖追轻鸿。","行乐以至斯，不知息微躬。","侧聆天鸡鸣，凡耳初破聋。","吾从汗漫游，溯景鞭垂虹。","濯缨咸池渊，晞发若木丛。","亲串不我忘，惠音赤鲩公。","长哦赋来归，阅尔世上雄。"]},{"t":"席上呈钱德循","f":"七言律诗","c":["枣华纂纂桑叶肥，老蚕起眠雏雀飞。","南邻买酒劝行乐，越客废书歌式微。","式微式微胡不归，明日会知今日非。","旧溪手种水杨柳，长与秋风扫钓矶。"]},{"t":"晓度黄叶岭东谷怀寄金陵王居士闲叟","f":"五言古诗","c":["阴谷不寓暑，风松朝露零。","乳溪逗绿筱，琴筑声泠泠。","老石渍金碧，窅然沈列星。","酌此石上泉，饵彼松下苓。","倏欻振飞步，岂徒制颓龄。","何须历五岳，即蹈神人庭。","顾余方有役，俗驾不敢停。","寄音采真子，来卜白云扃。"]},{"t":"晓登柏子冈回望金陵怀寄钟山泉禅师","f":"五言古诗","c":["晨征念王事，驽驾烦屡叱。","既陟崔嵬高，稍辞丛薄密。","乌牛沾宿露，白鸟明初日。","清川舴艋迟，绿岸浮图出。","缅怀秣陵游，曾缀秦淮繂。","曳舄白下门，供香金粟室。","得闻四句偈，如奉三尺律。","损益非所知，婚嫁行且毕。","庶几追老庞，薄暮徼万一。","誓将迁枳根，待变江南橘。"]},{"t":"海陵喜雨","f":"七言律诗","c":["闰年四月之相交，旱天云物何萧骚。","清风捲地换尘世，白雨入林翻海涛。","殊胜农儿踏车健，少宽病夫挥扇劳。","须晴径买一渔艇，想见横塘深半篙。"]},{"t":"烛蛾","f":"五言律诗","c":["鬼蛾来翩翩，慕此堂上烛。","附炎竟何功，自取焚如酷。","感彼万动微，保生在无欲。","不见青林蝉，饮风聊自足。"]},{"t":"留别田昼","f":"七言古诗","c":["君家陋巷一尺泥，吾车有轮马有蹄。","犯寒踏雨重相过，明日扁舟吾遂西。","回首邯郸迹如扫，离索十年成潦倒。","兔葵燕麦春日妍，蝉腹龟肠气方饱。","云逵窅窅谢攀跻，长铗与人还故栖。","异时结驷来南亩，耕者老夫锄者妻。"]},{"t":"留别龟山白禅老兼简杨居士介","f":"五言古诗","c":["汴尾望龟山，人烟了可数。","长淮断日风，浩若千里阻。","舟无百石载，两腋忧双橹。","鹢首荡颓波，中流几翔舞。","维梢迫曛暮，坎坎禅林鼓。","曳锡辱来过，依然识眉宇。","青荧灯火畔，再得亲软语。","多惭晚闻道，忠义夙自许。","刚肠愤激际，赤手搏豺虎。","过壮缠百痾，馀生托儿乳。","羸躯假缓死，岂复胜冠组。","会约子云孙，西岩两庵主。"]},{"t":"留别道士许自然","f":"七言古诗","c":["东晋高贤许远游，裔孙今不坠风流。","还有临川王太傅，每思与语即登楼。","浮名何啻如云薄，钟鼓爰居非所乐。","漱石枕流知善谑，友月朋风差不恶。","吾亦尘閒无所求，终期探药栖罗浮。","异日归来辽海鹤，不见人民见城郭。"]},{"t":"留别僧讷","f":"七言古诗","c":["冗从西班谁比数，牛侩马医犹尔汝。","诗解穷人未必工，苦调酸声效梁父。","荥阳道人方外交，谓我有言追屈骚。","骊珠不惜弹黄雀，狗尾何堪联晋貂。","秦淮潮上扁舟发，后日相思一书札。","千里同风了了然，人閒无处无明月。"]},{"t":"留侯庙下作","f":"五言古诗","c":["文成念韩痛，破产伺强秦。","千金募健士，椎断属车尘。","东去变名姓，浮游淮泗滨。","忍耻奉遗履，得书何老人。","十年风云会，赤帝资经纶。","鸿门祸端结，一言即解纷。","英彭既合纵，楚项提孤军。","伟哉借箸谈，竖儒无复陈。","分疆饵两将，来若从龙云。","释怨俾侯印，谋销蛇豕群。","定都天府国，推功归奉春。","四老落吾术，拂巾辞隐沦。","东朝羽翼就，楚调徒悲辛。","出处能事毕，致君终乞身。","岂眷万户封，仅与萧酂均。","淮阴败晚节，顾亦非吾伦。","愿访赤松子，逍遥云汉津。","强饭示终殁，爽灵方上宾。","严祠镇川湄，馀泽及斯民。","客子老将至，低回冗从臣。","惭无应时策，肝膈空轮囷。","可教固无类，慨然辄求伸。","未应终万古，黄石独能神。"]},{"t":"病暑","f":"五言古诗","c":["旱夏景延永，烈日天中央。","欻欻燎原野，中人如探汤。","病肺苦焦渴，吐舌生喉疮。","蔗浆与茗饮，未易苏膏肓。","稍惊气象变，云物来冥茫。","仰枕视檐际，浩浩浮沧江。","忽得灌顶偈，洒然心地凉。","雷公未鼓怒，风伯何猖狂。","扫荡太宇空，万影才斜阳。","俯辞楚台上，拱立齐鼎旁。","一介命蝼蚁，敢干私雨旸。","田夫信无罪，触热正驱蝗。"]},{"t":"秦淮官柳二首 其一","f":"七言律诗","c":["秦淮两潮西复东，淮边杨柳酣薰风。","送春白花去漠漠，避日黄鸟啼匆匆。","陶彭泽多倦官叹，桓琅邪今衰病翁。","此身会复有健日，拟就绿阴横钓篷。"]},{"t":"罢官有期怀寄历阳朋好","f":"五言古诗","c":["迅雨荡阑暑，层飙披滞云。","澄川缭楚甸，新阳丽秋旻。","物候岂不嘉，中怀怆离群。","亲朋满城邑，系滞此江濆。","及瓜信匪遥，遂作河梁分。","何人具供帐，樽酒展慇勤。","一聆雪儿歌，载悽游子魂。","津鼓惊朝梦，□烟生夕曛。","所悲紫兰缨，复染京洛尘。","春风有归雁，报我相思文。"]},{"t":"读李益诗","f":"五言古诗","c":["君虞兴圣孙，诗律早专美。","乐府度新声，宫酺奉天子。","鲜风猎兰苕，华月濯桃李。","独有连眉郎，才称劣相比。","颇闻竹窗句，流落绮纨耳。","吏曹久失调，幕府感恩起。","从军五十篇，王粲惭率尔。","胡沙动霜草，开卷得千里。","骞翔大蓬拜，转顾触排毁。","晚升八座崇，谢事知所止。","高文茂支庶，埋灭长已矣。","斯人今不亡，正赖数番纸。","咄嗟齿踰壮，日就无闻耻。","勉哉课谣吟，请自田居始。"]},{"t":"调北邻刘生","f":"七言古诗","c":["荒园老墙百堵破，北邻刘子南邻贺。","今朝两望不相过，端怯衡阳芒屩涴。","吾庖无鱼未必饿，晏饭糠覈烦脾磨。","吾床何容凡物坐，书为睡媒即床卧。","彼子刘子何所作，方学商声哦楚些，细君戛琴与之和。","相忘之乐在江湖，最灵者人情不无。","此日可惜难再图，秋风西来莫挽吾。","后日相思几千里，书不尽言徒耗纸。"]},{"t":"部兵之狄丘道中怀寄彭城社友","f":"五言古诗","c":["驾马出北门，徒御何迟迟。","日气方汹涌，霜阴亦纷披。","役夫前驱行，少妇痛不随。","分携仰天哭，声尽有馀悲。","虽非远行迈，要之为别离。","顾我岂无家，从公难遂私。","且怀二三友，缺此文酒期。","临分各有赠，婉思见乎词。","吟讽一回首，烟林失城池。","相思肯相过，斗黍为君炊。"]},{"t":"宿宝泉山慧日寺","f":"五言古诗","c":["日入不遑息，驱车更之东。","回蹊出蒙密，解袂迎长风。","风从何许来，历历江南钟。","顿辔阿兰若，虚庭月正中。","流萤逗深竹，白鸟巢青松。","华灯耿翠箔，瑶花擢春丛。","绝境美清夜，恍非尘界逢。","惜无一樽酒，幸与之子同。","明发即南北，浮生两飞蓬。"]},{"t":"宿法惠寺","f":"五言古诗","c":["驱马越飞涧，扬旌下回冈。","欻见层浮图，高风振琅珰。","重门壮且深，老柏森然行。","佛子出延客，投鞭步长廊。","中庭汲新泉，一饮生清凉。","孤坐兴登览，危梯趋上方。","萧萧荒竹林，檐外如环墙。","樵牧断行径，龙蛇知所藏。","山禽喜暄旸，啸侣何琅琅。","子规特殷勤，使人怀故乡。","引领落西北，暮色来苍茫。","一官早见縻，微尚久未偿。","明发复东去，斯游良不忘。"]},{"t":"寄汉阳赵尉沔","f":"词","c":["庆湖遗老坐诗穷，强仕之年百病攻。","谁谓南昌禄隐翁，伏枕呻吟四壁空。","相思限此江西东，寄声每托江头风。","斯言近俳聊一笑，江水方清饥可疗。","人生奇偶类探筹，造物岂容人数料。","君初试吏或当然，我太半生真不调。","昔不愿起家百日登三司，今不愿还家六印金累累。","但愿官粮办亲养，归来尚馀三径资。","邻墙晏起访安否，尔酌我歌尧舜时。","咄嗟此愿良难必，吞声食檗甘如蜜。"]},{"t":"寄兴化黄主簿杞","f":"七言律诗","c":["何准第五不足称，黄童无双非自名。","卑栖鸾凤安初仕，葆练龙虎希长生。","明月高吟紫芝曲，红尘先老白云兄。","莫辞一力走三舍，遽未能来频寄声。"]},{"t":"寄有捷上人","f":"七言绝句","c":["捷也当年避畏途，寄身一叶泛隋渠。","定须惭愧操舟子，千里风波汝渡吾。"]},{"t":"寄杜仲观","f":"五言古诗","c":["中春雨收霁，与子登丛台。","形胜宛然在，太行西北来。","无情百尺土，千载未摧颓。","四顾发悲啸，凄风振颐颏。","淩高气象变，似不容徘徊。","下出破禅刹，断碑生紫苔。","严公赋怀古，复使后人哀。","西寻王氏园，一径趋城隈。","老竹未萌笋，繁花如雪开。","惠然丘少年，逸躅欣攀陪。","小榭罗宴豆，开帘按俳诙。","招呼缈缥人，晚镜催妆梅。","水调唱金缕，云罍浮玉醅。","倾觞敢惜醉，忘著接䍦回。","明日遂分首，旧游安在哉。","我为东徐官，客鬓栖尘埃。","君调南康吏，江山役清才。","西风吹去雁，尺纸为君裁。","我已困摧辱，壮心如湿灰。","行将隐名姓，采药孙登嵬。","异日傥相过，衡门剪蒿莱。"]},{"t":"寄杜邯郸","f":"五言古诗","c":["穷巷厌多雨，颓垣藜藿生。","蜩螗饱风露，晏景一何清。","坐指岁芳歇，羁人心骨惊。","所怀不可见，东州闻政声。","三年但弦歌，百里称神明。","风月动高兴，诗章时一鸣。","天葩落健笔，直与春工争。","浑河失故渠，怒水方纵横。","难凭束苇济，跬步万里程。","梦想不知远，笑谈何可并。","赖有西飞翰，尺纸缄驰情。"]},{"t":"寄武昌方令临李尉援兼简黄冈二潘昆仲","f":"七言律诗","c":["好在桐江三拜翁，谪仙之裔好应同。","如闻花县两郎子，兴发能来一水东。","共醉南楼故时月，断无庾令浼人风。","季真老病不堪酒，泽畔微吟怀四侬。"]},{"t":"寄金陵仓官赵令毣通直","f":"五言律诗","c":["岁律倏云莫，王孙兴可堪。","羡云归日下，随雁滞江南。","卑湿求长健，登临赖半酣。","西州眼中近，早晚寄华缄。"]},{"t":"寄墨代书赠杨时","f":"七言古诗","c":["徂来雪压苍松颠，沦膏根柢蟠蜿蜒。","樵斤剪析石火热，曲突百步凝梢烟。","蒲萄秋颗累累悬，海胶九炼堪续弦。","力捣万杵臼欲穿，剂成圭璧随方圆。","点漆比色石比坚，坐令李韦羞居前。","陈台潘谷老且贤，授唯识者不计钱。","是翁解化如蜕蝉，后可继此无闻焉。","付君一圭款识全，保护谨密何千年。","君家清风宜世传，不特谈玄须草玄。"]},{"t":"寄题浔阳周氏濂溪草堂","f":"五言古诗","c":["濂溪之水清，未足濯公缨。","平生抱苦节，成就此溪名。","长啸置符传，孤云归思轻。","溪头四壁居，溪下百亩耕。","量汲奉晨盥，课樵共夕烹。","希逢杖屦游，但听弦歌声。","为客剪三径，传家通一经。","双珠交照乘，合璧倍连城。","被褐有馀乐，问缣无隐情。","桂林两枝秀，借尔俗眼荣。","昔仰名父子，今推难弟兄。","不应文范裔，遽谓公惭卿。","如袭带砺封，毋为权利倾。","地实寝丘比，有力安得并。","勒诗高岸石，敢告后代生。"]},{"t":"寄题栗亭县名嘉亭","f":"五言古诗","c":["少陵昔避地，幽栖凤皇川。","始愿获其所，赋诗此终焉。","眷彼美林麓，荫膏腴上田。","阳坡饶垂珠，阴谷繁玉延。","长镵勤采斸，服食攀飞仙。","兵祲夺和气，力耕无善年。","林坰开冰雪，旬浃断庖烟。","呜呼歌七章，暮节西南迁。","环堵久芜没，斯亭名尚传。","茂宰怆怀古，增崇殊过前。","雕甍揭长帘，下容十客筵。","嫩岚隔春丛，清竹鸣夏蝉。","风月有高兴，写之武城弦。","狂客属尪废，驽筋难强鞭。","何暇远登览，但哦鲸海篇。","尚苦八口累，依稀同曩贤。","馀龄寄幻境，未断东西缘。","江淮米价平，一舸去悠然。","幸此岁丰乐，浮游吾所便。","异时访陈躅，复使后人怜。"]},{"t":"晚出江城闻角","f":"词","c":["古壕沮洳荷叶枯，矍铄秃鹙行且渔。","山衔日脚水关掩，孤楼引角吹单于。","胡马嘶风兴非浅，壮图旧迹随尘卷。","秋尽湖边雁不来，流落方悲去人远。","十月之交五夜长，河横斗直天苍凉。","苏门故里斗杓下，岂无伯仲勤相望。","君不见剡蓬为矢弧弦桑，男儿落地志四方。","履屐无根著家巷，道梁适楚犹吾乡。","鸲鹆不踰济，橘渡淮为枳。","吾心况物未应然，随牒官身聊尔耳。"]},{"t":"晚泊三山怀古兼寄历阳朋游","f":"七言律诗","c":["三山春水拍江流，六代馀风扫地收。","破国龙骧复安在，赋诗宣城难与酬。","伤心远宦北宗老，满眼旧游南豫州。","寄声好住数君子，一别相忘风马牛。"]},{"t":"望夫石","f":"五言古诗","c":["亭亭思妇石，下阅几人代。","荡子长不归，山椒久相待。","微云荫发彩，初日煇蛾黛。","秋雨叠苔衣，春风舞萝带。","宛然姑射子，矫首尘冥外。","陈迹遂亡穷，嘉期从莫再。","脱如鲁秋氏，妄结桑中爱。","玉质委渊沙，悠悠复安在。"]},{"t":"渔歌","f":"词","c":["严公桐江上，吕父清渭滨。","出处两能事，寥寥乎若人。","拥蓑芘笠吴侬子，身偶一竿生寄水。","侯庖富馔美鲥鲈，寸鬣分鳞辱刀机。","吾将一钩悬十犍，笑倚扶桑不计年。","鲲鲸怀饵脱相得，坐使东南饫食鲜。"]},{"t":"烹鸡叹","f":"五言古诗","c":["膳夫缚三鸡，二雌先就烹。","一雄置机上，不废知时鸣。","有客见之叹，人情犹物情。","宁昌言即死，何噤口偷生。","愚闻此客言，退思因窃评。","鸡实鼎俎资，杀身非罪声。","人忘枢机诫，鼓舌为祸萌。","宜念千金躯，与鸡何重轻。"]},{"t":"黄山席上别当涂僚友 其一","f":"五言律诗","c":["自昔有宇宙，便应有此山。","如我与君者，几辈来跻攀。","声迹两磨灭，寥寥千古间。","短生一浮沤，妄比金石顽。"]},{"t":"黄楼歌","f":"词","c":["君不见熙宁丁巳秋，灵平未塞河横流。","澶漫势欲浮东州，斯人坐有为鱼忧。","当时贤守维苏侯，厌术不取三犀牛。","跨城岧峣起黄楼，五行相推土胜水，鼍作鼋惊走鞭箠。","三丈浑流变清泚，南来船车鹢衔尾。","使君登览兴如何，舞剑吟笺宾从多。","水平照影见雁下，山空答响闻渔歌。","楼下汀洲长芳草，一麾南出彭门道。","昨日春游咏白蘋，后夜秋风悲鵩鸟。","黄冈汝海心悠哉，青衫白发多尘埃。","采菱伎女今何在，骑竹儿童望不来。","望不来，碧云明月长裴徊。"]},{"t":"黄鹤楼","f":"五言古诗","c":["登真者谁子，昔有费公祎。","白日玉书下，青天驾鹤飞。","此地少留憩，神标怅依依。","振裾谢尘浊，与尔方远违。","层楼宠陈迹，江山长四围。","登临美商素，雨气薄西晖。","水落州觜嫩，风豪帆背肥。","飘然起遐想，琳馆閟岩扉。","明月识悠阔，白云疑是非。","金桃未遽熟，薤露虞先晞。","高树两华表，长招羽驾归。","灵瓢五色剂，定与遗民挥。","自顾乏仙质，延生犹可希。","刀圭傥不吝，如饱首阳饥。"]},{"t":"喜雨","f":"五言古诗","c":["终春久旱暵，涉夏俄溽暑。","垢汗浼衣襟，梅津蒸柱础。","黄霾闭赤景，测候错辰午。","沙燕逐风鸢，翻飞溯来雨。","纷纷白羽箭，齐发万牛弩。","落瓦复鸣阶，浮沤如沸煮。","崇朝已沛浃，枯渴顿清瘉。","田父喜过从，迎门好相语。","蚕桑薄可具，豚酒与箫鼓。","择吉谢丛祠，巫娘罢狂舞。","晨炊饱丁壮，庇笠耕舄卤。","少缓麦租期，庶将秋稼补。","输入太仓中，蕃肥任黄鼠。"]},{"t":"彭城三咏 其一 戏马台歌","f":"词","c":["秦蛇已中断，刘项方龙战。","叱咤沮风云，睢盱走霆电。","鸿沟一画天地开，楚王洗剑东归来。","新都形胜控淮泗，笼山络谷营高台。","重瞳登览何为者，不知招贤知戏马。","上如激矢下投丸，兰筋霜腕便回盘。","半夜悲歌骓不逝，明日阴陵行路难。","騋牝三千归汉闲，粟豆尤闻蠹县官。","君不见华山之阳古坰牧，春风吹草年年绿。"]},{"t":"彭城三咏 其二 斩蛇泽歌","f":"词","c":["君不闻泗滨亭长送徒如咸阳，徒夫怀归多道亡。","泽中置酒饮相诀，吾亦从此奔芒砀。","阴风萧萧导者惧，前有脩蛇怒横路。","酒酣拔剑肯留行，划断蜿蜒不回顾。","河明月出人踵来，彼媪何冤号且哀。","谓遭赤帝屠吾子，语竟莫知安在哉。","真人闻此自心许，茫茫四海吾其主。","虎变龙飞十二年，馘项枭英盖狐鼠。","半夜雄铓飞上天，几见长陵一抔土。"]},{"t":"彭城三咏 其三 歌风台词","f":"词","c":["汉祖高风百尺台，千年客土生蒿莱。","何穷人事水东去，如故地形山四来。","江淮犹沸鲸鲵血，八十一车枉归辙。","白叟逢迎皆故人，牢酒欢呼惜将别。","崤渑迢遥非我乡，死生此地何能忘。","酒阑鸣筑动云物，青衿儿曹随抑扬。","尔时可无股肱良，端思猛士守四方。","君不闻淮阴就缚何慨慷，解道鸟尽良弓藏。"]},{"t":"暑夜","f":"五言律诗","c":["渴蝉鸣中夜，木叶凝无风。","襟苧不加带，犹如被蒙茸。","三庚信可畏，一扇曾何功。","安得解民愠，苍梧理古桐。"]},{"t":"游云龙张氏山居","f":"五言古诗","c":["昔闻张逸民，卜筑云龙山。","东望结遐想，喜得彭城官。","一语定襟契，宛如平生欢。","招携属休沐，投此萝薜间。","女仆候门巷，青袿双翠鬟。","苏斋轩户明，饼火焚椒兰。","宝墨鬼神护，清诗冰玉寒。","森然拱檐霤，架石排琅玕。","东趋放鹤亭，磴道披茅菅。","指顾百村落，炊烟林莽间。","日脚洒平陆，两山如断环。","凄风振晚叶，坐怯衣裘单。","引领紫霄极，飘飖如可干。","缅怀眉山公，五马来游盘。","酣兴走颠笔，苍崖即镵刊。","午年仲冬月，雪野云弥漫。","扫石坐舒啸，惠泉烹凤团。","当时诧盛集，千古陋逵安。","俛仰迹遂陈，斯人久泥蟠。","我来后千日，逸躅何由攀。","遇胜不能赋，俯寻尘路还。","山英移未勒，时款白云关。"]},{"t":"游庄严寺园","f":"七言绝句","c":["石楠花落小池清，独下平桥弄扇行。","蔽日绿阴无觅处，不如归去两三声。"]},{"t":"游灵壁兰皋园","f":"五言古诗","c":["集仙昔荣养，卜筑循兰陔。","深径万株合，清池百亩开。","飞梁荫菡萏，攒栋跨崔嵬。","淮海斸红药，潇湘移翠栽。","岱松佩萝茑，海石糊莓苔。","车马远惊聒，鱼鸟忘嫌猜。","病客倦舟楫，寻春此裴徊。","闰年物候迟，前日已闻雷。","薄景未晞雪，东风新破梅。","主人京洛旧，杖屦容参陪。","指我艮隅地，方营秋月台。","眼明壁间字，醉墨题东莱。","短句颇清绝，早推能赋才。","殷勤卷白苧，为尔拂尘埃。","安得一携手，更倾林下杯。","酒阑话平昔，岂复顾形骸。","行役浸相远，人生信悠哉。","薄暮重回首，长哦归去来。"]},{"t":"游盱眙南山示杨介","f":"五言古诗","c":["霜晓无轻飔，长淮净如眼。","招携南山游，老子兴不浅。","不从千步桥，飞度一渔舠。","中流鼓素楫，鲂鱮欻惊跳。","禅叟延游客，匆匆问行色。","千里远京关，浮骖去安适。","长啸指沧浪，濯缨湔我裳。","朱门曳裾地，槐柳自成行。","多年困靴板，未立中人产。","沈痼迫衰迟，求田咄何晚。","神丸傥驻延，投此寄馀年。","凿室邻杨氏，然薪系太玄。"]},{"t":"游金陵雨花台","f":"五言古诗","c":["迢迢朱雀航，飞盖共淩越。","东风石子冈，芳草微径绝。","生公法堂在，清夜贮明月。","回认城郭游，春华烂晴雪。","长烟动江隩，微云泊山胁。","连樯去迟回，白鸟屡明灭。","江山信清丽，人物久销歇。","戍堡定荒凉，投身计何拙。","尘衫与汗马，端为老生设。","李侯朱门俊，许与尽时哲。","俛首就微班，刚肠颇摧折。","人生特眠饭，似是此身切。","岁晚赋归田，非君复谁结。"]},{"t":"登头陀寺峰顶庵","f":"七言律诗","c":["磴道淩虚挂白虹，头陀上方黄鹄东。","沧溟五夜浴新日，老木三伏来凄风。","北梦南云展张阔，纵江横汉并吞雄。","楚乡绝境此其一，付与微吟多病翁。"]},{"t":"登黄楼有怀苏眉山","f":"词","c":["登黄楼，望黄州，黄州望不见，楼下水东流。","水流何可留，浮云更悠悠。","伤心泽畔客，憔悴楚兰秋。"]},{"t":"答许景亮","f":"七言古诗","c":["东嘉海上孕瑰怪，之子人英晦当代。","发之辞章聊一噫，雷鼓霜钟警聋聩。","投吾夜光敢不拜，相期过高幸少杀。","君家风鉴严简汰，顾吾衰迟积尪瘵。","久隐墙东慕牛侩，绝望仲华安石辈。","老矣狂奴犹故态，清思屡遭俗子败。","絮衣棘径动罥碍，京尘浼人更难奈。","行拿一舟犯滂湃，五斗无馀杂糠稗。","全家饫飧云梦䔇，黄鹤登临指天外。","燕子西飞书可待，访吾少明安好在。"]},{"t":"答杜仲观登丛台见寄","f":"五言古诗","c":["高风荡河汉，白露被寒菊。","下有络纬虫，凄酸生意促。","华年不相待，去我何流速。","老步失腾骧，短辕甘局蹙。","伊人濮阳秀，方厌折腰辱。","仕道塞榛芜，低徊避蚖蝮。","邯郸古都会，陈迹武灵筑。","兴发即登临，西南几穷目。","新诗琢璠琰，叠寄两三幅。","一听郢中歌，阳春回草木。","行将及瓜代，暂喜摆羁束。","鞭马径相过，连朝奉游瞩。","只鸡与斗黍，礼意未为足。","何以遇高阳，多营瓮头醁。"]},{"t":"答陈传道五首 其一","f":"五言绝句","c":["客子厌京尘，长街风眯目。","安得卧南阳，清潭渍寒菊。"]},{"t":"答陈传道五首 其四","f":"五言绝句","c":["闻有高秋兴，清樽醉飞鸿。","应悲故人远，薄晚面西风。"]},{"t":"答靳生","f":"词","c":["轩轩陆士龙，卓卓荀鸣鹤。","云间日下逢，此段殊不恶。","方君嗜狂药，而吾穷病缚。","相望不相过，赋诗聊尔谑。","知君酒隐慕先贤，谁何合作饮中仙。","金陵妙唱丹砂弦，当日新声传不传。","莫学沧波弄云月，老鲛哆口馋流涎。","访吾之居在何许，春明门东大道边。","青鞋布袜不妨步，何待东家蹇驴乃著鞭。","我屋真无坐客毡，蒲团柽机共萧然。","斗鸡走狗春风颠，付与垣东恶少年。"]},{"t":"答僧讷","f":"七言古诗","c":["唐代衣冠高四姓，天宗之亚荥阳郑。","不坠家声五百年，桂籍相望三叶庆。","上人猛谢区中缘，破冠投栉还童颠。","寸灰已灭五经笥，来入辨才无碍禅。","我窃官粮众人后，相逢宛是平生旧。","一闻南国白头吟，万愧西风碧云陋。","老鹤终辞鸡鹜群，谁将断绠绊浮云。","它日传衣度梅岭，解留何语与将军。"]},{"t":"感兴六首 其六","f":"五言绝句","c":["扁舟彼何人，国霸始谋身。","不知钓鱼翁，羞作故人臣。"]},{"t":"感兴六首 其五","f":"五言绝句","c":["庙堂击鲜食，日负天下责。","不知五湖上，自有扁舟客。"]},{"t":"感兴六首 其四","f":"五言绝句","c":["猎儿燕楚俗，得意唯驰逐。","不知庙堂上，坐饱万钱肉。"]},{"t":"感兴六首 其三","f":"五言绝句","c":["皂雕狞觜爪，飞走披肝脑。","不知游猎儿，必尔韝上老。"]},{"t":"感庭枣","f":"五言古诗","c":["昔来华纂纂，遽许实离离。","西风会摇落，行复见空枝。","岁物感流驶，事功伤暮迟。","咄彼身后名，前人端自欺。","书殚南山竹，奄奄定何知。","贤哉张生翰，千载与心期。"]},{"t":"腰疼山浮图下作","f":"五言古诗","c":["兹山非峻极，名不载图谱。","投策一攀跻，未觉病腰膂。","苍松带寒日，交阴层窣堵。","俨然黄面师，粉绘色已古。","我贪五斗米，磬折向儿乳。","复著鞍马劳，疲筋剧笞楚。","此身异金石，能涉几寒暑。","诛茅结圆庐，宴坐此其所。","清心日焚诵，庶拔未来苦。","望尘彼何人，碌碌安足数。"]},{"t":"酬别盱眙杜舆","f":"五言古诗","c":["君希谢太傅，筑室卧东山。","应携玉人去，为问何时还。","扁舟欲之东，霜落江潮悭。","难从京口渡，且转广陵湾。","与君合复离，恍若愁梦间。","婴疾再寒暑，医师怜我顽。","颓龄未遽尽，解组誓投闲。","幽岩有芳桂，晚岁约同攀。"]},{"t":"潘豳老以长篇求假吾书以副本送之","f":"七言律诗","c":["元凯有言君盍知，借书还书皆可嗤。","家传五载亦勤矣，吾与两雏当共之。","吏役岂容方外驾，古人端在个中期。","聊分副本天随子，辑缀来归是一奇。"]},{"t":"题乌江汤泉寄老庵","f":"五言古诗","c":["西庵松竹深，薄暮更微雨。","山禽不畏人，嘲哳方对语。","而余倦宦者，罢日今可数。","京邑夙所怀，其如恶尘土。","行复念斯游，回头怅何许。"]},{"t":"题天清寺安上人北轩","f":"五言古诗","c":["南城繁氏台，维昔孝王筑。","歌吟寂无闻，万楹联佛屋。","道人开北牖，俯就百乔木。","八月鸣青蝉，槐蛾委平绿。","客来借榻卧，吹睡俄顷足。","疏雨隔斜阳，垂虹跨长陆。","良游怅迟后，回谢三庚酷。","瘦马尾华轩，汗颜尘一掬。","昨非勿复道，佳约犹可续。","载酒定何时，新黄糁庭菊。"]},{"t":"题兰陵王碑阴","f":"五言古诗","c":["齐室生武贤，兰陵乃颇牧。","析瓜飨虎士，餍饫比粱肉。","金墉免胄战，破阵何神速。","乐府有遗声，当歌凯旋曲。","盘宗既不寿，霸祚宜尔促。","十代六百年，人间换陵谷。","荒途接幽垄，谁复禁樵牧。","窆石半攲摧，钩锄断鳌足。","苍苔蚀瑑刻，仰睇眩尘目。","操翰无愧辞，千言不为辱。","流湍齧马鬣，客土日危蹙。","霪潦并年间，弥漫即川陆。","昔多万两送，今无一抔筑。","人生妄区别，共尽同草木。","何待雍门弹，令君泪盈匊。"]},{"t":"题叶翰林道卿手书唐人唱和集后","f":"七言绝句","c":["翰客文房万卷馀，诜诜翻是蠹书鱼。","载薰载曝徒为尔，秦筑长城错备胡。"]},{"t":"题汉阳招真亭","f":"词","c":["大别山颠清沔尾，飞亭岧峣带云起。","清狂使君初燕喜，拍手招呼黄鹤子。","玄津炼出太阳酥，手葺胎发蒙头颅。","每誇久落北酆籍，岂意赍恨归黄垆。","越客登临兴何有，愁不能言病妨酒。","残阳云梦窅然深，尚欲开襟吞八九。","羽驾飘飖安在哉，使君馀迹已尘埃。","但见庾令楼横烟树杪，角声催月渡江来。"]},{"t":"题汉阳寓舍老桑","f":"七言绝句","c":["曾无沃若饱吴蚕，腹蠹聊供啄木馋。","底事殷勤谚元绪，不应有意附炎炎。"]},{"t":"题华阳公主碑阴","f":"五言古诗","c":["王姬乘凤去，春色一朝空。","昔怨绮罗月，今无松柏风。","千年见白日，狐穴入幽宫。","玉镜古尘满，落梅谁复容。","峨峨当隧碑，宝刻一何工。","文擅色丝美，但书膏邑封。","惜非丈夫烈，不得传无穷。","好在故时物，清漳流自东。"]},{"t":"题巫山图","f":"五言律诗","c":["巫山彼美神，秀色发朝云。","绚丽不可挹，飘飖去无痕。","楚梦一夕后，苍山秋复春。","目断肠亦断，往来今古人。"]},{"t":"题武昌郑判官直节亭","f":"五言古诗","c":["开亭榜直节，宠尔青琅玕。","岁晚傲霜雪，不同天下寒。","挺立百丈夫，被之古衣冠。","春华白粉泽，正色莫敢干。","越客与登览，微吟复长叹。","六鳌方抃戏，云海翻狂澜。","傥逢龙伯公，何惮剪一竿。","岐山鸣凤雏，久刷五色翰。","何以慰朝饥，美实来加餐。","高材陋时用，自持良独难。","不愿裁乐管，伶伦非古官。","浪遭野王辈，三弄为人欢。","愿制杀青简，灿然漆与丹。","褒贬约鲁史，终古垂不刊。","顾此托根地，辱哉久泥蟠。"]},{"t":"题诗卷后","f":"七言绝句","c":["诗岂穷人穷者工，斯言闻诸六一翁。","端惭少作老更拙，不废汝诗吾固穷。"]},{"t":"题毗陵僧舍二首 其二","f":"七言绝句","c":["秋风忽起家山意，流落天涯叹憔悴。","古寺不挂寰瀛图，终南山翁何处至。"]},{"t":"题香社寺平痾汤泉","f":"五言古诗","c":["骊山御汤殿，岁久玉莲倾。","谁谓大江北，有泉温且清。","相传白云窦，中閟丹砂英。","澡濯浃肌骨，沉痾亟能平。","岂特涤吾足，径当洁吾缨。","筑庐俯源上，涵泳凫鸥轻。","非复罜尘网，御风朝玉京。","赋诗投楚泽，用吊怀沙生。"]},{"t":"题海陵开元寺栖云庵","f":"五言古诗","c":["道人犹浮云，发彼王屋岑。","朝见肤寸合，暮为四海霖。","造物一戏耳，浮云本无心。","永谢应龙召，深栖双树林。","苍生热恼地，千载仰慈阴。","皎月示弦晦，清风何古今。","谁举甘露颂，轰然海潮音。","支离病居士，和以无弦琴。"]},{"t":"题海陵寓舍四首 其二","f":"七言律诗","c":["近湿篱根歌蟪蛄，向明屋角网蜘蛛。","黄葵紫苋雨张王，花蚊白蚁风驱除。","辗转犹憎夏夜久，支离何堪春病馀。","预愁还作旧年调，两眼京尘怀镜湖。"]},{"t":"题陶靖节集后","f":"五言古诗","c":["渊明不乐仕，解组归柴桑。","溯风北窗下，坦腹傲羲皇。","储粟既屡空，乞食何惶惶。","有身即大患，斯语闻伯阳。","顾我亦多忤，丘樊思退藏。","惭无辟粒术，圭勺耗官仓。"]},{"t":"题崇胜寺无心庵","f":"五言律诗","c":["老鹤依林表，孤云寓山间。","结茅穷释子，著身如许闲。","有心即尘纷，无心犹石顽。","有无心并置，日暮客来还。"]},{"t":"题黄冈东坡潘氏亦颜斋","f":"词","c":["东坡有田谁料理，黧面苍毛潘氏子。","结茅题榜亦颜斋，农隙把书聊自喜。","潘乎潘乎信是颜之徒，终日何所论难真如愚。","世无孔父四科友，犹办箪食瓢饮陋巷环墙居。","百亩之收粒可数，天南有待东坡主。","更输什一补官仓，馀勺几何供雀鼠。","会须不改其乐媚而翁，力田水旱由天公。","大胜心迹相违阮校尉，东西南北哭途穷。"]},{"t":"题潘大临东轩","f":"五言古诗","c":["陈公少荒诞，一室未遽扫。","事功竟何成，老魅死不早。","潘郎治寓舍，帚秃无遗蚤。","庭砌莳兰萱，未霜除恶草。","明窗羃轻素，朝日上杲杲。","烟蔓擢薰炉，松腴浮墨沼。","著书析鲁史，百传见脱藁。","贼乱久逋诛，吾方力穷讨。","不应两观下，仅获少正卯。","坐可骄素臣，俾渠眸子瞭。","而翁晏退食，笔削日课了。","伯仲咏南陔，馀风飒林杪。","安知自娱适，聊尉堂上老。","起居侍杖藜，寒燠躬炀澡。","昏定仰屋眠，是中亦大好。"]},{"t":"燕子楼","f":"五言古诗","c":["城据山川胜，千年楚故都。","高楼临汴水，杨柳荫芙蕖。","唐室中多故，将军老镇徐。","毬场朝戏马，玉帐夜投壶。","白雪徵清唱，黄金得绿珠。","春风楼上宴，三日极欢娱。","红粉梦云散，白杨兵火馀。","当年贺厦燕，老尽几番雏。","曲径拥黄叶，西风时扫除。","寒鸱蹲老树，睥睨女墙狐。","有客晚登览，徬徨思壮图。","荆榛闭铜雀，麋鹿游姑苏。","陈迹岂足道，旧欢何日无。","朱栏开酒场，宝勒迎官奴。","醉袖舞鸲鹆，艳声歌鹧鸪。","迟留故时月，桂影来座隅。","回首一相诧，今人如不如。"]},{"t":"赠赵参军滂","f":"楚辞体","c":["髯参军，髯参军，平昔相好书相闻。","妙兼八法嗤五云，一字仅课三年勤。","春回玉树生兰筋，骅骝气压千羸群。","庾家之鸡安足云，君子砚渔而笔耘，桓扇兮羊裙。","奈何不书蕊珠秘录之真文，宝厨钿轴缄灵芸。","阆居清绝无世纷，谁其观者紫阳君。","后日人间偶流落，犹得标题持键钥。"]},{"t":"赠道士蹇拱辰","f":"词","c":["尝观妙手御风图，想像斯人世所无。","今识黄冠葆光子，爽气飘飖画不如。","岷峨东来九千里，眼饱高山与流水。","乘春更拟访天台，晨肇当年偶然耳。","葆光子，胡为乎，鼎中龙虎炼成宝，笔下鬼神驱作奴。","须君且置是等事，三复玄元皇帝书。"]},{"t":"赠僧孚","f":"七言古诗","c":["北道交游窦了然，手持丹诀口谈禅。","吾年方少不解事，贪酒放歌相助癫。","十载驱车道梁楚，汴水之阳一环堵。","著书直上窥鬻熊，郑圃漆园聊尔汝。","旋闻瞥作去乡行，声迹相辽扫风雨。","我遭官缚未渠央，君割尘缘遽如许。","扁舟三月溯长川，故人投谒俄童颠。","周妻何肉败吾事，成佛定输灵运先。","此行历涉佳山水，随牒不妨行乐耳。","与君更结莲社游，径取盂囊付舟尾。"]},{"t":"鹦鹉洲","f":"五言古诗","c":["鹦鹉陇下鸟，能语奇羽毛。","罗罻巧相致，雕笼关鐍牢。","长怀故园树，烟雨落空巢。","万里迁泽国，舟舆□□劳。","正平托物赋，健笔不停操。","千载访陈躅，晴沙葭菼高。","珍禽不复见，慨想若人豪。","处士起河朔，英风拔时髦。","文章俪坟诰，俛就犹诗骚。","儿汝命杨孔，奴兵视刘曹。","奸雄可奈此，束之投楚郊。","忤俗竟非命，惜哉时不遭。","非无择木智，天下方滔滔。","遗干泯鱼腹，浮魂谁复招。","近结屈平好，佩兰杂申椒。","远惭子胥烈，怒气翻秋涛。","空馀春草碧，恨血满江皋。"]},{"t":"马上重经旧游六言","f":"词","c":["浅浅东流宛溪，当年罢酒分携。","认得桥边杨柳，春风几度鸦啼。"]},{"t":"题画卷后六言二首 其一 关路逢僧图","f":"词","c":["蹇驴乌帽禅客，落日黄尘故关。","已悔弃繻昔去，更逢挈履今还。"]},{"t":"题画卷后六言二首 其二 鸣琴召鹤图","f":"词","c":["结茅百尺荒台，杖藜一径莓苔。","谢绝鸡群老鹤，不应端为琴来。"]},{"t":"题惠崇画扇六言二首 其一 梅花雪雀","f":"词","c":["春雪霏霏晚梅，抱枝寒雀毰毸。","陇下有人肠断，为衔芳信东来。"]},{"t":"题惠崇画扇六言二首 其二 秋水芦雁","f":"词","c":["塞南秋水陂塘，芦叶萧萧半黄。","直北飞来鸿雁，端疑个是潇湘。"]},{"t":"七娘子 □□□","f":"词","c":["□波飞□□□向。","□□□、□□□□样。","拥鼻微吟，捋须遐想。","□□□□□□上。","会须加数□□酿。","□□□、□□□□涨。","美满孤帆，轻便双桨。","中分□□□□往。"]},{"t":"好女儿四首 其二 九回肠","f":"词","c":["削玉销香。","不喜浓妆。","倚高楼、望断章台路，但垂杨永巷，落花微雨，芳草斜阳。","赖有雕梁新燕，试寻访，武陵狂。","小华笺、付与西飞去，印一双愁黛，再三归字，□九回肠。"]},{"t":"人南渡/感皇恩 人南渡","f":"词","c":["兰芷满芳洲，游丝横路。","罗袜尘生步。","迎顾。","整鬟颦黛，脉脉两情难语。","细风吹柳絮。","人南渡。","回首旧游，山无重数。","花底深朱户。","何处。","半黄梅子，向晚一帘疏雨。","断魂分付与。","春将去。"]},{"t":"下水船","f":"词","c":["芳草青门路。","还拂京尘东去。","回想当年离绪。","送君南浦。","愁几许。","尊酒流连薄暮。","帘卷津楼风雨。","凭阑语。","草草蘅皋赋。","分首惊鸿不驻。","灯火虹桥，难寻弄波微步。","漫凝伫。","莫怨无情流水，明月扁舟何处。"]},{"t":"于飞乐","f":"词","c":["日薄云融。","满城罗绮芳丛。","一枝粉淡香浓。","几销魂，偏健羡、紫蝶黄蜂。","繁华梦断，酒醒来、扫地春空。","武陵原、回头何处，情随流水无穷。","寄两行清泪，想几许残红。","惜花人老，年年奈、依旧东风。"]},{"t":"千叶莲/鹧鸪天 千叶莲","f":"词","c":["闻你侬嗟我更嗟。","春霜一夜扫秾华。","永无清啭欺头管，赖有浓香著臂纱。","侵海角，抵天涯。","行云谁为不知家。","秋风想见西湖上，化出白莲千叶花。"]},{"t":"忆秦娥 子夜歌","f":"词","c":["三更月。","中庭恰照梨花雪。","梨花雪。","不胜凄断，杜鹃啼血。","王孙何许音尘绝。","柔桑陌上吞声别。","吞声别。","陇头流水，替人呜咽。"]},{"t":"小重山 □□□","f":"词","c":["隔水桃花□□□。","□□□□□，□□□。","□妆飞鹊镜台前。","□□□，□□□□□。","□首已依然。","断云疏雨后，更闻蝉。","□□□叶付漪涟。","驰寄与，人住玉溪边。"]},{"t":"小重山","f":"词","c":["一叶西风生嫩凉。","彩舟旗影动，背斜阳。","溪流几曲似回肠。","高城远，今夜为谁长。","正节号清狂。","苎萝标韵美，倚新妆。","月华歌调转清商。","尊酒畔，好住伴刘郎。"]},{"t":"小重山 其一","f":"词","c":["玉指金徽一再弹。","新声传访戴，雪溪寒。","两行墨妙破冰纨。","牵情处，幽恨寄毫端。","昵语强羞难。","相逢真许似，镜中鸾。","小梅疏影近杯盘。","东风里，谁共倚阑干。"]},{"t":"小重山","f":"词","c":["飘径梅英雪未融。","芳菲消息到，杏梢红。","隔年欢事水西东。","凝思久，不语坐书空。","回想夹城中。","彩山箫鼓沸，绮罗丛。","钿轮珠网玉花骢。","香陌上，谁与斗春风。"]},{"t":"小重山","f":"词","c":["花院深疑无路通。","碧纱窗影下，玉芙蓉。","当时偏恨五更钟。","分携处，斜月小帘栊。","楚梦冷沈踪。","一双金缕枕，半床空。","画桥临水凤城东。","楼前柳，憔悴几秋风。"]},{"t":"小重山 其二","f":"词","c":["帘影新妆一破颜。","玳筵回雪舞，小云鬟。","琼枝擢秀望难攀。","凝情处，千里望蓬山。","歌断酒阑珊。","画船箫鼓转，绿杨湾。","坠钿残燎水堂关。","斜阳里，双燕伴人闲。"]},{"t":"小重山 其四","f":"词","c":["月月相逢只旧圆。","迢迢三十夜，夜如年。","伤心不照绮罗筵。","孤舟里，单枕若为眠。","茂苑想依然。","花楼连苑起，压漪涟。","玉人千里共婵娟。","清琴怨，肠断亦如弦。"]},{"t":"小重山 其三","f":"词","c":["枕上阊门五报更。","蜡灯香灺冷，恨天明。","青苹风转彩帆轻。","樯头燕，多谢伴人行。","临镜想倾城。","两尖愁黛浅，泪波横。","艳歌重记遣离情。","缠绵处，翻是断肠声。"]},{"t":"小梅花/梅花引","f":"词","c":["思前别。","记时节。","美人颜色如花发。","美人归。","天一涯。","娟娟姮娥，三五满还亏。","翠眉蝉鬓生离诀。","遥望青楼心欲绝。","梦中寻。","卧巫云。","觉来珠泪，滴向湘水深。","愁无已。","奏绿绮。","历历高山与流水。","妙通神。","绝知音。","不知暮雨朝云、何山岑。","相思无计堪相比。","珠箔雕阑几千里。","漏将分。","月窗明。","一夜梅花忽开、疑是君。"]},{"t":"乌啼月/乌夜啼","f":"词","c":["牛女相望处，星桥不碍东西。","重墙未抵蓬山远，却恨画楼低。","细字频传幽怨，凝缸长照单栖。","城乌可是知人意，偏向月明啼。"]},{"t":"六州歌头","f":"词","c":["少年侠气，交结五都雄。","肝胆洞。","毛发耸。","立谈中。","死生同。","一诺千金重。","推翘勇。","矜豪纵。","轻盖拥。","联飞鞚。","斗城东。","轰饮酒垆，春色浮寒瓮。","吸海垂虹。","闲呼鹰嗾犬，白羽摘雕弓。","狡穴俄空。","乐匆匆。","似黄粱梦。","辞丹凤。","明月共。","漾孤篷。","官冗从。","怀倥偬。","落尘笼。","簿书丛。","鹖弁如云众。","供粗用。","忽奇功。","笳鼓动。","渔阳弄。","思悲翁。","不请长缨，系取天骄种。","剑吼西风。","恨登山临水，手寄七弦桐。","目送归鸿。"]},{"t":"胜胜慢二首 其二 凤求凰","f":"词","c":["园林幂翠，燕寝凝香。","华池缭绕飞廊。","坐按吴娃清丽，楚调圆长。","歌阑横流美眄，乍疑生、绮席辉光。","文园属意，玉觞交劝，宝瑟高张。","南薰难销幽恨，金徽上，殷勤彩凤求凰。","便许卷收行雨，不恋高唐。","东山胜游在眼，待纫兰、撷菊相将。","双栖安隐，五云溪是故乡。"]},{"t":"凤栖梧/蝶恋花","f":"词","c":["独立江东人婉娈。","粉本花真，千里依稀见。","闲弄彩毫濡玉砚。","缠绵春思□歌扇。","爱我竹窗新句炼。","小砑绫笺、偷寄西飞燕。","乍可问名赊识面。","十年多病风情浅。"]},{"t":"凤栖梧/蝶恋花","f":"词","c":["挑菜踏青都过却。","杨柳风轻，摆动秋千索。","啼鸟自惊花自落。","有人同在真珠箔。","淡净衣裳妆□薄。","闲凭银筝，睡鬓慵梳掠。","试问为谁添瘦弱。","娇羞只把眉颦著。"]},{"t":"凤栖梧/蝶恋花","f":"词","c":["为问宛溪桥畔柳。","拂水倡条，几赠行人手。","一样叶眉偏解皱。","白绵飞尽因谁瘦。","今日离亭还对酒。","唱断青青，好去休回首。","美荫向人疏似旧。","何须更待秋风后。"]},{"t":"天门谣","f":"词","c":["牛渚天门险，限南北、七雄豪占。","清雾敛，与闲人登览。","待月上潮，平波滟滟，塞管轻吹新阿滥。","风满槛，历历数、西州更点。"]},{"t":"天宁乐/金人捧露盘","f":"词","c":["斗储祥，虹流祉，兆黄虞。","未□□、□圣真符。","千龄叶应，九河清、神物出龟图。","□□□□，□盛时、朝野欢娱。","靡不覆，旋穹□，□□□，□坤舆。","致万国、一变华胥。","霞觞□□，□□□、□□□宸趋。","五云长在，望子□、□□□□。"]},{"t":"忆仙姿/如梦令 其八","f":"词","c":["江上潮回风细。","红袖倚楼凝睇。","天际认归舟，但见平林如荠。","迢递。","迢递。","人更远于天际。"]},{"t":"忆仙姿/如梦令 其四","f":"词","c":["罗绮丛中初见。","理鬓横波流转。","半醉不胜情，帘影犹招歌扇。","留恋。","留恋。","秋夜辞巢双燕。"]},{"t":"忆仙姿/如梦令 其三","f":"词","c":["相见时难别易。","何限玉琴心意。","眉黛只供愁，羞见双鸳鸯字。","憔悴。","憔悴。","蜡烛销成红泪。"]},{"t":"忆仙姿/如梦令 其九","f":"词","c":["梦想山阴游冶。","深径碧桃花谢。","曲水稳流觞，暖絮芳兰堪藉。","萧洒。","萧洒。","月棹烟蓑东下。"]},{"t":"忆仙姿/如梦令 其五","f":"词","c":["雨后一分春减。","深院落红如糁。","柳外出秋千，度日彩旗风飐。","销黯。","销黯。","门共宝奁长掩。"]},{"t":"忆仙姿/如梦令","f":"词","c":["莲叶初生南浦。","两岸绿杨飞絮。","向晚鲤鱼风，断送彩帆何处。","凝伫。","凝伫。","楼外一江烟雨。"]},{"t":"忆仙姿/如梦令","f":"词","c":["日日春风楼上。","不见石城双桨。","鸳枕梦回时，烛泪屏山相向。","流荡。","流荡。","门外白苹溪涨。"]},{"t":"忆仙姿/如梦令 其六","f":"词","c":["柳下玉骢双鞚。","蝉鬓宝钿浮动。","半醉倚迷楼，聊送斜阳三弄。","豪纵。","豪纵。","一觉扬州春梦。"]},{"t":"忆仙姿/如梦令 其七","f":"词","c":["何处偷谐心赏。","促坐绮罗筵上。","不记下楼时，醉□月侵书幌。","怀想。","怀想。","清丽歌声妆样。"]},{"t":"忆仙姿/如梦令","f":"词","c":["彩舫解维官柳。","楼上谁家红袖。","团扇弄微风，如为行人招手。","回首。","回首。","云断武陵溪口。"]},{"t":"忆仙姿/如梦令","f":"词","c":["白纻春衫新制。","准拟采兰修禊。","遮日走京尘，何啻分阴如岁。","留滞。","留滞。","不似行云难系。"]},{"t":"忆秦娥 其二","f":"词","c":["风惊幕。","灯前细雨檐花落。","檐花落。","玉台清镜，泪淹妆薄。","良时不再须行乐。","王孙莫负东城约。","东城约。","一分春色，为君留著。"]},{"t":"忆秦娥 其一","f":"词","c":["晓朦胧。","前溪百鸟啼匆匆。","啼匆匆。","凌波人去，拜月楼空。","去年今日东门东。","鲜妆辉映桃花红。","桃花红。","吹开吹落，一任东风。"]},{"t":"忆秦娥 其三","f":"词","c":["著春衫。","玉鞭鞭马南城南。","南城南。","柔条芳草，留驻金衔。","粉娥采叶供新蚕。","蚕饥略许携纤纤。","携纤纤。","湔裙淇上，更待初三。"]},{"t":"月先圆/好女儿 其三 月先圆","f":"词","c":["才色相怜。","难偶当年。","屡逢迎、几许缠绵意，记秋千架底，摴蒲局上，祓禊池边。","收贮一春幽恨，细书遍、砑绫笺。","算蓬山、未抵屏山远，奈碧云易合，彩霞深闭，明月先圆。"]},{"t":"木兰花/玉楼春","f":"七言律诗","c":["银簧雁柱香檀拨。","镂板三声催细抹。","舞腰轻怯绛裙长，羞按筑球花十八。","东城柳岸匆匆发。","画舫一篙烟水阔。","可怜单枕欲眠时，还见尊前前夜月。"]},{"t":"木兰花/玉楼春","f":"七言律诗","c":["佩环声认腰肢软。","风里麝熏知近远。","此身常羡玉妆台，得见晓来梳画面。","回廊几步通深院。","一桁绣衣帘不卷。","酒阑歌罢欲黄昏，肠断归巢双燕燕。"]},{"t":"木兰花/玉楼春","f":"七言律诗","c":["嫣然何啻千金价。","意远态闲难入画。","更无方便只尊前，说尽牵情多少话。","别来乐事经春罢。","枉度佳春抛好夜。","如今触绪易销魂，最是不堪风月下。"]},{"t":"木兰花/玉楼春","f":"七言律诗","c":["朝来著眼沙头认。","五两竿摇风色顺。","佳期学取弄潮儿，人纵无情潮有信。","纷纷花雨红成阵。","冷酒青梅寒食近。","漫将江水比闲愁，水尽江头愁不尽。"]},{"t":"木兰花/玉楼春","f":"七言律诗","c":["罗襟粉汗和香浥。","纤指留痕红一捻。","离亭再卜合欢期，寻见石榴双翠叶。","危楼欲上危肠怯。","纵得鸾胶难寸接。","西风燕子会来时，好付小笺封泪帖。"]},{"t":"水调歌头","f":"词","c":["彼美吴姝唱，繁会阖闾邦。","千坊万井，斜桥曲水小轩窗。","缥缈关山台观。","罗绮云烟相半。","金石压掁撞。","痴信东归虏，黑自死心降。","范夫子，高标韵，秀眉庞。","功成长往，有人同载世无双。","物外聊从吾好。","赖尔工颦妍笑。","伴醉玉连缸。","尽任扁舟路，风雨卷秋江。"]},{"t":"风流子","f":"词","c":["何处最难忘。","方豪健，放乐五云乡。","彩笔赋诗，禁池芳草，香鞯调马，辇路垂杨。","绮筵上，扇偎歌黛浅，汗浥舞罗香。","兰烛伴归，绣轮同载，闭花别馆，隔水深坊。","零落少年场。","琴心漫流怨，带眼偷长。","无奈占床燕月，侵鬓吴霜。","念北里音尘，鱼封永断，便桥烟雨，鹤表相望。","好在后庭桃李，应记刘郎。"]},{"t":"清商怨三首 其二 东阳叹","f":"词","c":["流连狂乐恨景短。","奈夕阳送晚。","醉未成欢，醒来愁满眼。","东阳销瘦带展。","望日下、旧游天远。","泪洒春风，春风谁复管。"]},{"t":"东吴乐/尉迟杯","f":"词","c":["胜游地。","信东吴绝景饶佳丽。","平湖底，见层岚，凉月下，闻清吹。","人如秾李。","泛襟袂、香润苹风起。","喜凌波、素袜逢迎，领略当歌深意。","鄂君被。","双鸳绮。","垂杨荫，夷犹画舲相舣。","宝瑟弦调，明珠佩委。","回首碧云千里。","归鸿后、芳音谁寄。","念怀县、青鬓今无几。","枉分将、镜里华年，付与楼前流水。"]},{"t":"东邻妙/玉楼春","f":"七言律诗","c":["张灯结绮笼驰道。","六六洞天连夜到。","韶华吹断紫云回，怊怅人间新梦觉。","倾城犹记东邻妙。","尊酒相逢留一笑。","卢郎任老也多才，不数五陵狂侠少。"]},{"t":"更漏子三首 其三 付金钗","f":"词","c":["付金钗，平斗酒。","未许解携纤手。","吟警句，写清愁。","浮骖为少留。","旧游赊，新梦后。","月映隔窗疏柳。","闲砚席，剩衾绸。","今秋似去秋。"]},{"t":"鹧鸪天 半死桐","f":"词","c":["重过阊门万事非。","同来何事不同归。","梧桐半死清霜后，头白鸳鸯失伴飞。","原上草，露初晞。","旧栖新垄两依依。","空床卧听南窗雨，谁复挑灯夜补衣。"]},{"t":"水调歌头 台城游","f":"词","c":["南国本潇洒。","六代浸豪奢。","台城游冶。","襞笺能赋属宫娃。","云观登临清夏。","璧月留连长夜。","吟醉送年华。","回首飞鸳瓦。","却羡井中蛙。","访乌衣，成白社。","不容车。","旧时王谢。","堂前双燕过谁家。","楼外河横斗挂。","淮上潮平霜下。","樯影落寒沙。","商女篷窗罅。","犹唱后庭花。"]},{"t":"失调名 其二","f":"词","c":["风头梦、吹无迹。"]},{"t":"失调名 其一","f":"词","c":["罗帷映月，玉研生冰。"]},{"t":"尔汝歌/清商怨 尔汝歌","f":"词","c":["劳生羁宦未易处。","赖醉□□□。","白眼青天，忘形相尔汝。","□□□□□□。","□□□，送君南浦。","雪暗沧江，□□□□□。"]},{"t":"踏莎行 其五 平阳兴","f":"词","c":["凉叶辞风，流云卷雨。","寥寥夜色沈钟鼓。","谁调清管度新声，有人高卧平阳坞。","草暖沧洲，潮平别浦。","双凫乘雁方容与。","深藏华屋锁雕笼，此生乍可输鹦鹉。"]},{"t":"归风便/玉楼春三首 其二 归风便","f":"七言律诗","c":["津亭薄晚张离燕。","红粉□歌持酒劝。","歌声煎泪欲沾襟，酒色□□□□□。","□□会有归风便。","休道相忘秋后□。","□□□抵故人心，惆怅故人心不见。"]},{"t":"玉连环/一落索 一落索","f":"词","c":["别酒更添红粉泪。","促成愁醉。","相逢浅笑合微吟，撩惹到、缠绵地。","花下解携重附耳。","佳期深记。","青翰舟稳绣衾香，谁禁断、东流水。"]},{"t":"玉京秋","f":"词","c":["陇首霜晴，泗滨云晚，乍摇落。","废榭苍苔，破台荒草，西楚霸图冥漠。","记登临事，九日胜游，千载如昨。","更想像，晋客□归，谢生能赋继高作。","飘泊。","尘埃倦客，风月羁心，潘鬓晓来清镜觉。","蜡屐纶巾，羽觞象管，且追随、隼旟行乐。","东山□，应笑个侬风味薄。","念故园黄花，自有年年约。"]},{"t":"石州引/石州慢","f":"词","c":["薄雨初寒，斜照弄晴，春意空阔。","长亭柳色才黄，远客一枝先折。","烟横水际，映带几点归鸦，东风销尽龙沙雪。","还记出关来，恰而今时节。","将发。","画楼芳酒，红泪清歌，顿成轻别。","已是经年，杳杳音尘多绝。","欲知方寸，共有几许清愁，芭蕉不展丁香结。","枉望断天涯，两厌厌风月。"]},{"t":"伤春曲/满江红 伤春曲","f":"词","c":["火禁初开，深深院、尽重帘箔。","人自起、翠衾寒梦，夜来风恶。","肠断残红和泪落。","半随经雨飘池角。","记采兰、携手曲江游，年时约。","芳物大，都如昨。","自怨别，疏行乐。","被无情双燕，短封难托。","谁念东阳销瘦骨。","更堪白纻衣衫薄。","向小窗、题满杏花笺，伤春作。"]},{"t":"江如练/蝶恋花","f":"词","c":["睡鸭炉寒熏麝煎。","寂寂歌梁，无计留归燕。","十二曲阑闲倚遍。","一杯长待何人劝。","不识当年桃叶面。","吟咏佳词，想像犹曾见。","两桨往来风与便。","潮平月上江如练。"]},{"t":"踏莎行 其三 度新声","f":"词","c":["小苑浴兰，微波寄叶。","石城回首山重沓。","绮窗烟雨梦佳期，飞霞艇子雕檀楫。","楼迥披襟，廊长响屧。","供愁麝月眉心帖。","紫箫闲捻度新声，有人偷倚阑干掐。"]},{"t":"踏莎行 其二 潇潇雨","f":"词","c":["鸦轧齐桡，□冬叠鼓。","浮骖晚下金牛渚。","莫愁应自有愁时，篷窗今夜潇潇雨。","杜若芳洲。","芙蓉别浦。","依依艳笑逢迎处。","随潮风自石城来，潮回好寄人传语。"]},{"t":"踏莎行 其一 江南曲","f":"词","c":["蝉韵清弦，溪横翠縠。","翩翩彩鹢帆开幅。","黄帘绛幕掩香风，当筵粲粲人如玉。","浅黛凝愁，明波转瞩。","兰情似怨临行促。","不辞寸断九回肠，殷勤更唱江南曲。"]},{"t":"江城子","f":"词","c":["麝熏微度绣芙蓉。","翠衾重。","画堂空。","前夜偷期，相见却匆匆。","心事两知何处问，依约是，梦中逢。","坐疑行听竹窗风。","出帘栊。","杳无踪。","已过黄昏，才动寺楼钟。","暮雨不来春又去，花满地，月朦胧。"]},{"t":"小梅花二首 其二 行路难","f":"词","c":["缚虎手。","悬河口。","车如鸡栖马如狗。","白纶巾。","扑黄尘。","不知我辈，可是蓬蒿人。","衰兰送客咸阳道。","天若有情天亦老。","作雷颠。","不论钱。","谁问旗亭，美酒斗十千。","酌大斗。","更为寿。","青鬓常青古无有。","笑嫣然。","舞翩然。","当垆秦女，十五语如弦。","遗音能记秋风曲。","事去千年犹恨促。","揽流光。","系扶桑。","争奈愁来，一日却为长。"]},{"t":"西江月","f":"词","c":["携手看花深径，扶肩待月斜廊。","临分少伫已伥伥。","此段不堪回想。","欲寄书如天远，难销夜似年长。","小窗风雨碎人肠。","更在孤舟枕上。"]},{"t":"凤栖梧三首 其二 西笑吟","f":"词","c":["桃叶园林风日好。","曲径珍丛，处处闻啼鸟。","翠珥金丸委芳草。","袜罗尘动香裙扫。","片帆乘兴东流早。","每话长安，引领犹西笑。","离索年多故人少。","江南有雁无书到。"]},{"t":"负心期/浣溪沙","f":"词","c":["节物侵寻迫暮迟。","可胜摇落长年悲。","回首五湖乘兴地，负心期。","惊雁失行风剪剪，冷云成阵雪垂垂。","不拼尊前泥样醉，个能痴。"]},{"t":"问歌颦/雨中花令 问歌颦","f":"词","c":["清滑京江人物秀。","富美发、丰肌素手。","宝子馀妍，阿娇馀韵，独步秋娘后。","奈倦客襟怀先怯酒。","问何意、歌颦易皱。","弱柳飞绵，繁花结子，做弄伤春瘦。"]},{"t":"伴云来/天香","f":"词","c":["烟络横林，山沈远照，逦迤黄昏钟鼓。","烛映帘栊，蛩催机杼，共苦清秋风露。","不眠思妇，齐应和、几声砧杵。","惊动天涯倦宦，骎骎岁华行暮。","当年酒狂自负。","谓东君、以春相付。","流浪征骖北道，客樯南浦。","幽恨无人晤语。","赖明月曾知旧游处。","好伴云来，还将梦去。"]},{"t":"中吕宫丑奴儿二首 其一 伴登临","f":"词","c":["中吴茂苑繁华地，冠盖如林。","桃李成阴。","若个芳心、真个会琴心。","高秋霁色清于水，月榭风襟。","且伴登临。","留与他年、尊酒话而今。"]},{"t":"渔家傲 其二 游仙咏","f":"词","c":["啸度万松千步岭。","钱湖门外非尘境。","见底碧漪如眼净。","岚光映。","镜屏百曲新磨莹。","好月为人重破瞑。","云头艳艳开金饼。","传语桂娥应耐静。","堪乘兴。","尊前听我游仙咏。"]},{"t":"吴门柳/渔家傲 其一 吴门柳","f":"词","c":["窈窕盘门西转路。","残阳映带青山暮。","最是长杨攀折苦。","堪怜许。","清霜剪断和烟缕。","春水归期端不负。","依依照影临南浦。","留取木兰舟少住。","无风雨。","黄昏月上潮平去。"]},{"t":"吹柳絮/瑞鹧鸪 吹柳絮","f":"七言律诗","c":["月痕依约到西厢。","曾羡花枝拂短墙。","初未识愁那得泪，每浑疑梦奈馀香。","歌逢袅处眉先妩，酒半酣时眼更狂。","闲倚绣帘吹柳絮，问何人似冶游郎。"]},{"t":"木兰花三首 其一 呈纤手","f":"七言律诗","c":["秦弦络络呈纤手。","宝雁斜飞三十九。","徵韶新谱日边来，倾耳吴娃惊未有。","文园老令难堪酒。","蜜炬垂花知夜久。","更须妩媚做腰肢，细学永丰坊畔柳。"]},{"t":"弄珠英/蓦山溪","f":"词","c":["楚乡新岁。","不放残寒退。","月晓桂娥闲，弄珠英、因风委坠。","清淮铺练，十二玉峰前，上帘栊，招佳丽。","置酒成高会。","江南芳信，目断何人寄。","应占镜边春，想晨妆、膏浓压翠。","此时乘兴，半道忍回桡，五云溪，门深闭。","璧月长相对。"]},{"t":"丑奴儿二首 其二 忍泪吟","f":"词","c":["十年一觉扬州梦，雨散云沈。","隔水登临。","扬子湾西夕照深。","当时玉管朱弦句，忍泪重吟。","半取沾襟。","饾饤西风□□□。"]},{"t":"更漏子","f":"词","c":["芳草斜曛。","映画桥□□，翠阁临津。","数阕清歌，两行红粉，厌厌别酒初醺。","芳意赠我殷勤。","罗巾双黛痕。","便兰舟独上，洞府人闲，素手轻分。","十里绮陌香尘。","望紫云车远，已掩青门。","迤逦黄昏，景阳钟动，临风隐隐犹闻。","明朝水馆渔村。","凭谁招断魂。","恨不如今夜，明月多情，应待归云。"]},{"t":"更漏子 □□□","f":"词","c":["酒三行，琴再弄。","宛是和鸣双凤。","罗斗帐，绣屏风。","浓香夜夜同。","去年欢，今夕梦。","怊怅晓钟初动。","休道梦，觉来空。","当时亦梦中。"]},{"t":"更漏子三首 其一 独倚楼","f":"词","c":["上东门，门外柳，赠别每烦纤手。","一叶落，几番秋，江南独倚楼。","曲阑干，凝伫久，薄暮更堪搔首。","无际恨，见闲愁，侵寻天尽头。"]},{"t":"减字浣溪沙七首 其四 杨柳陌","f":"七言古诗","c":["兴庆宫池整月开。","□□□□缕金鞋。","后庭芳草绿缘阶。","祓禊归□杨柳陌，□□□落凤凰钗。","细风抛絮入人怀。"]},{"t":"诉衷情令三首 其三 步花间","f":"词","c":["凭陵残醉步花间。","风绰佩珊珊。","踏青解红人散，不耐日长闲。","纤手指，小金环。","拥云鬟。","一声水调，两点春愁，先占眉山。"]},{"t":"太平时七首 其三 花幕暗","f":"词","c":["绿绮新声隔坐闻。","认殷勤。","尊前为舞郁金裙。","酒微醺。","月转参横花幕暗，夜初分。","阳台拼作不归云。","任郎嗔。"]},{"t":"武陵春 花想容","f":"词","c":["南国佳人推阿秀，歌醉几相逢。","云想衣裳花想容。","春未抵情浓。","津亭回首青楼远，帘箔更重重。","今夜扁舟泪不供。","犹听隔江钟。"]},{"t":"踏莎行七首 其四 芳心苦","f":"词","c":["杨柳回塘，鸳鸯别浦。","绿萍涨断莲舟路。","断无蜂蝶慕幽香，红衣脱尽芳心苦。","返照迎潮，行云带雨。","依依似与骚人语。","当年不肯嫁春风，无端却被秋风误。"]},{"t":"踏莎行 芳洲泊","f":"词","c":["露叶栖萤，风枝袅鹊。","水堂离燕褰珠箔。","一声横玉吹流云，厌厌凉月西南落。","江际吴边，山侵楚角。","兰桡明夜芳洲泊。","殷勤留语采香人，清尊不负黄花约。"]},{"t":"芳草渡/系裙腰","f":"词","c":["留征辔，送离杯。","羞泪下，捻青梅。","低声问道几时回。","秦筝雁促，此夜为谁排。","君去也，远蓬莱。","千里地，信音乖。","相思成病底情怀。","和烦恼，寻个便，送将来。"]},{"t":"诉衷情令 其二","f":"词","c":["半销檀粉睡痕新。","背镜照樱唇。","临风再歌团扇，深意属何人。","轻调笑，浅凝颦。","认情亲。","最难堪酒，似不胜情，依样伤春。"]},{"t":"诉衷情令 其一","f":"词","c":["不堪回首卧云乡。","羁宦负清狂。","年来镜湖风月，鱼鸟两相忘。","秦塞险，楚山苍。","更斜阳。","画桥流水，曾见扁舟，几度刘郎。"]},{"t":"连理枝","f":"词","c":["绣幌闲眠晓。","处处闻啼鸟。","枕上无情，斜风横雨，落花多少。","想灞桥、春色老于人，恁江南梦杳。","往事今何道。","聊咏池塘草。","怀县年来，萧萧壮发，可堪频照。","赖醉乡、佳境许徜徉，惜归欤不早。"]},{"t":"侍香金童","f":"词","c":["楚梦方回，翠被寒如水。","尚想见、扬州桃李。","姿秀韵闲何物比。","玉管秋风，漫声流美。","燕堂开，双按秦弦呈素指。","宝雁参差飞不起。","三五彩蟾明夜是。","屈曲阑干，断肠千里。"]},{"t":"卷春空/定风波 卷春空","f":"词","c":["墙上夭桃簌簌红。","巧随轻絮入帘栊。","自是芳心贪结子。","翻使。","惜花人恨五更风。","露萼鲜浓妆脸靓。","相映。","隔年情事此门中。","粉面不知何处在。","无奈。","武陵流水卷春空。"]},{"t":"好女儿四首 其一 国门东","f":"词","c":["车马匆匆。","会国门东。","信人间、自古销魂处，指红尘北道，碧波南浦，黄叶西风。","堠馆娟娟新月，从今夜、与谁同。","想深闺独守空床思，但频占镜鹊，悔分钗燕，长望书鸿。"]},{"t":"古捣练子 夜如年","f":"词","c":["斜月下，北风前。","万杵千砧捣欲穿。","不为捣衣勤不睡，破除今夜夜如年。"]},{"t":"古捣练子 夜捣衣","f":"词","c":["收锦字，下鸳机。","净拂床砧夜捣衣。","马上少年今健否，过瓜时见雁南归。"]},{"t":"夜游宫","f":"词","c":["江面波纹皱縠。","江南岸、草和烟绿。","初过寒食一百六。","采苹游，□香裙，鸣佩玉。","心事偷相属。","赋春恨、彩笺双幅。","今夜小楼吹凤竹。","谢东风，寄怀人，肠断曲。"]},{"t":"定情曲 春愁","f":"词","c":["沈水浓熏，梅粉淡妆，露华鲜映春晓。","浅颦轻笑。","真物外，一种闲花风调。","可待合欢翠被，不见忘忧芳草。","拥膝浑忘羞，回身就郎抱。","两点灵犀心颠倒。","念乐事稀逢，归期须早。","五云闻道。","星桥畔、油壁车迎苏小。","引领西陵自远，携手东山偕老。","殷勤制、双凤新声，定情永为好。"]},{"t":"六么令 宛溪柳","f":"词","c":["梦云萧散，帘卷画堂晓。","残薰尽烛隐映，绮席金壶倒。","尘送行鞭袅袅。","醉指长安道。","波平天渺。","兰舟欲上，回首离愁满芳草。","已恨归期不早。","枉负狂年少。","无奈风月多情，此去应相笑。","心记新声缥缈。","翻是相思调。","明年春杪。","宛溪杨柳，依旧青青为谁好。"]},{"t":"念良游/满江红","f":"词","c":["山缭平湖，寒飙扬、六英纷泊。","清镜晓、倚岩琪树，挠云朱阁。","窈窕缯窗褰翠幕，尊前皓齿歌梅落。","信醉乡、绝境待名流，供行乐。","时易失，今犹昨。","欢莫再，情何薄。","扁舟幸不系，会寻佳约。","想见徘徊华表下，个身似是辽东鹤。","访旧游、人与物俱非，空城郭。"]},{"t":"念离群/沁园春","f":"词","c":["宫烛分烟，禁池开钥，凤城暮春。","向落花香里，澄波影外，笙歌迟日，罗绮芳尘。","载酒追游，联镳归晚，灯火平康寻梦云。","逢迎处，最多才自负，巧笑相亲。","离群。","客宦漳滨。","但惊见、来鸿归燕频。","念日边消耗，天涯怅望，楼台清晓，帘幕黄昏。","无限悲凉，不胜憔悴，断尽危肠销尽魂。","方年少，恨浮名误我，乐事输人。"]},{"t":"念彩云/夜游宫 念彩云","f":"词","c":["流水苍山带郭。","寻尘迹、宛然如昨。","犹记黄花携手约。","误重来，小庭花，空自落。","不怨兰情薄。","可怜许、彩云漂泊。","紫燕西飞书漫托。","碧城中，几青楼，垂画幕。"]},{"t":"拥鼻吟/吴音子 吴音子","f":"词","c":["别酒初销，怃然弭棹蒹葭浦。","回首不见高城，青楼更何许。","大艑轲峨，越商巴贾。","万恨龙钟，篷下对语。","指征路。","山缺处，孤烟起，历历闻津鼓。","江豚吹浪，晚来风转夜深雨。","拥鼻微吟，断肠新句。","粉碧罗笺，封泪寄与。"]},{"t":"古捣练子 杵声齐","f":"词","c":["砧面莹，杵声齐。","捣就征衣泪墨题。","寄到玉关应万里，戍人犹在玉关西。"]},{"t":"河传 其二","f":"词","c":["华堂重厦，向尊前更听，碧云新怨。","玉指钿徽，总是挑人心眼。","恨随红蜡短。","彩旗影动船头转。","双桨凌波，惟念人留恋。","江上暮潮，隐隐山横南岸。","奈离愁、分不断。"]},{"t":"河传 其一","f":"词","c":["华堂张燕。","向尊前妙选，舞裙歌扇。","彼美个人，的的风流心眼。","恨寻芳来晚。","曲街灯火香尘散。","犹约晨妆，一觇春风面。","惆怅善和坊里，平桥南畔。","小青楼、帘不卷。"]},{"t":"河满子","f":"词","c":["每恨相逢薄处，可怜欲去迟回。","犹记新声团扇□，殷勤再引馀杯。","为问依依杨柳，秋风好住章台。","疏雨忽随云断，斜阳却送潮回。","桃叶青山长在眼，几时双楫迎来。","如待碧阑红药，一年两度花开。"]}]};